@click.pass_context
def main(
    ctx: click.Context,
    code: Optional[str],
    line_length: int,
    target_version: List[TargetVersion],
    check: bool,
    diff: bool,
    fast: bool,
    pyi: bool,
    py36: bool,
    skip_string_normalization: bool,
    quiet: bool,
    verbose: bool,
    include: str,
    exclude: str,
    src: Tuple[str, ...],
    config: Optional[str],
) -> None:
    """The uncompromising code formatter."""
    write_back = WriteBack.from_configuration(check=check, diff=diff)
    if target_version:
        if py36:
            err("Cannot use both --target-version and --py36")
            ctx.exit(2)
        else:
            versions = set(target_version)
    elif py36:
        err(
            "--py36 is deprecated and will be removed in a future version. "
            "Use --target-version py36 instead."
        )
        versions = PY36_VERSIONS
    else:
        # We'll autodetect later.
        versions = set()
    mode = Mode(
        target_versions=versions,
        line_length=line_length,
        is_pyi=pyi,
        string_normalization=not skip_string_normalization,
    )
    if config and verbose:
        out(f"Using configuration from {config}.", bold=False, fg="blue")
    if code is not None:
        print(format_str(code, mode=mode))
        ctx.exit(0)
    try:
        include_regex = re_compile_maybe_verbose(include)
    except re.error:
        err(f"Invalid regular expression for include given: {include!r}")
        ctx.exit(2)
    try:
        exclude_regex = re_compile_maybe_verbose(exclude)
    except re.error:
        err(f"Invalid regular expression for exclude given: {exclude!r}")
        ctx.exit(2)
    report = Report(check=check, diff=diff, quiet=quiet, verbose=verbose)
    root = find_project_root(src)
    sources: Set[Path] = set()
    path_empty(src, quiet, verbose, ctx)
    for s in src:
        p = Path(s)
        if p.is_dir():
            sources.update(
                gen_python_files_in_dir(
                    p, root, include_regex, exclude_regex, report, get_gitignore(root)
                )
            )
        elif p.is_file() or s == "-":
            # if a file was explicitly given, we don't care about its extension
            sources.add(p)
        else:
            err(f"invalid path: {s}")
    if len(sources) == 0:
        if verbose or not quiet:
            out("No Python files are present to be formatted. Nothing to do 😴")
        ctx.exit(0)

    if len(sources) == 1:
        reformat_one(
            src=sources.pop(),
            fast=fast,
            write_back=write_back,
            mode=mode,
            report=report,
        )
    else:
        reformat_many(
            sources=sources, fast=fast, write_back=write_back, mode=mode, report=report
        )

    if verbose or not quiet:
        out("Oh no! 💥 💔 💥" if report.return_code else "All done! ✨ 🍰 ✨")
        click.secho(str(report), err=True)
    ctx.exit(report.return_code)

def maybe_remove_trailing_comma(self, closing: Leaf) -> bool:
    """Remove trailing comma if there is one and it's safe."""
    if not (
        self.leaves
        and self.leaves[-1].type == token.COMMA
        and closing.type in CLOSING_BRACKETS
    ):
        return False

    if closing.type == token.RBRACE:
        self.remove_trailing_comma()
        return True

    if closing.type == token.RSQB:
        comma = self.leaves[-1]
        if comma.parent and comma.parent.type == syms.listmaker:
            self.remove_trailing_comma()
            return True

    # For parens let's check if it's safe to remove the comma.
    # Imports are always safe.
    if self.is_import:
        self.remove_trailing_comma()
        return True

    # Otherwise, if the trailing one is the only one, we might mistakenly
    # change a tuple into a different type by removing the comma.
    depth = closing.bracket_depth + 1
    commas = 0
    opening = closing.opening_bracket
    for _opening_index, leaf in enumerate(self.leaves):
        if leaf is opening:
            break

    else:
        return False

    for leaf in self.leaves[_opening_index + 1 :]:
        if leaf is closing:
            break

        bracket_depth = leaf.bracket_depth
        if bracket_depth == depth and leaf.type == token.COMMA:
            commas += 1
            if leaf.parent and leaf.parent.type == syms.arglist:
                commas += 1
                break

    if commas > 1:
        self.remove_trailing_comma()
        return True

    return False

def bracket_split_build_line(
    leaves: List[Leaf], original: Line, opening_bracket: Leaf, *, is_body: bool = False
) -> Line:
    """Return a new line with given `leaves` and respective comments from `original`.

    If `is_body` is True, the result line is one-indented inside brackets and as such
    has its first leaf's prefix normalized and a trailing comma added when expected.
    """
    result = Line(depth=original.depth)
    if is_body:
        result.inside_brackets = True
        result.depth += 1
        if leaves:
            # Since body is a new indent level, remove spurious leading whitespace.
            normalize_prefix(leaves[0], inside_brackets=True)
            # Ensure a trailing comma for imports, but be careful not to add one after
            # any comments.
            if original.is_import:
                for i in range(len(leaves) - 1, -1, -1):
                    if leaves[i].type == STANDALONE_COMMENT:
                        continue
                    elif leaves[i].type == token.COMMA:
                        break
                    else:
                        leaves.insert(i + 1, Leaf(token.COMMA, ","))
                        break
    # Populate the line
    for leaf in leaves:
        result.append(leaf, preformatted=True)
        for comment_after in original.comments_after(leaf):
            result.append(comment_after, preformatted=True)
    if is_body:
        result.should_explode = should_explode(result, opening_bracket)
    return result

def lib2to3_parse(src_txt: str, target_versions: Iterable[TargetVersion] = ()) -> Node:
    """Given a string with source, return the lib2to3 Node."""
    if src_txt[-1:] != "\n":
        src_txt += "\n"

    for grammar in get_grammars(set(target_versions)):
        drv = driver.Driver(grammar, pytree.convert)
        try:
            result = drv.parse_string(src_txt, True)
            break

        except ParseError as pe:
            lineno, column = pe.context[1]
            lines = src_txt.splitlines()
            try:
                faulty_line = lines[lineno - 1]
            except IndexError:
                faulty_line = "<line number missing in source>"
            exc = InvalidInput(f"Cannot parse: {lineno}:{column}: {faulty_line}")
    else:
        raise exc from None

    if isinstance(result, Leaf):
        result = Node(syms.file_input, [result])
    return result

def __init__(self, grammar, convert=None, logger=None):
    self.grammar = grammar
    if logger is None:
        logger = logging.getLogger(__name__)
    self.logger = logger
    self.convert = convert

def parse_stream_raw(self, stream, debug=False):
    """Parse a stream and return the syntax tree."""
    tokens = tokenize.generate_tokens(stream.readline)
    return self.parse_tokens(tokens, debug)

def parse_string(self, text, debug=False):
    """Parse a string and return the syntax tree."""
    tokens = tokenize.generate_tokens(io.StringIO(text).readline)
    return self.parse_tokens(tokens, debug)

def bracket_split_build_line(
    leaves: List[Leaf], original: Line, opening_bracket: Leaf, *, is_body: bool = False
) -> Line:
    """Return a new line with given `leaves` and respective comments from `original`.

    If `is_body` is True, the result line is one-indented inside brackets and as such
    has its first leaf's prefix normalized and a trailing comma added when expected.
    """
    result = Line(depth=original.depth)
    if is_body:
        result.inside_brackets = True
        result.depth += 1
        if leaves:
            # Since body is a new indent level, remove spurious leading whitespace.
            normalize_prefix(leaves[0], inside_brackets=True)
            # Ensure a trailing comma when expected.
            if original.is_import:
                if leaves[-1].type != token.COMMA:
                    leaves.append(Leaf(token.COMMA, ","))
    # Populate the line
    for leaf in leaves:
        result.append(leaf, preformatted=True)
        for comment_after in original.comments_after(leaf):
            result.append(comment_after, preformatted=True)
    if is_body:
        result.should_explode = should_explode(result, opening_bracket)
    return result

def get_grammars(target_versions: Set[TargetVersion]) -> List[Grammar]:
    if not target_versions:
        return GRAMMARS
    elif all(not version.is_python2() for version in target_versions):
        # Python 2-compatible code, so don't try Python 3 grammar.
        return [
            pygram.python_grammar_no_print_statement_no_exec_statement,
            pygram.python_grammar_no_print_statement,
        ]
    else:
        return [pygram.python_grammar]

def evaluate_generator(model, generator,
                       steps=None,
                       max_queue_size=10,
                       workers=1,
                       use_multiprocessing=False,
                       verbose=0):
    """See docstring for `Model.evaluate_generator`."""
    model._make_test_function()

    if hasattr(model, 'metrics'):
        for m in model.stateful_metric_functions:
            m.reset_states()
        stateful_metric_indices = [
            i for i, name in enumerate(model.metrics_names)
            if str(name) in model.stateful_metric_names]
    else:
        stateful_metric_indices = []

    steps_done = 0
    outs_per_batch = []
    batch_sizes = []
    is_sequence = isinstance(generator, Sequence)
    if not is_sequence and use_multiprocessing and workers > 1:
        warnings.warn(
            UserWarning('Using a generator with `use_multiprocessing=True`'
                        ' and multiple workers may duplicate your data.'
                        ' Please consider using the`keras.utils.Sequence'
                        ' class.'))
    if steps is None:
        if is_sequence:
            steps = len(generator)
        else:
            raise ValueError('`steps=None` is only valid for a generator'
                             ' based on the `keras.utils.Sequence` class.'
                             ' Please specify `steps` or use the'
                             ' `keras.utils.Sequence` class.')
    enqueuer = None

    try:
        if workers > 0:
            if is_sequence:
                enqueuer = OrderedEnqueuer(
                    generator,
                    use_multiprocessing=use_multiprocessing)
            else:
                enqueuer = GeneratorEnqueuer(
                    generator,
                    use_multiprocessing=use_multiprocessing)
            enqueuer.start(workers=workers, max_queue_size=max_queue_size)
            output_generator = enqueuer.get()
        else:
            if is_sequence:
                output_generator = iter_sequence_infinite(generator)
            else:
                output_generator = generator

        if verbose == 1:
            progbar = Progbar(target=steps)

        while steps_done < steps:
            generator_output = next(output_generator)
            if not hasattr(generator_output, '__len__'):
                raise ValueError('Output of generator should be a tuple '
                                 '(x, y, sample_weight) '
                                 'or (x, y). Found: ' +
                                 str(generator_output))
            if len(generator_output) == 2:
                x, y = generator_output
                sample_weight = None
            elif len(generator_output) == 3:
                x, y, sample_weight = generator_output
            else:
                raise ValueError('Output of generator should be a tuple '
                                 '(x, y, sample_weight) '
                                 'or (x, y). Found: ' +
                                 str(generator_output))
            outs = model.test_on_batch(x, y, sample_weight=sample_weight)
            outs = to_list(outs)
            outs_per_batch.append(outs)

            if x is None or len(x) == 0:
                # Handle data tensors support when no input given
                # step-size = 1 for data tensors
                batch_size = 1
            elif isinstance(x, list):
                batch_size = x[0].shape[0]
            elif isinstance(x, dict):
                batch_size = list(x.values())[0].shape[0]
            else:
                batch_size = x.shape[0]
            if batch_size == 0:
                raise ValueError('Received an empty batch. '
                                 'Batches should contain '
                                 'at least one item.')
            steps_done += 1
            batch_sizes.append(batch_size)
            if verbose == 1:
                progbar.update(steps_done)

    finally:
        if enqueuer is not None:
            enqueuer.stop()

    averages = []
    for i in range(len(outs)):
        if i not in stateful_metric_indices:
            averages.append(np.average([out[i] for out in outs_per_batch],
                                       weights=batch_sizes))
        else:
            averages.append(np.float64(outs_per_batch[-1][i]))
    return unpack_singleton(averages)

def predict_generator(model, generator,
                      steps=None,
                      max_queue_size=10,
                      workers=1,
                      use_multiprocessing=False,
                      verbose=0):
    """See docstring for `Model.predict_generator`."""
    model._make_predict_function()

    steps_done = 0
    all_outs = []
    is_sequence = isinstance(generator, Sequence)
    if not is_sequence and use_multiprocessing and workers > 1:
        warnings.warn(
            UserWarning('Using a generator with `use_multiprocessing=True`'
                        ' and multiple workers may duplicate your data.'
                        ' Please consider using the`keras.utils.Sequence'
                        ' class.'))
    if steps is None:
        if is_sequence:
            steps = len(generator)
        else:
            raise ValueError('`steps=None` is only valid for a generator'
                             ' based on the `keras.utils.Sequence` class.'
                             ' Please specify `steps` or use the'
                             ' `keras.utils.Sequence` class.')
    enqueuer = None

    try:
        if workers > 0:
            if is_sequence:
                enqueuer = OrderedEnqueuer(
                    generator,
                    use_multiprocessing=use_multiprocessing)
            else:
                enqueuer = GeneratorEnqueuer(
                    generator,
                    use_multiprocessing=use_multiprocessing)
            enqueuer.start(workers=workers, max_queue_size=max_queue_size)
            output_generator = enqueuer.get()
        else:
            if is_sequence:
                output_generator = iter_sequence_infinite(generator)
            else:
                output_generator = generator

        if verbose == 1:
            progbar = Progbar(target=steps)

        while steps_done < steps:
            generator_output = next(output_generator)
            if isinstance(generator_output, tuple):
                # Compatibility with the generators
                # used for training.
                if len(generator_output) == 2:
                    x, _ = generator_output
                elif len(generator_output) == 3:
                    x, _, _ = generator_output
                else:
                    raise ValueError('Output of generator should be '
                                     'a tuple `(x, y, sample_weight)` '
                                     'or `(x, y)`. Found: ' +
                                     str(generator_output))
            else:
                # Assumes a generator that only
                # yields inputs (not targets and sample weights).
                x = generator_output

            outs = model.predict_on_batch(x)
            outs = to_list(outs)

            if not all_outs:
                for out in outs:
                    all_outs.append([])

            for i, out in enumerate(outs):
                all_outs[i].append(out)
            steps_done += 1
            if verbose == 1:
                progbar.update(steps_done)

    finally:
        if enqueuer is not None:
            enqueuer.stop()

    if len(all_outs) == 1:
        if steps_done == 1:
            return all_outs[0][0]
        else:
            return np.concatenate(all_outs[0])
    if steps_done == 1:
        return [out[0] for out in all_outs]
    else:
        return [np.concatenate(out) for out in all_outs]

def sparse_categorical_accuracy(y_true, y_pred):
    # flatten y_true in case it's in shape (num_samples, 1) instead of (num_samples,)
    return K.cast(K.equal(K.flatten(y_true),
                          K.cast(K.argmax(y_pred, axis=-1), K.floatx())),
                  K.floatx())

def sparse_top_k_categorical_accuracy(y_true, y_pred, k=5):
    return K.mean(K.in_top_k(y_pred, K.cast(K.max(y_true, axis=-1), 'int32'), k),
                  axis=-1)

def on_epoch_end(self, epoch, logs=None):
    logs = logs or {}

    def handle_value(k):
        is_zero_dim_ndarray = isinstance(k, np.ndarray) and k.ndim == 0
        if isinstance(k, six.string_types):
            return k
        elif isinstance(k, Iterable) and not is_zero_dim_ndarray:
            return '"[%s]"' % (', '.join(map(str, k)))
        else:
            return k

    if self.keys is None:
        self.keys = sorted(logs.keys())

    if self.model.stop_training:
        # We set NA so that csv parsers do not fail for this last epoch.
        logs = dict([(k, logs[k]) if k in logs else (k, 'NA') for k in self.keys])

    if not self.writer:
        class CustomDialect(csv.excel):
            delimiter = self.sep

        self.writer = csv.DictWriter(self.csv_file,
                                     fieldnames=['epoch'] + self.keys, dialect=CustomDialect)
        if self.append_header:
            self.writer.writeheader()

    row_dict = OrderedDict({'epoch': epoch})
    row_dict.update((key, handle_value(logs[key])) for key in self.keys)
    self.writer.writerow(row_dict)
    self.csv_file.flush()

def on_train_begin(self, logs=None):
    if self.append:
        if os.path.exists(self.filename):
            with open(self.filename, 'r' + self.file_flags) as f:
                self.append_header = not bool(len(f.readline()))
        self.csv_file = open(self.filename, 'a' + self.file_flags)
    else:
        self.csv_file = open(self.filename, 'w' + self.file_flags)

def sparse_categorical_accuracy(y_true, y_pred):
    return K.cast(K.equal(K.max(y_true, axis=-1),
                          K.cast(K.argmax(y_pred, axis=-1), K.floatx())),
                  K.floatx())

def _recurrence(x, states, m):
    # create place holder
    place_holders = [C.placeholder(dynamic_axes=x.dynamic_axes) for _ in states]
    past_values = []
    for s, p in zip(states, place_holders):
        past_values.append(C.sequence.past_value(p, s))
    new_output, new_states = step_function(
        x, tuple(past_values) + tuple(rnn_constants))

    if getattr(new_output, '_uses_learning_phase', False):
        global uses_learning_phase
        uses_learning_phase = True

    if m is not None:
        new_states = [C.element_select(m, n, s) for n, s in zip(new_states, past_values)]
    n_s = []
    for o, p in zip(new_states, place_holders):
        n_s.append(o.replace_placeholders({p: o.output}))
    if len(n_s) > 0:
        new_output = n_s[0]
    return new_output, n_s

def compute_output_shape(self, input_shape):
    if isinstance(input_shape, list):
        input_shape = input_shape[0]

    if hasattr(self.cell.state_size, '__len__'):
        state_size = self.cell.state_size
    else:
        state_size = [self.cell.state_size]
    output_dim = state_size[0]

    if self.return_sequences:
        output_shape = (input_shape[0], input_shape[1], output_dim)
    else:
        output_shape = (input_shape[0], output_dim)

    if self.return_state:
        state_shape = [(input_shape[0], dim) for dim in state_size]
        return [output_shape] + state_shape
    else:
        return output_shape

def build(self, input_shape):
    if isinstance(input_shape, list):
        constants_shape = input_shape[1:]
        input_shape = input_shape[0]
    for cell in self.cells:
        if isinstance(cell, Layer):
            if has_arg(cell.call, 'constants'):
                cell.build([input_shape] + constants_shape)
            else:
                cell.build(input_shape)
        if hasattr(cell.state_size, '__len__'):
            output_dim = cell.state_size[0]
        else:
            output_dim = cell.state_size
        input_shape = (input_shape[0], output_dim)
    self.built = True

@property
def state_size(self):
    # States are a flat list
    # in reverse order of the cell stack.
    # This allows to preserve the requirement
    # `stack.state_size[0] == output_dim`.
    # e.g. states of a 2-layer LSTM would be
    # `[h2, c2, h1, c1]`
    # (assuming one LSTM has states [h, c])
    state_size = []
    for cell in self.cells[::-1]:
        if hasattr(cell.state_size, '__len__'):
            state_size += list(cell.state_size)
        else:
            state_size.append(cell.state_size)
    return tuple(state_size)

@symbolic
def update(x, new_x):
    """Update the value of `x` to `new_x`.

    # Arguments
        x: A `Variable`.
        new_x: A tensor of same shape as `x`.

    # Returns
        The variable `x` updated.
    """
    return tf_state_ops.assign(x, new_x)

@symbolic
def update_add(x, increment):
    """Update the value of `x` by adding `increment`.

    # Arguments
        x: A `Variable`.
        increment: A tensor of same shape as `x`.

    # Returns
        The variable `x` updated.
    """
    return tf_state_ops.assign_add(x, increment)

@symbolic
def update_sub(x, decrement):
    """Update the value of `x` by subtracting `decrement`.

    # Arguments
        x: A `Variable`.
        decrement: A tensor of same shape as `x`.

    # Returns
        The variable `x` updated.
    """
    return tf_state_ops.assign_sub(x, decrement)

def __call__(self, shape, dtype=None):
    return K.random_normal(shape, self.mean, self.stddev,
                           dtype=dtype, seed=self.seed)

def __call__(self, shape, dtype=None):
    return K.random_uniform(shape, self.minval, self.maxval,
                            dtype=dtype, seed=self.seed)

def __call__(self, shape, dtype=None):
    return K.truncated_normal(shape, self.mean, self.stddev,
                              dtype=dtype, seed=self.seed)

def __call__(self, shape, dtype=None):
    fan_in, fan_out = _compute_fans(shape)
    scale = self.scale
    if self.mode == 'fan_in':
        scale /= max(1., fan_in)
    elif self.mode == 'fan_out':
        scale /= max(1., fan_out)
    else:
        scale /= max(1., float(fan_in + fan_out) / 2)
    if self.distribution == 'normal':
        # 0.879... = scipy.stats.truncnorm.std(a=-2, b=2, loc=0., scale=1.)
        stddev = np.sqrt(scale) / .87962566103423978
        return K.truncated_normal(shape, 0., stddev,
                                  dtype=dtype, seed=self.seed)
    else:
        limit = np.sqrt(3. * scale)
        return K.random_uniform(shape, -limit, limit,
                                dtype=dtype, seed=self.seed)

def deconv_length(dim_size, stride_size, kernel_size, padding, output_padding):
    """Determines output length of a transposed convolution given input length.

    # Arguments
        dim_size: Integer, the input length.
        stride_size: Integer, the stride along the dimension of `dim_size`.
        kernel_size: Integer, the kernel size along the dimension of
            `dim_size`.
        padding: One of `"same"`, `"valid"`, `"full"`.
        output_padding: Integer, amount of padding along the output dimension,
            Can be set to `None` in which case the output length is inferred.

    # Returns
        The output length (integer).
    """
    assert padding in {'same', 'valid', 'full'}
    if dim_size is None:
        return None

    # Infer length if output padding is None, else compute the exact length
    if output_padding is None:
        if padding == 'valid':
            dim_size = dim_size * stride_size + max(kernel_size - stride_size, 0)
        elif padding == 'full':
            dim_size = dim_size * stride_size - (stride_size + kernel_size - 2)
        elif padding == 'same':
            dim_size = dim_size * stride_size
    else:
        if padding == 'same':
            pad = kernel_size // 2
        elif padding == 'valid':
            pad = 0
        elif padding == 'full':
            pad = kernel_size - 1

        dim_size = ((dim_size - 1) * stride_size + kernel_size - 2 * pad +
                    output_padding)

    return dim_size

def __getitem__(self, index):
    if self.shuffle:
        rows = np.random.randint(
            self.start_index, self.end_index, size=self.batch_size)
    else:
        i = self.start_index + self.batch_size * self.stride * index
        rows = np.arange(i, min(i + self.batch_size *
                                self.stride, self.end_index), self.stride)

    samples, targets = self._empty_batch(len(rows))
    for j, row in enumerate(rows):
        indices = range(rows[j] - self.length, rows[j], self.sampling_rate)
        samples[j] = self.data[indices]
        targets[j] = self.targets[rows[j]]
    if self.reverse:
        return samples[:, ::-1, ...], targets
    return samples, targets

def __len__(self):
    return int(np.ceil(
        (self.end_index - self.start_index) /
        (self.batch_size * self.stride)))

def _test_loop(self, f, ins, batch_size=None, verbose=0, steps=None):
    """Abstract method to loop over some data in batches.

    # Arguments
        f: Keras function returning a list of tensors.
        ins: list of tensors to be fed to `f`.
        batch_size: integer batch size or `None`.
        verbose: verbosity mode.
        steps: Total number of steps (batches of samples)
            before declaring predictions finished.
            Ignored with the default value of `None`.

    # Returns
        Scalar loss (if the model has a single output and no metrics)
        or list of scalars (if the model has multiple outputs
        and/or metrics). The attribute `model.metrics_names` will give you
        the display labels for the scalar outputs.
    """

    if hasattr(self, 'metrics'):
        for m in self.metrics:
            if isinstance(m, Layer) and m.stateful:
                m.reset_states()
        stateful_metric_indices = [
            i for i, name in enumerate(self.metrics_names)
            if str(name) in self.stateful_metric_names]
    else:
        stateful_metric_indices = []

    num_samples = self._check_num_samples(ins, batch_size,
                                          steps,
                                          'steps')
    outs = []
    if verbose == 1:
        if steps is not None:
            progbar = Progbar(target=steps)
        else:
            progbar = Progbar(target=num_samples)

    # To prevent a slowdown, we find beforehand the arrays that need conversion.
    feed = self._feed_inputs + self._feed_targets + self._feed_sample_weights
    indices_for_conversion_to_dense = []
    for i in range(len(feed)):
        if issparse(ins[i]) and not K.is_sparse(feed[i]):
            indices_for_conversion_to_dense.append(i)

    if steps is not None:
        for step in range(steps):
            batch_outs = f(ins)
            if isinstance(batch_outs, list):
                if step == 0:
                    for _ in enumerate(batch_outs):
                        outs.append(0.)
                for i, batch_out in enumerate(batch_outs):
                    if i in stateful_metric_indices:
                        outs[i] = float(batch_out)
                    else:
                        outs[i] += batch_out
            else:
                if step == 0:
                    outs.append(0.)
                outs[0] += batch_outs
            if verbose == 1:
                progbar.update(step + 1)
        for i in range(len(outs)):
            if i not in stateful_metric_indices:
                outs[i] /= steps
    else:
        batches = _make_batches(num_samples, batch_size)
        index_array = np.arange(num_samples)
        for batch_index, (batch_start, batch_end) in enumerate(batches):
            batch_ids = index_array[batch_start:batch_end]
            if isinstance(ins[-1], float):
                # Do not slice the training phase flag.
                ins_batch = _slice_arrays(ins[:-1], batch_ids) + [ins[-1]]
            else:
                ins_batch = _slice_arrays(ins, batch_ids)
            for i in indices_for_conversion_to_dense:
                ins_batch[i] = ins_batch[i].toarray()

            batch_outs = f(ins_batch)
            if isinstance(batch_outs, list):
                if batch_index == 0:
                    for batch_out in enumerate(batch_outs):
                        outs.append(0.)
                for i, batch_out in enumerate(batch_outs):
                    if i in stateful_metric_indices:
                        outs[i] = batch_out
                    else:
                        outs[i] += batch_out * len(batch_ids)
            else:
                if batch_index == 0:
                    outs.append(0.)
                outs[0] += batch_outs * len(batch_ids)

            if verbose == 1:
                progbar.update(batch_end)
        for i in range(len(outs)):
            if i not in stateful_metric_indices:
                outs[i] /= num_samples
    if len(outs) == 1:
        return outs[0]
    return outs

def on_epoch_end(self, epoch, logs=None):
    logs = logs or {}
    logs['lr'] = K.get_value(self.model.optimizer.lr)
    current = logs.get(self.monitor)
    if current is None:
        warnings.warn(
            'Reduce LR on plateau conditioned on metric `%s` '
            'which is not available. Available metrics are: %s' %
            (self.monitor, ','.join(list(logs.keys()))), RuntimeWarning
        )

    else:
        if self.in_cooldown():
            self.cooldown_counter -= 1
            self.wait = 0

        if self.monitor_op(current, self.best):
            self.best = current
            self.wait = 0
        elif not self.in_cooldown():
            if self.wait >= self.patience:
                old_lr = float(K.get_value(self.model.optimizer.lr))
                if old_lr > self.min_lr:
                    new_lr = old_lr * self.factor
                    new_lr = max(new_lr, self.min_lr)
                    K.set_value(self.model.optimizer.lr, new_lr)
                    if self.verbose > 0:
                        print('\nEpoch %05d: ReduceLROnPlateau reducing learning '
                              'rate to %s.' % (epoch + 1, new_lr))
                    self.cooldown_counter = self.cooldown
                    self.wait = 0
            self.wait += 1

def standardize(self, x):
    """Apply the normalization configuration to a batch of inputs.

    # Arguments
        x: batch of inputs to be normalized.

    # Returns
        The inputs, normalized.
    """
    if self.preprocessing_function:
        x = self.preprocessing_function(x)
    if self.rescale:
        x *= self.rescale
    if self.samplewise_center:
        x -= np.mean(x, keepdims=True)
    if self.samplewise_std_normalization:
        x /= (np.std(x, keepdims=True) + K.epsilon())

    if self.featurewise_center:
        if self.mean is not None:
            x -= self.mean
        else:
            warnings.warn('This ImageDataGenerator specifies '
                          '`featurewise_center`, but it hasn\'t '
                          'been fit on any training data. Fit it '
                          'first by calling `.fit(numpy_data)`.')
    if self.featurewise_std_normalization:
        if self.std is not None:
            x /= (self.std + K.epsilon())
        else:
            warnings.warn('This ImageDataGenerator specifies '
                          '`featurewise_std_normalization`, but it hasn\'t '
                          'been fit on any training data. Fit it '
                          'first by calling `.fit(numpy_data)`.')
    if self.zca_whitening:
        if self.principal_components is not None:
            flatx = np.reshape(x, (-1, np.prod(x.shape[-3:])))
            whitex = np.dot(flatx, self.principal_components)
            x = np.reshape(whitex, x.shape)
        else:
            warnings.warn('This ImageDataGenerator specifies '
                          '`zca_whitening`, but it hasn\'t '
                          'been fit on any training data. Fit it '
                          'first by calling `.fit(numpy_data)`.')
    return x

def call(self, inputs, training=None, mask=None, initial_state=None):
    kwargs = {}
    if has_arg(self.layer.call, 'training'):
        kwargs['training'] = training
    if has_arg(self.layer.call, 'mask'):
        kwargs['mask'] = mask

    if initial_state is not None and has_arg(self.layer.call, 'initial_state'):
        if not isinstance(initial_state, list):
            raise ValueError(
                'When passing `initial_state` to a Bidirectional RNN, the state '
                'should be a list containing the states of the underlying RNNs. '
                'Found: ' + str(initial_state))
        forward_state = initial_state[:len(initial_state) // 2]
        backward_state = initial_state[len(initial_state) // 2:]
        y = self.forward_layer.call(inputs, initial_state=forward_state, **kwargs)
        y_rev = self.backward_layer.call(inputs, initial_state=backward_state, **kwargs)
    else:
        y = self.forward_layer.call(inputs, **kwargs)
        y_rev = self.backward_layer.call(inputs, **kwargs)

    if self.return_state:
        states = y[1:] + y_rev[1:]
        y = y[0]
        y_rev = y_rev[0]

    if self.return_sequences:
        y_rev = K.reverse(y_rev, 1)
    if self.merge_mode == 'concat':
        output = K.concatenate([y, y_rev])
    elif self.merge_mode == 'sum':
        output = y + y_rev
    elif self.merge_mode == 'ave':
        output = (y + y_rev) / 2
    elif self.merge_mode == 'mul':
        output = y * y_rev
    elif self.merge_mode is None:
        output = [y, y_rev]

    # Properly set learning phase
    if (getattr(y, '_uses_learning_phase', False) or
       getattr(y_rev, '_uses_learning_phase', False)):
        if self.merge_mode is None:
            for out in output:
                out._uses_learning_phase = True
        else:
            output._uses_learning_phase = True

    if self.return_state:
        if self.merge_mode is None:
            return output + states
        return [output] + states
    return output

def build(self, input_shape):
    for cell in self.cells:
        if isinstance(cell, Layer):
            cell.build(input_shape)
        if hasattr(cell.state_size, '__len__'):
            output_dim = cell.state_size[0]
        else:
            output_dim = cell.state_size
        input_shape = (input_shape[0], input_shape[1], output_dim)
    self.built = True

def update(self, current, values=None, force=False):
    """Updates the progress bar.

    # Arguments
        current: Index of current step.
        values: List of tuples (name, value_for_last_step).
            The progress bar will display averages for these values.
        force: Whether to force visual progress update.
    """
    values = values or []
    for k, v in values:
        if k not in self.sum_values:
            self.sum_values[k] = [v * (current - self.seen_so_far),
                                  current - self.seen_so_far]
            self.unique_values.append(k)
        else:
            self.sum_values[k][0] += v * (current - self.seen_so_far)
            self.sum_values[k][1] += (current - self.seen_so_far)
    self.seen_so_far = current

    now = time.time()
    info = ' - %.0fs' % (now - self.start)
    if self.verbose == 1:
        if (not force and (now - self.last_update) < self.interval and
                current < self.target):
            return

        prev_total_width = self.total_width
        if self._dynamic_display:
            sys.stdout.write('\b' * prev_total_width)
            sys.stdout.write('\r')
        else:
            sys.stdout.write('\n')

        if self.target is not None:
            numdigits = int(np.floor(np.log10(self.target))) + 1
            barstr = '%%%dd/%d [' % (numdigits, self.target)
            bar = barstr % current
            prog = float(current) / self.target
            prog_width = int(self.width * prog)
            if prog_width > 0:
                bar += ('=' * (prog_width - 1))
                if current < self.target:
                    bar += '>'
                else:
                    bar += '='
            bar += ('.' * (self.width - prog_width))
            bar += ']'
        else:
            bar = '%7d/Unknown' % current

        self.total_width = len(bar)
        sys.stdout.write(bar)

        if current:
            time_per_unit = (now - self.start) / current
        else:
            time_per_unit = 0
        if self.target is not None and current < self.target:
            eta = time_per_unit * (self.target - current)
            if eta > 3600:
                eta_format = '%d:%02d:%02d' % (eta // 3600, (eta % 3600) // 60, eta % 60)
            elif eta > 60:
                eta_format = '%d:%02d' % (eta // 60, eta % 60)
            else:
                eta_format = '%ds' % eta

            info = ' - ETA: %s' % eta_format
        else:
            if time_per_unit >= 1:
                info += ' %.0fs/step' % time_per_unit
            elif time_per_unit >= 1e-3:
                info += ' %.0fms/step' % (time_per_unit * 1e3)
            else:
                info += ' %.0fus/step' % (time_per_unit * 1e6)

        for k in self.unique_values:
            info += ' - %s:' % k
            if isinstance(self.sum_values[k], list):
                avg = np.mean(
                    self.sum_values[k][0] / max(1, self.sum_values[k][1]))
                if abs(avg) > 1e-3:
                    info += ' %.4f' % avg
                else:
                    info += ' %.4e' % avg
            else:
                info += ' %s' % self.sum_values[k]

        self.total_width += len(info)
        if prev_total_width > self.total_width:
            info += (' ' * (prev_total_width - self.total_width))

        if self.target is not None and current >= self.target:
            info += '\n'

        sys.stdout.write(info)
        sys.stdout.flush()

    elif self.verbose == 2:
        if self.target is None or current >= self.target:
            for k in self.unique_values:
                info += ' - %s:' % k
                avg = np.mean(
                    self.sum_values[k][0] / max(1, self.sum_values[k][1]))
                if avg > 1e-3:
                    info += ' %.4f' % avg
                else:
                    info += ' %.4e' % avg
            info += '\n'

            sys.stdout.write(info)
            sys.stdout.flush()

    self.last_update = now

def compute_output_shape(self, input_shape):
    if isinstance(input_shape, list):
        input_shape = input_shape[0]

    if hasattr(self.cell.state_size, '__len__'):
        output_dim = self.cell.state_size[0]
    else:
        output_dim = self.cell.state_size

    if self.return_sequences:
        output_shape = (input_shape[0], input_shape[1], output_dim)
    else:
        output_shape = (input_shape[0], output_dim)

    if self.return_state:
        state_shape = [(input_shape[0], output_dim) for _ in self.states]
        return [output_shape] + state_shape
    else:
        return output_shape

def get(self):
    """Creates a generator to extract data from the queue.

    Skip the data if it is `None`.

    # Returns
        A generator
    """
    while self.is_running():
        if not self.queue.empty():
            inputs = self.queue.get()
            if inputs is not None:
                yield inputs
        else:
            all_finished = all([not thread.is_alive() for thread in self._threads])
            if all_finished and self.queue.empty():
                raise StopIteration()
            else:
                time.sleep(self.wait_time)

def start(self, workers=1, max_queue_size=10):
    """Kicks off threads which add data from the generator into the queue.

    # Arguments
        workers: number of worker threads
        max_queue_size: queue size
            (when full, threads could block on `put()`)
    """

    def data_generator_task():
        while not self._stop_event.is_set():
            try:
                if self._use_multiprocessing or self.queue.qsize() < max_queue_size:
                    generator_output = next(self._generator)
                    self.queue.put(generator_output)
                else:
                    time.sleep(self.wait_time)
            except StopIteration:
                break
            except Exception:
                self._stop_event.set()
                raise

    try:
        if self._use_multiprocessing:
            self.queue = multiprocessing.Queue(maxsize=max_queue_size)
            self._stop_event = multiprocessing.Event()
        else:
            self.queue = queue.Queue()
            self._stop_event = threading.Event()

        for _ in range(workers):
            if self._use_multiprocessing:
                # Reset random seed else all children processes
                # share the same seed
                np.random.seed(self.seed)
                thread = multiprocessing.Process(target=data_generator_task)
                thread.daemon = True
                if self.seed is not None:
                    self.seed += 1
            else:
                thread = threading.Thread(target=data_generator_task)
            self._threads.append(thread)
            thread.start()
    except:
        self.stop()
        raise

def data_generator_task():
    while not self._stop_event.is_set():
        try:
            if self._use_multiprocessing or self.queue.qsize() < max_queue_size:
                generator_output = next(self._generator)
                self.queue.put(generator_output)
            else:
                time.sleep(self.wait_time)
        except StopIteration:
            break
        except Exception:
            self._stop_event.set()
            raise

def stop(self, timeout=None):
    """Stops running threads and wait for them to exit, if necessary.

    Should be called by the same thread which called `start()`.

    # Arguments
        timeout: maximum time to wait on `thread.join()`.
    """
    if self.is_running():
        self._stop_event.set()

    for thread in self._threads:
        if thread.is_alive():
            if self._use_multiprocessing:
                thread.terminate()
            else:
                thread.join(timeout)

    if self._use_multiprocessing:
        if self.queue is not None:
            self.queue.close()

    self._threads = []
    self._stop_event = None
    self.queue = None

def get(self):
    """Creates a generator to extract data from the queue.

    Skip the data if it is `None`.

    # Returns
        Generator yielding tuples (inputs, targets)
            or (inputs, targets, sample_weights)
    """
    try:
        while self.is_running():
            inputs = self.queue.get(block=True).get()
            self.queue.task_done()
            if inputs is not None:
                yield inputs
    except Exception as e:
        self.stop()
        raise StopIteration(e)

def process_node(layer, node_data):
    input_tensors = []
    for input_data in node_data:
        inbound_layer_name = input_data[0]
        inbound_node_index = input_data[1]
        inbound_tensor_index = input_data[2]
        if len(input_data) == 3:
            kwargs = {}
        elif len(input_data) == 4:
            kwargs = input_data[3]
        else:
            raise ValueError('Improperly formatted model config.')
        inbound_layer = created_layers[inbound_layer_name]
        if len(inbound_layer._inbound_nodes) <= inbound_node_index:
            add_unprocessed_node(layer, node_data)
            return
        inbound_node = inbound_layer._inbound_nodes[inbound_node_index]
        input_tensors.append(
            inbound_node.output_tensors[inbound_tensor_index])
    # Call layer on its inputs, thus creating the node
    # and building the layer if needed.
    if input_tensors:
        layer(unpack_singleton(input_tensors), **kwargs)

@Appender(_shared_docs["pct_change"] % _shared_doc_kwargs)
def pct_change(self, periods=1, fill_method="pad", limit=None, freq=None, **kwargs):
    # TODO: Not sure if above is correct - need someone to confirm.
    axis = self._get_axis_number(kwargs.pop("axis", self._stat_axis_name))
    if fill_method is None:
        data = self
    else:
        data = self.fillna(method=fill_method, limit=limit, axis=axis)

    rs = data.div(data.shift(periods=periods, freq=freq, axis=axis, **kwargs)) - 1
    rs = rs.loc[~rs.index.duplicated()]
    rs = rs.reindex_like(data)
    if freq is None:
        mask = isna(com.values_from_object(data))
        np.putmask(rs.values, mask, np.nan)
    return rs

def init_ndarray(values, index, columns, dtype=None, copy=False):
    # input must be a ndarray, list, Series, index

    if isinstance(values, ABCSeries):
        if columns is None:
            if values.name is not None:
                columns = [values.name]
        if index is None:
            index = values.index
        else:
            values = values.reindex(index)

        # zero len case (GH #2234)
        if not len(values) and columns is not None and len(columns):
            values = np.empty((0, 1), dtype=object)

    # we could have a categorical type passed or coerced to 'category'
    # recast this to an arrays_to_mgr
    if is_categorical_dtype(getattr(values, "dtype", None)) or is_categorical_dtype(
        dtype
    ):

        if not hasattr(values, "dtype"):
            values = prep_ndarray(values, copy=copy)
            values = values.ravel()
        elif copy:
            values = values.copy()

        index, columns = _get_axes(len(values), 1, index, columns)
        return arrays_to_mgr([values], columns, index, columns, dtype=dtype)
    elif is_extension_array_dtype(values) or is_extension_array_dtype(dtype):
        # GH#19157
        if columns is None:
            columns = [0]
        return arrays_to_mgr([values], columns, index, columns, dtype=dtype)

    # by definition an array here
    # the dtypes will be coerced to a single dtype
    values = prep_ndarray(values, copy=copy)

    if dtype is not None:
        if not is_dtype_equal(values.dtype, dtype):
            try:
                values = values.astype(dtype)
            except Exception as orig:
                # e.g. ValueError when trying to cast object dtype to float64
                raise ValueError(
                    f"failed to cast to '{dtype}' (Exception was: {orig})"
                ) from orig

    index, columns = _get_axes(*values.shape, index=index, columns=columns)
    values = values.T

    # if we don't have a dtype specified, then try to convert objects
    # on the entire block; this is to convert if we have datetimelike's
    # embedded in an object type
    if dtype is None and is_object_dtype(values):

        if values.ndim == 2 and values.shape[0] != 1:
            # transpose and separate blocks

            dvals_list = [maybe_infer_to_datetimelike(row) for row in values]
            for n in range(len(dvals_list)):
                if isinstance(dvals_list[n], np.ndarray):
                    dvals_list[n] = dvals_list[n].reshape(1, -1)

            from pandas.core.internals.blocks import make_block

            # TODO: What about re-joining object columns?
            block_values = [
                make_block(dvals_list[n], placement=[n]) for n in range(len(dvals_list))
            ]

        else:
            datelike_vals = maybe_infer_to_datetimelike(values)
            block_values = [datelike_vals]
    else:
        block_values = [values]

    return create_block_manager_from_blocks(block_values, [columns, index])

@Appender(_index_shared_docs["get_indexer_non_unique"] % _index_doc_kwargs)
def get_indexer_non_unique(self, target):
    target = ensure_index(target)
    pself, ptarget = self._maybe_promote(target)
    if pself is not self or ptarget is not target:
        return pself.get_indexer_non_unique(ptarget)

    if is_categorical(target):
        tgt_values = np.asarray(target)
    elif self.is_all_dates:
        tgt_values = target.asi8
    else:
        tgt_values = target._ndarray_values

    indexer, missing = self._engine.get_indexer_non_unique(tgt_values)
    return ensure_platform_int(indexer), missing

@Appender(_index_shared_docs["_convert_slice_indexer"])
def _convert_slice_indexer(self, key: slice, kind=None):
    assert kind in ["ix", "loc", "getitem", "iloc", None]

    # validate iloc
    if kind == "iloc":
        return slice(
            self._validate_indexer("slice", key.start, kind),
            self._validate_indexer("slice", key.stop, kind),
            self._validate_indexer("slice", key.step, kind),
        )

    # potentially cast the bounds to integers
    start, stop, step = key.start, key.stop, key.step

    # figure out if this is a positional indexer
    def is_int(v):
        return v is None or is_integer(v)

    is_null_slicer = start is None and stop is None
    is_index_slice = is_int(start) and is_int(stop)
    is_positional = is_index_slice and not self.is_integer()

    if kind == "getitem":
        """
        called from the getitem slicers, validate that we are in fact
        integers
        """
        if self.is_integer() or is_index_slice:
            return slice(
                self._validate_indexer("slice", key.start, kind),
                self._validate_indexer("slice", key.stop, kind),
                self._validate_indexer("slice", key.step, kind),
            )

    # convert the slice to an indexer here

    # if we are mixed and have integers
    try:
        if is_positional and self.is_mixed():
            # Validate start & stop
            if start is not None:
                self.get_loc(start)
            if stop is not None:
                self.get_loc(stop)
            is_positional = False
    except KeyError:
        if self.inferred_type in ["mixed-integer-float", "integer-na"]:
            raise

    if is_null_slicer:
        indexer = key
    elif is_positional:
        indexer = key
    else:
        indexer = self.slice_indexer(start, stop, step, kind=kind)

    return indexer

@Appender(_index_shared_docs["_convert_scalar_indexer"])
def _convert_scalar_indexer(self, key, kind=None):
    assert kind in ["ix", "loc", "getitem", "iloc", None]

    if kind == "iloc":
        return self._validate_indexer("positional", key, kind)

    if len(self) and not isinstance(self, ABCMultiIndex):

        # we can raise here if we are definitive that this
        # is positional indexing (eg. .ix on with a float)
        # or label indexing if we are using a type able
        # to be represented in the index

        if kind in ["getitem", "ix"] and is_float(key):
            if not self.is_floating():
                return self._invalid_indexer("label", key)

        elif kind in ["loc"] and is_float(key):

            # we want to raise KeyError on string/mixed here
            # technically we *could* raise a TypeError
            # on anything but mixed though
            if self.inferred_type not in [
                "floating",
                "mixed-integer-float",
                "integer-na",
                "string",
                "unicode",
                "mixed",
            ]:
                return self._invalid_indexer("label", key)

        elif kind in ["loc"] and is_integer(key):
            if not self.holds_integer():
                return self._invalid_indexer("label", key)

    return key

@Appender(_index_shared_docs["_convert_scalar_indexer"])
def _convert_scalar_indexer(self, key, kind=None):
    if self.categories._defer_to_indexing:
        return self.categories._convert_scalar_indexer(key, kind=kind)

    return super()._convert_scalar_indexer(key, kind=kind)

@unpack_zerodim_and_defer(op.__name__)
def cmp_method(self, other):
    mask = None

    if isinstance(other, IntegerArray):
        other, mask = other._data, other._mask

    elif is_list_like(other):
        other = np.asarray(other)
        if other.ndim > 1:
            raise NotImplementedError(
                "can only perform ops with 1-d structures"
            )
        if len(self) != len(other):
            raise ValueError("Lengths must match to compare")

    # numpy will show a DeprecationWarning on invalid elementwise
    # comparisons, this will raise in the future
    with warnings.catch_warnings():
        warnings.filterwarnings("ignore", "elementwise", FutureWarning)
        with np.errstate(all="ignore"):
            result = op(self._data, other)

    # nans propagate
    if mask is None:
        mask = self._mask
    else:
        mask = self._mask | mask

    result[mask] = op_name == "ne"
    return result

@Appender(_index_shared_docs["get_value"] % _index_doc_kwargs)
def get_value(self, series, key):

    # if we have something that is Index-like, then
    # use this, e.g. DatetimeIndex
    # Things like `Series._get_value` (via .at) pass the EA directly here.
    s = getattr(series, "_values", series)
    if isinstance(s, (ExtensionArray, Index)) and is_scalar(key):
        # GH 20882, 21257
        # Unify Index and ExtensionArray treatment
        # First try to convert the key to a location
        # If that fails, raise a KeyError if an integer
        # index, otherwise, see if key is an integer, and
        # try that
        try:
            iloc = self.get_loc(key)
            return s[iloc]
        except KeyError:
            if len(self) > 0 and (self.holds_integer() or self.is_boolean()):
                raise
            elif is_integer(key):
                return s[key]

    s = com.values_from_object(series)
    k = com.values_from_object(key)

    k = self._convert_scalar_indexer(k, kind="getitem")
    try:
        return self._engine.get_value(s, k, tz=getattr(series.dtype, "tz", None))
    except KeyError as e1:
        if len(self) > 0 and (self.holds_integer() or self.is_boolean()):
            raise

        try:
            return libindex.get_value_at(s, key)
        except IndexError:
            raise
        except TypeError:
            # generator/iterator-like
            if is_iterator(key):
                raise InvalidIndexError(key)
            else:
                raise e1
        except Exception:
            raise e1
    except TypeError:
        # e.g. "[False] is an invalid key"
        if is_scalar(key):
            raise IndexError(key)
        raise InvalidIndexError(key)

def _get_merge_keys(self):
    """
    Note: has side effects (copy/delete key columns)

    Parameters
    ----------
    left
    right
    on

    Returns
    -------
    left_keys, right_keys
    """
    left_keys = []
    right_keys = []
    join_names = []
    right_drop = []
    left_drop = []

    left, right = self.left, self.right

    is_lkey = lambda x: is_array_like(x) and len(x) == len(left)
    is_rkey = lambda x: is_array_like(x) and len(x) == len(right)

    # Note that pd.merge_asof() has separate 'on' and 'by' parameters. A
    # user could, for example, request 'left_index' and 'left_by'. In a
    # regular pd.merge(), users cannot specify both 'left_index' and
    # 'left_on'. (Instead, users have a MultiIndex). That means the
    # self.left_on in this function is always empty in a pd.merge(), but
    # a pd.merge_asof(left_index=True, left_by=...) will result in a
    # self.left_on array with a None in the middle of it. This requires
    # a work-around as designated in the code below.
    # See _validate_specification() for where this happens.

    # ugh, spaghetti re #733
    if _any(self.left_on) and _any(self.right_on):
        for lk, rk in zip(self.left_on, self.right_on):
            if is_lkey(lk):
                left_keys.append(lk)
                if is_rkey(rk):
                    right_keys.append(rk)
                    join_names.append(None)  # what to do?
                else:
                    if rk is not None:
                        right_keys.append(right._get_label_or_level_values(rk))
                        join_names.append(rk)
                    else:
                        # work-around for merge_asof(right_index=True)
                        right_keys.append(right.index)
                        join_names.append(right.index.name)
            else:
                if not is_rkey(rk):
                    if rk is not None:
                        right_keys.append(right._get_label_or_level_values(rk))
                    else:
                        # work-around for merge_asof(right_index=True)
                        right_keys.append(right.index)
                    if lk is not None and lk == rk:
                        # avoid key upcast in corner case (length-0)
                        if len(left) > 0:
                            right_drop.append(rk)
                        else:
                            left_drop.append(lk)
                else:
                    right_keys.append(rk)
                if lk is not None:
                    left_keys.append(left._get_label_or_level_values(lk))
                    join_names.append(lk)
                else:
                    # work-around for merge_asof(left_index=True)
                    left_keys.append(left.index)
                    join_names.append(left.index.name)
    elif _any(self.left_on):
        for k in self.left_on:
            if is_lkey(k):
                left_keys.append(k)
                join_names.append(None)
            else:
                left_keys.append(left._get_label_or_level_values(k))
                join_names.append(k)
        if isinstance(self.right.index, MultiIndex):
            right_keys = [
                lev._values.take(lev_codes)
                for lev, lev_codes in zip(
                    self.right.index.levels, self.right.index.codes
                )
            ]
        else:
            right_keys = [self.right.index._values]
    elif _any(self.right_on):
        for k in self.right_on:
            if is_rkey(k):
                right_keys.append(k)
                join_names.append(None)
            else:
                right_keys.append(right._get_label_or_level_values(k))
                join_names.append(k)
        if isinstance(self.left.index, MultiIndex):
            left_keys = [
                lev._values.take(lev_codes)
                for lev, lev_codes in zip(
                    self.left.index.levels, self.left.index.codes
                )
            ]
        else:
            left_keys = [self.left.index.values]

    if left_drop:
        self.left = self.left._drop_labels_or_levels(left_drop)

    if right_drop:
        self.right = self.right._drop_labels_or_levels(right_drop)

    return left_keys, right_keys, join_names

def _isna_old(obj):
    """
    Detect missing values, treating None, NaN, INF, -INF as null.

    Parameters
    ----------
    arr: ndarray or object value

    Returns
    -------
    boolean ndarray or boolean
    """
    if is_scalar(obj):
        return libmissing.checknull_old(obj)
    # hack (for now) because MI registers as ndarray
    elif isinstance(obj, ABCMultiIndex):
        raise NotImplementedError("isna is not defined for MultiIndex")
    elif isinstance(obj, type):
        return False
    elif isinstance(obj, (ABCSeries, np.ndarray, ABCIndexClass)):
        return _isna_ndarraylike_old(obj)
    elif isinstance(obj, ABCGeneric):
        return obj._constructor(obj._data.isna(func=_isna_old))
    elif isinstance(obj, list):
        return _isna_ndarraylike_old(np.asarray(obj, dtype=object))
    elif hasattr(obj, "__array__"):
        return _isna_ndarraylike_old(np.asarray(obj))
    else:
        return obj is None

@Appender(
    _shared_docs["melt"]
    % dict(caller="pd.melt(df, ", versionadded="", other="DataFrame.melt")
)
def melt(
    frame: DataFrame,
    id_vars=None,
    value_vars=None,
    var_name=None,
    value_name="value",
    col_level=None,
) -> DataFrame:
    # TODO: what about the existing index?
    # If multiindex, gather names of columns on all level for checking presence
    # of `id_vars` and `value_vars`
    if isinstance(frame.columns, ABCMultiIndex):
        cols = [x for c in frame.columns for x in c]
    else:
        cols = list(frame.columns)

    if id_vars is not None:
        if not is_list_like(id_vars):
            id_vars = [id_vars]
        elif isinstance(frame.columns, ABCMultiIndex) and not isinstance(id_vars, list):
            raise ValueError(
                "id_vars must be a list of tuples when columns are a MultiIndex"
            )
        else:
            # Check that `id_vars` are in frame
            id_vars = list(id_vars)
            missing = Index(np.ravel(id_vars)).difference(cols)
            if not missing.empty:
                raise KeyError(
                    "The following 'id_vars' are not present"
                    " in the DataFrame: {missing}"
                    "".format(missing=list(missing))
                )
    else:
        id_vars = []

    if value_vars is not None:
        if not is_list_like(value_vars):
            value_vars = [value_vars]
        elif isinstance(frame.columns, ABCMultiIndex) and not isinstance(
            value_vars, list
        ):
            raise ValueError(
                "value_vars must be a list of tuples when columns are a MultiIndex"
            )
        else:
            value_vars = list(value_vars)
            # Check that `value_vars` are in frame
            missing = Index(np.ravel(value_vars)).difference(cols)
            if not missing.empty:
                raise KeyError(
                    "The following 'value_vars' are not present in"
                    " the DataFrame: {missing}"
                    "".format(missing=list(missing))
                )
        frame = frame.loc[:, id_vars + value_vars]
    else:
        frame = frame.copy()

    if col_level is not None:  # allow list or other?
        # frame is a copy
        frame.columns = frame.columns.get_level_values(col_level)

    if var_name is None:
        if isinstance(frame.columns, ABCMultiIndex):
            if len(frame.columns.names) == len(set(frame.columns.names)):
                var_name = frame.columns.names
            else:
                var_name = [
                    "variable_{i}".format(i=i) for i in range(len(frame.columns.names))
                ]
        else:
            var_name = [
                frame.columns.name if frame.columns.name is not None else "variable"
            ]
    if isinstance(var_name, str):
        var_name = [var_name]

    N, K = frame.shape
    K -= len(id_vars)

    mdata = {}
    for col in id_vars:
        id_data = frame.pop(col)
        if is_extension_array_dtype(id_data):
            id_data = concat([id_data] * K, ignore_index=True)
        else:
            id_data = np.tile(id_data.values, K)
        mdata[col] = id_data

    mcolumns = id_vars + var_name + [value_name]

    mdata[value_name] = frame.values.ravel("F")
    for i, col in enumerate(var_name):
        # asanyarray will keep the columns as an Index
        mdata[col] = np.asanyarray(frame.columns._get_level_values(i)).repeat(N)

    return frame._constructor(mdata, columns=mcolumns)

def _add_margins(
    table: Union["Series", "DataFrame"],
    data,
    values,
    rows,
    cols,
    aggfunc,
    observed=None,
    margins_name: str = "All",
    fill_value=None,
):
    if not isinstance(margins_name, str):
        raise ValueError("margins_name argument must be a string")

    msg = 'Conflicting name "{name}" in margins'.format(name=margins_name)
    for level in table.index.names:
        if margins_name in table.index.get_level_values(level):
            raise ValueError(msg)

    grand_margin = _compute_grand_margin(data, values, aggfunc, margins_name)

    if table.ndim == 2:
        # i.e. DataFramae
        for level in table.columns.names[1:]:
            if margins_name in table.columns.get_level_values(level):
                raise ValueError(msg)

    key: Union[str, Tuple[str, ...]]
    if len(rows) > 1:
        key = (margins_name,) + ("",) * (len(rows) - 1)
    else:
        key = margins_name

    if not values and isinstance(table, ABCSeries):
        # If there are no values and the table is a series, then there is only
        # one column in the data. Compute grand margin and return it.
        return table.append(Series({key: grand_margin[margins_name]}))

    elif values:
        marginal_result_set = _generate_marginal_results(
            table,
            data,
            values,
            rows,
            cols,
            aggfunc,
            observed,
            grand_margin,
            margins_name,
        )
        if not isinstance(marginal_result_set, tuple):
            return marginal_result_set
        result, margin_keys, row_margin = marginal_result_set
    else:
        # no values, and table is a DataFrame
        assert isinstance(table, ABCDataFrame)
        marginal_result_set = _generate_marginal_results_without_values(
            table, data, rows, cols, aggfunc, observed, margins_name
        )
        if not isinstance(marginal_result_set, tuple):
            return marginal_result_set
        result, margin_keys, row_margin = marginal_result_set

    row_margin = row_margin.reindex(result.columns, fill_value=fill_value)
    # populate grand margin
    for k in margin_keys:
        if isinstance(k, str):
            row_margin[k] = grand_margin[k]
        else:
            row_margin[k] = grand_margin[k[0]]

    from pandas import DataFrame

    margin_dummy = DataFrame(row_margin, columns=[key]).T

    row_names = result.index.names
    try:
        for dtype in set(result.dtypes):
            cols = result.select_dtypes([dtype]).columns
            margin_dummy[cols] = margin_dummy[cols].astype(dtype)
        result = result.append(margin_dummy)
    except TypeError:

        # we cannot reshape, so coerce the axis
        result.index = result.index._to_safe_for_reshape()
        result = result.append(margin_dummy)
    result.index.names = row_names

    return result

def _make_concat_multiindex(indexes, keys, levels=None, names=None) -> MultiIndex:

    if (levels is None and isinstance(keys[0], tuple)) or (
        levels is not None and len(levels) > 1
    ):
        zipped = list(zip(*keys))
        if names is None:
            names = [None] * len(zipped)

        if levels is None:
            _, levels = factorize_from_iterables(zipped)
        else:
            levels = [ensure_index(x) for x in levels]
    else:
        zipped = [keys]
        if names is None:
            names = [None]

        if levels is None:
            levels = [ensure_index(keys)]
        else:
            levels = [ensure_index(x) for x in levels]

    if not all_indexes_same(indexes):
        codes_list = []

        # things are potentially different sizes, so compute the exact codes
        # for each level and pass those to MultiIndex.from_arrays

        for hlevel, level in zip(zipped, levels):
            to_concat = []
            for key, index in zip(hlevel, indexes):
                try:
                    i = level.get_loc(key)
                except KeyError as err:
                    raise ValueError(f"Key {key} not in level {level}") from err

                to_concat.append(np.repeat(i, len(index)))
            codes_list.append(np.concatenate(to_concat))

        concat_index = _concat_indexes(indexes)

        # these go at the end
        if isinstance(concat_index, MultiIndex):
            levels.extend(concat_index.levels)
            codes_list.extend(concat_index.codes)
        else:
            codes, categories = factorize_from_iterable(concat_index)
            levels.append(categories)
            codes_list.append(codes)

        if len(names) == len(levels):
            names = list(names)
        else:
            # make sure that all of the passed indices have the same nlevels
            if not len({idx.nlevels for idx in indexes}) == 1:
                raise AssertionError(
                    "Cannot concat indices that do not have the same number of levels"
                )

            # also copies
            names = names + get_consensus_names(indexes)

        return MultiIndex(
            levels=levels, codes=codes_list, names=names, verify_integrity=False
        )

    new_index = indexes[0]
    n = len(new_index)
    kpieces = len(indexes)

    # also copies
    new_names = list(names)
    new_levels = list(levels)

    # construct codes
    new_codes = []

    # do something a bit more speedy

    for hlevel, level in zip(zipped, levels):
        hlevel = ensure_index(hlevel)
        mapped = level.get_indexer(hlevel)

        mask = mapped == -1
        if mask.any():
            raise ValueError(f"Values not found in passed level: {hlevel[mask]!s}")

        new_codes.append(np.repeat(mapped, n))

    if isinstance(new_index, MultiIndex):
        new_levels.extend(new_index.levels)
        new_codes.extend([np.tile(lab, kpieces) for lab in new_index.codes])
    else:
        new_levels.append(new_index)
        new_codes.append(np.tile(np.arange(n), kpieces))

    if len(new_names) < len(new_levels):
        new_names.extend(new_index.names)

    return MultiIndex(
        levels=new_levels, codes=new_codes, names=new_names, verify_integrity=False
    )

def __new__(
    cls,
    data=None,
    dtype=None,
    copy=False,
    name=None,
    fastpath=None,
    tupleize_cols=True,
    **kwargs,
) -> "Index":

    from .range import RangeIndex
    from pandas import PeriodIndex, DatetimeIndex, TimedeltaIndex
    from .numeric import Float64Index, Int64Index, UInt64Index
    from .interval import IntervalIndex
    from .category import CategoricalIndex

    if name is None and hasattr(data, "name"):
        name = data.name

    if fastpath is not None:
        warnings.warn(
            "The 'fastpath' keyword is deprecated, and will be "
            "removed in a future version.",
            FutureWarning,
            stacklevel=2,
        )
        if fastpath:
            return cls._simple_new(data, name)

    if isinstance(data, ABCPandasArray):
        # ensure users don't accidentally put a PandasArray in an index.
        data = data.to_numpy()

    # range
    if isinstance(data, RangeIndex):
        return RangeIndex(start=data, copy=copy, dtype=dtype, name=name)
    elif isinstance(data, range):
        return RangeIndex.from_range(data, dtype=dtype, name=name)

    # categorical
    elif is_categorical_dtype(data) or is_categorical_dtype(dtype):
        return CategoricalIndex(data, dtype=dtype, copy=copy, name=name, **kwargs)

    # interval
    elif (
        is_interval_dtype(data) or is_interval_dtype(dtype)
    ) and not is_object_dtype(dtype):
        closed = kwargs.get("closed", None)
        return IntervalIndex(data, dtype=dtype, name=name, copy=copy, closed=closed)

    elif (
        is_datetime64_any_dtype(data)
        or is_datetime64_any_dtype(dtype)
        or "tz" in kwargs
    ):
        if is_dtype_equal(_o_dtype, dtype):
            # GH#23524 passing `dtype=object` to DatetimeIndex is invalid,
            #  will raise in the where `data` is already tz-aware.  So
            #  we leave it out of this step and cast to object-dtype after
            #  the DatetimeIndex construction.
            # Note we can pass copy=False because the .astype below
            #  will always make a copy
            result = DatetimeIndex(
                data, copy=False, name=name, **kwargs
            )  # type: "Index"
            return result.astype(object)
        else:
            return DatetimeIndex(data, copy=copy, name=name, dtype=dtype, **kwargs)

    elif is_timedelta64_dtype(data) or is_timedelta64_dtype(dtype):
        if is_dtype_equal(_o_dtype, dtype):
            # Note we can pass copy=False because the .astype below
            #  will always make a copy
            result = TimedeltaIndex(data, copy=False, name=name, **kwargs)
            return result.astype(object)
        else:
            return TimedeltaIndex(data, copy=copy, name=name, dtype=dtype, **kwargs)

    elif is_period_dtype(data) and not is_object_dtype(dtype):
        return PeriodIndex(data, copy=copy, name=name, **kwargs)

    # extension dtype
    elif is_extension_array_dtype(data) or is_extension_array_dtype(dtype):
        data = np.asarray(data)
        if not (dtype is None or is_object_dtype(dtype)):
            # coerce to the provided dtype
            ea_cls = dtype.construct_array_type()
            data = ea_cls._from_sequence(data, dtype=dtype, copy=False)

        # coerce to the object dtype
        data = data.astype(object)
        return Index(data, dtype=object, copy=copy, name=name, **kwargs)

    # index-like
    elif isinstance(data, (np.ndarray, Index, ABCSeries)):
        if dtype is not None:
            # we need to avoid having numpy coerce
            # things that look like ints/floats to ints unless
            # they are actually ints, e.g. '0' and 0.0
            # should not be coerced
            # GH 11836
            if is_integer_dtype(dtype):
                inferred = lib.infer_dtype(data, skipna=False)
                if inferred == "integer":
                    data = maybe_cast_to_integer_array(data, dtype, copy=copy)
                elif inferred in ["floating", "mixed-integer-float"]:
                    if isna(data).any():
                        raise ValueError("cannot convert float NaN to integer")

                    if inferred == "mixed-integer-float":
                        data = maybe_cast_to_integer_array(data, dtype)

                    # If we are actually all equal to integers,
                    # then coerce to integer.
                    try:
                        return cls._try_convert_to_int_index(
                            data, copy, name, dtype
                        )
                    except ValueError:
                        pass

                    # Return an actual float index.
                    return Float64Index(data, copy=copy, dtype=dtype, name=name)

                elif inferred == "string":
                    pass
                else:
                    data = data.astype(dtype)
            elif is_float_dtype(dtype):
                inferred = lib.infer_dtype(data, skipna=False)
                if inferred == "string":
                    pass
                else:
                    data = data.astype(dtype)
            else:
                data = np.array(data, dtype=dtype, copy=copy)

        # maybe coerce to a sub-class
        if is_signed_integer_dtype(data.dtype):
            return Int64Index(data, copy=copy, dtype=dtype, name=name)
        elif is_unsigned_integer_dtype(data.dtype):
            return UInt64Index(data, copy=copy, dtype=dtype, name=name)
        elif is_float_dtype(data.dtype):
            return Float64Index(data, copy=copy, dtype=dtype, name=name)
        elif issubclass(data.dtype.type, np.bool) or is_bool_dtype(data):
            subarr = data.astype("object")
        else:
            subarr = com.asarray_tuplesafe(data, dtype=object)

        # asarray_tuplesafe does not always copy underlying data,
        # so need to make sure that this happens
        if copy:
            subarr = subarr.copy()

        if dtype is None:
            inferred = lib.infer_dtype(subarr, skipna=False)
            if inferred == "integer":
                try:
                    return cls._try_convert_to_int_index(subarr, copy, name, dtype)
                except ValueError:
                    pass

                return Index(subarr, copy=copy, dtype=object, name=name)
            elif inferred in ["floating", "mixed-integer-float", "integer-na"]:
                # TODO: Returns IntegerArray for integer-na case in the future
                return Float64Index(subarr, copy=copy, name=name)
            elif inferred == "interval":
                try:
                    return IntervalIndex(subarr, name=name, copy=copy)
                except ValueError:
                    # GH27172: mixed closed Intervals --> object dtype
                    pass
            elif inferred == "boolean":
                # don't support boolean explicitly ATM
                pass
            elif inferred != "string":
                if inferred.startswith("datetime"):
                    try:
                        return DatetimeIndex(subarr, copy=copy, name=name, **kwargs)
                    except (ValueError, OutOfBoundsDatetime):
                        # GH 27011
                        # If we have mixed timezones, just send it
                        # down the base constructor
                        pass

                elif inferred.startswith("timedelta"):
                    return TimedeltaIndex(subarr, copy=copy, name=name, **kwargs)
                elif inferred == "period":
                    try:
                        return PeriodIndex(subarr, name=name, **kwargs)
                    except IncompatibleFrequency:
                        pass
        if kwargs:
            raise TypeError(f"Unexpected keyword arguments {set(kwargs)!r}")
        return cls._simple_new(subarr, name, **kwargs)

    elif hasattr(data, "__array__"):
        return Index(np.asarray(data), dtype=dtype, copy=copy, name=name, **kwargs)
    elif data is None or is_scalar(data):
        raise cls._scalar_data_error(data)
    else:
        if tupleize_cols and is_list_like(data):
            # GH21470: convert iterable to list before determining if empty
            if is_iterator(data):
                data = list(data)

            if data and all(isinstance(e, tuple) for e in data):
                # we must be all tuples, otherwise don't construct
                # 10697
                from .multi import MultiIndex

                return MultiIndex.from_tuples(
                    data, names=name or kwargs.get("names")
                )
        # other iterable of some kind
        subarr = com.asarray_tuplesafe(data, dtype=object)
        return Index(subarr, dtype=dtype, copy=copy, name=name, **kwargs)

def __new__(cls, data=None, dtype=None, copy=False, name=None, fastpath=None):

    if fastpath is not None:
        warnings.warn(
            "The 'fastpath' keyword is deprecated, and will be "
            "removed in a future version.",
            FutureWarning,
            stacklevel=2,
        )
        if fastpath:
            return cls._simple_new(data, name=name)

    # Coerce to ndarray if not already ndarray or Index
    if not isinstance(data, (np.ndarray, Index)):
        if is_scalar(data):
            raise cls._scalar_data_error(data)

        # other iterable of some kind
        if not isinstance(data, (ABCSeries, list, tuple)):
            data = list(data)

        data = np.asarray(data, dtype=dtype)

    if issubclass(data.dtype.type, str):
        cls._string_data_error(data)

    if copy or not is_dtype_equal(data.dtype, cls._default_dtype):
        subarr = np.array(data, dtype=cls._default_dtype, copy=copy)
        cls._assert_safe_casting(data, subarr)
    else:
        subarr = data

    if name is None and hasattr(data, "name"):
        name = data.name
    return cls._simple_new(subarr, name=name)

def __new__(cls, data):
    # CombinedDatetimelikeProperties isn't really instantiated. Instead
    # we need to choose which parent (datetime or timedelta) is
    # appropriate. Since we're checking the dtypes anyway, we'll just
    # do all the validation here.
    from pandas import Series

    if not isinstance(data, ABCSeries):
        raise TypeError(
            "cannot convert an object of type {0} to a "
            "datetimelike index".format(type(data))
        )

    orig = data if is_categorical_dtype(data) else None
    if orig is not None:
        data = Series(orig.values.categories, name=orig.name, copy=False)

    if is_datetime64_dtype(data.dtype):
        return DatetimeProperties(data, orig)
    elif is_datetime64tz_dtype(data.dtype):
        return DatetimeProperties(data, orig)
    elif is_timedelta64_dtype(data.dtype):
        return TimedeltaProperties(data, orig)
    elif is_period_arraylike(data):
        return PeriodProperties(data, orig)
    elif is_datetime_arraylike(data):
        return DatetimeProperties(data, orig)

    raise AttributeError("Can only use .dt accessor with datetimelike values")

def agg_series(self, obj, func):
    try:
        return self._aggregate_series_fast(obj, func)
    except AssertionError:
        raise
    except ValueError as err:
        if "No result." in str(err):
            # raised in libreduction
            pass
        elif "Function does not reduce" in str(err):
            # raised in libreduction
            pass
        else:
            raise
        return self._aggregate_series_pure_python(obj, func)

def _get_merge_keys(self):

    # note this function has side effects
    (left_join_keys, right_join_keys, join_names) = super()._get_merge_keys()

    # validate index types are the same
    for i, (lk, rk) in enumerate(zip(left_join_keys, right_join_keys)):
        if not is_dtype_equal(lk.dtype, rk.dtype):
            if is_categorical_dtype(lk.dtype) and is_categorical_dtype(rk.dtype):
                # The generic error message is confusing for categoricals.
                #
                # In this function, the join keys include both the original
                # ones of the merge_asof() call, and also the keys passed
                # to its by= argument. Unordered but equal categories
                # are not supported for the former, but will fail
                # later with a ValueError, so we don't *need* to check
                # for them here.
                msg = (
                    "incompatible merge keys [{i}] {lkdtype} and "
                    "{rkdtype}, both sides category, but not equal ones".format(
                        i=i, lkdtype=repr(lk.dtype), rkdtype=repr(rk.dtype)
                    )
                )
            else:
                msg = (
                    "incompatible merge keys [{i}] {lkdtype} and "
                    "{rkdtype}, must be the same type".format(
                        i=i, lkdtype=repr(lk.dtype), rkdtype=repr(rk.dtype)
                    )
                )
            raise MergeError(msg)

    # validate tolerance; datetime.timedelta or Timedelta if we have a DTI
    if self.tolerance is not None:

        if self.left_index:
            lt = self.left.index
        else:
            lt = left_join_keys[-1]

        msg = (
            "incompatible tolerance {tolerance}, must be compat "
            "with type {lkdtype}".format(
                tolerance=type(self.tolerance), lkdtype=repr(lt.dtype)
            )
        )

        if is_datetimelike(lt):
            if not isinstance(self.tolerance, datetime.timedelta):
                raise MergeError(msg)
            if self.tolerance < Timedelta(0):
                raise MergeError("tolerance must be positive")

        elif is_int64_dtype(lt):
            if not is_integer(self.tolerance):
                raise MergeError(msg)
            if self.tolerance < 0:
                raise MergeError("tolerance must be positive")

        elif is_float_dtype(lt):
            if not is_number(self.tolerance):
                raise MergeError(msg)
            if self.tolerance < 0:
                raise MergeError("tolerance must be positive")

        else:
            raise MergeError("key must be integer, timestamp or float")

    # validate allow_exact_matches
    if not is_bool(self.allow_exact_matches):
        msg = "allow_exact_matches must be boolean, passed {passed}"
        raise MergeError(msg.format(passed=self.allow_exact_matches))

    return left_join_keys, right_join_keys, join_names

def __init__(
    self,
    index,
    grouper=None,
    obj=None,
    name=None,
    level=None,
    sort=True,
    observed=False,
    in_axis=False,
):

    self.name = name
    self.level = level
    self.grouper = _convert_grouper(index, grouper)
    self.all_grouper = None
    self.index = index
    self.sort = sort
    self.obj = obj
    self.observed = observed
    self.in_axis = in_axis

    # right place for this?
    if isinstance(grouper, (Series, Index)) and name is None:
        self.name = grouper.name

    if isinstance(grouper, MultiIndex):
        self.grouper = grouper.values

    # we have a single grouper which may be a myriad of things,
    # some of which are dependent on the passing in level

    if level is not None:
        if not isinstance(level, int):
            if level not in index.names:
                raise AssertionError("Level {} not in index".format(level))
            level = index.names.index(level)

        if self.name is None:
            self.name = index.names[level]

        self.grouper, self._labels, self._group_index = index._get_grouper_for_level(  # noqa: E501
            self.grouper, level
        )

    # a passed Grouper like, directly get the grouper in the same way
    # as single grouper groupby, use the group_info to get labels
    elif isinstance(self.grouper, Grouper):
        # get the new grouper; we already have disambiguated
        # what key/level refer to exactly, don't need to
        # check again as we have by this point converted these
        # to an actual value (rather than a pd.Grouper)
        _, grouper, _ = self.grouper._get_grouper(self.obj, validate=False)
        if self.name is None:
            self.name = grouper.result_index.name
        self.obj = self.grouper.obj
        self.grouper = grouper._get_grouper()

    else:
        if self.grouper is None and self.name is not None:
            self.grouper = self.obj[self.name]

        elif isinstance(self.grouper, (list, tuple)):
            self.grouper = com.asarray_tuplesafe(self.grouper)

        # a passed Categorical
        elif is_categorical_dtype(self.grouper):

            self.grouper, self.all_grouper = recode_for_groupby(
                self.grouper, self.sort, observed
            )
            categories = self.grouper.categories

            # we make a CategoricalIndex out of the cat grouper
            # preserving the categories / ordered attributes
            self._labels = self.grouper.codes
            if observed:
                codes = algorithms.unique1d(self.grouper.codes)
                codes = codes[codes != -1]
                if sort or self.grouper.ordered:
                    codes = np.sort(codes)
            else:
                codes = np.arange(len(categories))

            self._group_index = CategoricalIndex(
                Categorical.from_codes(
                    codes=codes, categories=categories, ordered=self.grouper.ordered
                )
            )

        # we are done
        if isinstance(self.grouper, Grouping):
            self.grouper = self.grouper.grouper

        # no level passed
        elif not isinstance(
            self.grouper, (Series, Index, ExtensionArray, np.ndarray)
        ):
            if getattr(self.grouper, "ndim", 1) != 1:
                t = self.name or str(type(self.grouper))
                raise ValueError("Grouper for '{}' not 1-dimensional".format(t))
            self.grouper = self.index.map(self.grouper)
            if not (
                hasattr(self.grouper, "__len__")
                and len(self.grouper) == len(self.index)
            ):
                errmsg = (
                    "Grouper result violates len(labels) == "
                    "len(data)\nresult: %s" % pprint_thing(self.grouper)
                )
                self.grouper = None  # Try for sanity
                raise AssertionError(errmsg)

    # if we have a date/time-like grouper, make sure that we have
    # Timestamps like
    if getattr(self.grouper, "dtype", None) is not None:
        if is_datetime64_dtype(self.grouper):
            self.grouper = self.grouper.astype("datetime64[ns]")
        elif is_timedelta64_dtype(self.grouper):

            self.grouper = self.grouper.astype("timedelta64[ns]")

def _isna_ndarraylike(obj):
    values = getattr(obj, "_values", obj)
    dtype = values.dtype

    if is_extension_array_dtype(dtype):
        result = values.isna()
    elif is_string_dtype(dtype):
        result = _isna_string_dtype(values, dtype, old=False)

    elif needs_i8_conversion(dtype):
        # this is the NaT pattern
        result = values.view("i8") == iNaT
    else:
        result = np.isnan(values)

    # box
    if isinstance(obj, ABCSeries):
        result = obj._constructor(result, index=obj.index, name=obj.name, copy=False)

    return result

def _isna_new(obj):

    if is_scalar(obj):
        return libmissing.checknull(obj)
    # hack (for now) because MI registers as ndarray
    elif isinstance(obj, ABCMultiIndex):
        raise NotImplementedError("isna is not defined for MultiIndex")
    elif isinstance(obj, type):
        return False
    elif isinstance(obj, (ABCSeries, np.ndarray, ABCIndexClass, ABCExtensionArray)):
        return _isna_ndarraylike(obj)
    elif isinstance(obj, ABCDataFrame):
        return obj.isna()
    elif isinstance(obj, list):
        return _isna_ndarraylike(np.asarray(obj, dtype=object))
    elif hasattr(obj, "__array__"):
        return _isna_ndarraylike(np.asarray(obj))
    else:
        return False

def _isna_old(obj):
    """
    Detect missing values, treating None, NaN, INF, -INF as null.

    Parameters
    ----------
    arr: ndarray or object value

    Returns
    -------
    boolean ndarray or boolean
    """
    if is_scalar(obj):
        return libmissing.checknull_old(obj)
    # hack (for now) because MI registers as ndarray
    elif isinstance(obj, ABCMultiIndex):
        raise NotImplementedError("isna is not defined for MultiIndex")
    elif isinstance(obj, type):
        return False
    elif isinstance(obj, (ABCSeries, np.ndarray, ABCIndexClass, ABCExtensionArray)):
        return _isna_ndarraylike_old(obj)
    elif isinstance(obj, ABCDataFrame):
        return obj.isna()
    elif isinstance(obj, list):
        return _isna_ndarraylike_old(np.asarray(obj, dtype=object))
    elif hasattr(obj, "__array__"):
        return _isna_ndarraylike_old(np.asarray(obj))
    else:
        return False

@Appender(_index_shared_docs["get_indexer"])
def get_indexer(self, target, method=None, limit=None, tolerance=None):
    if com.any_not_none(method, tolerance, limit) or not is_list_like(target):
        return super().get_indexer(
            target, method=method, tolerance=tolerance, limit=limit
        )

    if self.step > 0:
        start, stop, step = self.start, self.stop, self.step
    else:
        # Work on reversed range for simplicity:
        start, stop, step = (self.stop - self.step, self.start + 1, -self.step)

    target_array = np.asarray(target)
    if not (is_integer_dtype(target_array) and target_array.ndim == 1):
        # checks/conversions/roundings are delegated to general method
        return super().get_indexer(target, method=method, tolerance=tolerance)

    locs = target_array - start
    valid = (locs % step == 0) & (locs >= 0) & (target_array < stop)
    locs[~valid] = -1
    locs[valid] = locs[valid] / step

    if step != self.step:
        # We reversed this range: transform to original locs
        locs[valid] = len(self) - 1 - locs[valid]
    return ensure_platform_int(locs)

