def _decorate_ticks(self, ax, name, ticklabels, start_edge, end_edge):
    ax.set_xlim((start_edge, end_edge))
    ax.set_xticks(self.tick_pos)
    ax.set_xticklabels(ticklabels)
    if name is not None and self.use_index:
        ax.set_xlabel(name)

def dispatch_to_series(left, right, func, str_rep=None, axis=None):
    """
    Evaluate the frame operation func(left, right) by evaluating
    column-by-column, dispatching to the Series implementation.

    Parameters
    ----------
    left : DataFrame
    right : scalar or DataFrame
    func : arithmetic or comparison operator
    str_rep : str or None, default None
    axis : {None, 0, 1, "index", "columns"}

    Returns
    -------
    DataFrame
    """
    # Note: we use iloc to access columns for compat with cases
    #       with non-unique columns.
    import pandas.core.computation.expressions as expressions

    right = lib.item_from_zerodim(right)
    if lib.is_scalar(right) or np.ndim(right) == 0:

        def column_op(a, b):
            return {i: func(a.iloc[:, i], b) for i in range(len(a.columns))}

    elif isinstance(right, ABCDataFrame):
        assert right._indexed_same(left)

        def column_op(a, b):
            return {i: func(a.iloc[:, i], b.iloc[:, i]) for i in range(len(a.columns))}

    elif isinstance(right, ABCSeries) and axis == "columns":
        # We only get here if called via left._combine_match_columns,
        # in which case we specifically want to operate row-by-row
        assert right.index.equals(left.columns)

        def column_op(a, b):
            return {i: func(a.iloc[:, i], b.iloc[i]) for i in range(len(a.columns))}

    elif isinstance(right, ABCSeries):
        assert right.index.equals(left.index)  # Handle other cases later

        def column_op(a, b):
            return {i: func(a.iloc[:, i], b) for i in range(len(a.columns))}

    else:
        # Remaining cases have less-obvious dispatch rules
        raise NotImplementedError(right)

    new_data = expressions.evaluate(column_op, str_rep, left, right)
    return new_data

def array_equivalent(left, right, strict_nan=False):
    """
    True if two arrays, left and right, have equal non-NaN elements, and NaNs
    in corresponding locations.  False otherwise. It is assumed that left and
    right are NumPy arrays of the same dtype. The behavior of this function
    (particularly with respect to NaNs) is not defined if the dtypes are
    different.

    Parameters
    ----------
    left, right : ndarrays
    strict_nan : bool, default False
        If True, consider NaN and None to be different.

    Returns
    -------
    b : bool
        Returns True if the arrays are equivalent.

    Examples
    --------
    >>> array_equivalent(
    ...     np.array([1, 2, np.nan]),
    ...     np.array([1, 2, np.nan]))
    True
    >>> array_equivalent(
    ...     np.array([1, np.nan, 2]),
    ...     np.array([1, 2, np.nan]))
    False
    """

    left, right = np.asarray(left), np.asarray(right)

    # shape compat
    if left.shape != right.shape:
        return False

    # Object arrays can contain None, NaN and NaT.
    # string dtypes must be come to this path for NumPy 1.7.1 compat
    if is_string_dtype(left) or is_string_dtype(right):

        if not strict_nan:
            # isna considers NaN and None to be equivalent.
            return lib.array_equivalent_object(
                ensure_object(left.ravel()), ensure_object(right.ravel())
            )

        for left_value, right_value in zip(left, right):
            if left_value is NaT and right_value is not NaT:
                return False

            elif isinstance(left_value, float) and np.isnan(left_value):
                if not isinstance(right_value, float) or not np.isnan(right_value):
                    return False
            else:
                if np.any(left_value != right_value):
                    return False
        return True

    # NaNs can occur in float and complex arrays.
    if is_float_dtype(left) or is_complex_dtype(left):

        # empty
        if not (np.prod(left.shape) and np.prod(right.shape)):
            return True
        return ((left == right) | (isna(left) & isna(right))).all()

    # numpy will will not allow this type of datetimelike vs integer comparison
    elif is_datetimelike_v_numeric(left, right):
        return False

    # M8/m8
    elif needs_i8_conversion(left) and needs_i8_conversion(right):
        if not is_dtype_equal(left.dtype, right.dtype):
            return False

        left = left.view("i8")
        right = right.view("i8")

    # if we have structured dtypes, compare first
    if left.dtype.type is np.void or right.dtype.type is np.void:
        if left.dtype != right.dtype:
            return False

    return np.array_equal(left, right)

def equals(self, other):
    """
    Determine if two Index objects contain the same elements.

    Returns
    -------
    bool
        True if "other" is an Index and it has the same elements as calling
        index; False otherwise.
    """
    if self.is_(other):
        return True

    if not isinstance(other, Index):
        return False

    if is_object_dtype(self) and not is_object_dtype(other):
        # if other is not object, use other's logic for coercion
        return other.equals(self)

    try:
        return array_equivalent(
            com.values_from_object(self), com.values_from_object(other)
        )
    except Exception:
        return False

def __init__(self, unit="ns", tz=None):
    if isinstance(unit, DatetimeTZDtype):
        unit, tz = unit.unit, unit.tz

    if unit != "ns":
        if isinstance(unit, str) and tz is None:
            # maybe a string like datetime64[ns, tz], which we support for
            # now.
            result = type(self).construct_from_string(unit)
            unit = result.unit
            tz = result.tz
            msg = (
                "Passing a dtype alias like 'datetime64[ns, {tz}]' "
                "to DatetimeTZDtype is deprecated. Use "
                "'DatetimeTZDtype.construct_from_string()' instead."
            )
            warnings.warn(msg.format(tz=tz), FutureWarning, stacklevel=2)
        else:
            raise ValueError("DatetimeTZDtype only supports ns units")

    if tz:
        tz = timezones.maybe_get_tz(tz)
        tz = timezones.tz_standardize(tz)
    elif tz is not None:
        raise pytz.UnknownTimeZoneError(tz)
    elif tz is None:
        raise TypeError("A 'tz' is required.")

    self._unit = unit
    self._tz = tz

def apply_empty_result(self):
    """
    we have an empty result; at least 1 axis is 0

    we will try to apply the function to an empty
    series in order to see if this is a reduction function
    """

    # we are not asked to reduce or infer reduction
    # so just return a copy of the existing object
    if self.result_type not in ["reduce", None]:
        return self.obj.copy()

    # we may need to infer
    should_reduce = self.result_type == "reduce"

    from pandas import Series

    if not should_reduce:

        EMPTY_SERIES = Series([])
        try:
            r = self.f(EMPTY_SERIES, *self.args, **self.kwds)
        except Exception:
            pass
        else:
            should_reduce = not isinstance(r, Series)

    if should_reduce:
        return self.obj._constructor_sliced(np.nan, index=self.agg_axis)
    else:
        return self.obj.copy()

def array_equivalent(left, right, strict_nan=False):
    """
    True if two arrays, left and right, have equal non-NaN elements, and NaNs
    in corresponding locations.  False otherwise. It is assumed that left and
    right are NumPy arrays of the same dtype. The behavior of this function
    (particularly with respect to NaNs) is not defined if the dtypes are
    different.

    Parameters
    ----------
    left, right : ndarrays
    strict_nan : bool, default False
        If True, consider NaN and None to be different.

    Returns
    -------
    b : bool
        Returns True if the arrays are equivalent.

    Examples
    --------
    >>> array_equivalent(
    ...     np.array([1, 2, np.nan]),
    ...     np.array([1, 2, np.nan]))
    True
    >>> array_equivalent(
    ...     np.array([1, np.nan, 2]),
    ...     np.array([1, 2, np.nan]))
    False
    """

    left, right = np.asarray(left), np.asarray(right)

    # shape compat
    if left.shape != right.shape:
        return False

    # Object arrays can contain None, NaN and NaT.
    # string dtypes must be come to this path for NumPy 1.7.1 compat
    if is_string_dtype(left) or is_string_dtype(right):

        if not strict_nan:
            # isna considers NaN and None to be equivalent.
            return lib.array_equivalent_object(
                ensure_object(left.ravel()), ensure_object(right.ravel())
            )

        for left_value, right_value in zip(left, right):
            if left_value is NaT and right_value is not NaT:
                return False

            elif isinstance(left_value, float) and np.isnan(left_value):
                if not isinstance(right_value, float) or not np.isnan(right_value):
                    return False
            else:
                if left_value != right_value:
                    return False
        return True

    # NaNs can occur in float and complex arrays.
    if is_float_dtype(left) or is_complex_dtype(left):

        # empty
        if not (np.prod(left.shape) and np.prod(right.shape)):
            return True
        return ((left == right) | (isna(left) & isna(right))).all()

    # numpy will will not allow this type of datetimelike vs integer comparison
    elif is_datetimelike_v_numeric(left, right):
        return False

    # M8/m8
    elif needs_i8_conversion(left) and needs_i8_conversion(right):
        if not is_dtype_equal(left.dtype, right.dtype):
            return False

        left = left.view("i8")
        right = right.view("i8")

    # if we have structured dtypes, compare first
    if left.dtype.type is np.void or right.dtype.type is np.void:
        if left.dtype != right.dtype:
            return False

    return np.array_equal(left, right)

def __setitem__(self, key, value):
    value = extract_array(value, extract_numpy=True)

    if not lib.is_scalar(key) and is_list_like(key):
        key = np.asarray(key)

    if not lib.is_scalar(value):
        value = np.asarray(value)

    values = self._ndarray
    t = np.result_type(value, values)
    if t != self._ndarray.dtype:
        values = values.astype(t, casting="safe")
        values[key] = value
        self._dtype = PandasDtype(t)
        self._ndarray = values
    else:
        self._ndarray[key] = value

def to_native_types(self, slicer=None, na_rep="nan", quoting=None, **kwargs):
    """ convert to our native types format, slicing if desired """

    values = self.get_values()

    if slicer is not None:
        values = values[:, slicer]
    mask = isna(values)

    if not self.is_object and not quoting:
        values = values.astype(str)
    else:
        values = np.array(values, dtype="object")

    values[mask] = na_rep
    return values

@cache_readonly
def _on(self):

    if self.on is None:
        return self.obj.index
    elif isinstance(self.obj, ABCDataFrame) and self.on in self.obj.columns:
        return Index(self.obj[self.on])
    else:
        raise ValueError(
            "invalid on specified as {0}, "
            "must be a column (if DataFrame) "
            "or None".format(self.on)
        )

def _combine_match_columns(self, other, func, level=None):
    # patched version of DataFrame._combine_match_columns to account for
    # NumPy circumventing __rsub__ with float64 types, e.g.: 3.0 - series,
    # where 3.0 is numpy.float64 and series is a SparseSeries. Still
    # possible for this to happen, which is bothersome

    if level is not None:
        raise NotImplementedError("'level' argument is not supported")

    left, right = self.align(other, join="outer", axis=1, level=level, copy=False)
    assert left.columns.equals(right.index)

    new_data = {}

    for col in left.columns:
        new_data[col] = func(left[col], float(right[col]))

    return self._constructor(
        new_data,
        index=left.index,
        columns=left.columns,
        default_fill_value=self.default_fill_value,
    ).__finalize__(self)

def _combine_match_index(self, other, func, level=None):

    if level is not None:
        raise NotImplementedError("'level' argument is not supported")

    this, other = self.align(other, join="outer", axis=0, level=level, copy=False)

    new_data = {}
    for col, series in this.items():
        new_data[col] = func(series.values, other.values)

    fill_value = self._get_op_result_fill_value(other, func)

    return self._constructor(
        new_data,
        index=this.index,
        columns=self.columns,
        default_fill_value=fill_value,
    ).__finalize__(self)

def _get_merge_keys(self):

    # note this function has side effects
    (left_join_keys, right_join_keys, join_names) = super()._get_merge_keys()

    # validate index types are the same
    for i, (lk, rk) in enumerate(zip(left_join_keys, right_join_keys)):
        if not is_dtype_equal(lk.dtype, rk.dtype):
            if is_categorical_dtype(lk.dtype) and is_categorical_dtype(rk.dtype):
                # The generic error message is confusing for categoricals.
                #
                # In this function, the join keys include both the original
                # ones of the merge_asof() call, and also the keys passed
                # to its by= argument. Unordered but equal categories
                # are not supported for the former, but will fail
                # later with a ValueError, so we don't *need* to check
                # for them here.
                msg = (
                    "incompatible merge keys [{i}] {lkdtype} and "
                    "{rkdtype}, both sides category, but not equal ones".format(
                        i=i, lkdtype=repr(lk.dtype), rkdtype=repr(rk.dtype)
                    )
                )
            else:
                msg = (
                    "incompatible merge keys [{i}] {lkdtype} and "
                    "{rkdtype}, must be the same type".format(
                        i=i, lkdtype=repr(lk.dtype), rkdtype=repr(rk.dtype)
                    )
                )
            raise MergeError(msg)

    # validate tolerance; must be a Timedelta if we have a DTI
    if self.tolerance is not None:

        if self.left_index:
            lt = self.left.index
        else:
            lt = left_join_keys[-1]

        msg = (
            "incompatible tolerance {tolerance}, must be compat "
            "with type {lkdtype}".format(
                tolerance=type(self.tolerance), lkdtype=repr(lt.dtype)
            )
        )

        if is_datetime64_dtype(lt) or is_datetime64tz_dtype(lt):
            if not isinstance(self.tolerance, Timedelta):
                raise MergeError(msg)
            if self.tolerance < Timedelta(0):
                raise MergeError("tolerance must be positive")

        elif is_int64_dtype(lt):
            if not is_integer(self.tolerance):
                raise MergeError(msg)
            if self.tolerance < 0:
                raise MergeError("tolerance must be positive")

        elif is_float_dtype(lt):
            if not is_number(self.tolerance):
                raise MergeError(msg)
            if self.tolerance < 0:
                raise MergeError("tolerance must be positive")

        else:
            raise MergeError("key must be integer, timestamp or float")

    # validate allow_exact_matches
    if not is_bool(self.allow_exact_matches):
        msg = "allow_exact_matches must be boolean, passed {passed}"
        raise MergeError(msg.format(passed=self.allow_exact_matches))

    return left_join_keys, right_join_keys, join_names

def _combine_frame(self, other, func, fill_value=None, level=None):
    this, other = self.align(other, join="outer", level=level, copy=False)
    new_index, new_columns = this.index, this.columns

    def _arith_op(left, right):
        # for the mixed_type case where we iterate over columns,
        # _arith_op(left, right) is equivalent to
        # left._binop(right, func, fill_value=fill_value)
        left, right = ops.fill_binop(left, right, fill_value)
        return func(left, right)

    if ops.should_series_dispatch(this, other, func):
        # iterate over columns
        return ops.dispatch_to_series(this, other, _arith_op)
    else:
        result = _arith_op(this.values, other.values)
        return self._constructor(
            result, index=new_index, columns=new_columns, copy=False
        )

def _can_use_numexpr(op, op_str, a, b, dtype_check):
    """ return a boolean if we WILL be using numexpr """
    if op_str is not None:

        # required min elements (otherwise we are adding overhead)
        if np.prod(a.shape) > _MIN_ELEMENTS:

            # check for dtype compatibility
            dtypes = set()
            for o in [a, b]:
                if hasattr(o, "dtypes"):
                    s = o.dtypes.value_counts()
                    if len(s) > 1:
                        return False
                    dtypes |= set(s.index.astype(str))
                elif isinstance(o, np.ndarray):
                    dtypes |= {o.dtype.name}

            # allowed are a superset
            if not len(dtypes) or _ALLOWED_DTYPES[dtype_check] >= dtypes:
                return True

    return False

def _normalize(table, normalize, margins, margins_name="All"):

    if not isinstance(normalize, (bool, str)):
        axis_subs = {0: "index", 1: "columns"}
        try:
            normalize = axis_subs[normalize]
        except KeyError:
            raise ValueError("Not a valid normalize argument")

    if margins is False:

        # Actual Normalizations
        normalizers = {
            "all": lambda x: x / x.sum(axis=1).sum(axis=0),
            "columns": lambda x: x / x.sum(),
            "index": lambda x: x.div(x.sum(axis=1), axis=0),
        }

        normalizers[True] = normalizers["all"]

        try:
            f = normalizers[normalize]
        except KeyError:
            raise ValueError("Not a valid normalize argument")

        table = f(table)
        table = table.fillna(0)

    elif margins is True:

        column_margin = table.loc[:, margins_name].drop(margins_name)
        index_margin = table.loc[margins_name, :].drop(margins_name)
        table = table.drop(margins_name, axis=1).drop(margins_name)
        # to keep index and columns names
        table_index_names = table.index.names
        table_columns_names = table.columns.names

        # Normalize core
        table = _normalize(table, normalize=normalize, margins=False)

        # Fix Margins
        if normalize == "columns":
            column_margin = column_margin / column_margin.sum()
            table = concat([table, column_margin], axis=1)
            table = table.fillna(0)

        elif normalize == "index":
            index_margin = index_margin / index_margin.sum()
            table = table.append(index_margin)
            table = table.fillna(0)

        elif normalize == "all" or normalize is True:
            column_margin = column_margin / column_margin.sum()
            index_margin = index_margin / index_margin.sum()
            index_margin.loc[margins_name] = 1
            table = concat([table, column_margin], axis=1)
            table = table.append(index_margin)

            table = table.fillna(0)

        else:
            raise ValueError("Not a valid normalize argument")

        table.index.names = table_index_names
        table.columns.names = table_columns_names

    else:
        raise ValueError("Not a valid margins argument")

    return table

def _prep_values(self, values: Optional[np.ndarray] = None) -> np.ndarray:
    """Convert input to numpy arrays for Cython routines"""
    if values is None:
        values = getattr(self._selected_obj, "values", self._selected_obj)

    # GH #12373 : rolling functions error on float32 data
    # make sure the data is coerced to float64
    if is_float_dtype(values.dtype):
        values = ensure_float64(values)
    elif is_integer_dtype(values.dtype):
        values = ensure_float64(values)
    elif needs_i8_conversion(values.dtype):
        raise NotImplementedError(
            "ops for {action} for this "
            "dtype {dtype} are not "
            "implemented".format(action=self._window_type, dtype=values.dtype)
        )
    else:
        try:
            values = ensure_float64(values)
        except (ValueError, TypeError):
            raise TypeError("cannot handle this type -> {0}".format(values.dtype))

    # Always convert inf to nan
    values[np.isinf(values)] = np.NaN

    return values

def __add__(self, other):
    other = lib.item_from_zerodim(other)
    if isinstance(other, (ABCSeries, ABCDataFrame)):
        return NotImplemented

    # scalar others
    elif other is NaT:
        result = self._add_nat()
    elif isinstance(other, (Tick, timedelta, np.timedelta64)):
        result = self._add_delta(other)
    elif isinstance(other, DateOffset):
        # specifically _not_ a Tick
        result = self._add_offset(other)
    elif isinstance(other, (datetime, np.datetime64)):
        result = self._add_datetimelike_scalar(other)
    elif lib.is_integer(other):
        # This check must come after the check for np.timedelta64
        # as is_integer returns True for these
        if not is_period_dtype(self):
            maybe_integer_op_deprecated(self)
        result = self._time_shift(other)

    # array-like others
    elif is_timedelta64_dtype(other):
        # TimedeltaIndex, ndarray[timedelta64]
        result = self._add_delta(other)
    elif is_offsetlike(other):
        # Array/Index of DateOffset objects
        result = self._addsub_offset_array(other, operator.add)
    elif is_datetime64_dtype(other) or is_datetime64tz_dtype(other):
        # DatetimeIndex, ndarray[datetime64]
        return self._add_datetime_arraylike(other)
    elif is_integer_dtype(other):
        if not is_period_dtype(self):
            maybe_integer_op_deprecated(self)
        result = self._addsub_int_array(other, operator.add)
    elif is_float_dtype(other):
        # Explicitly catch invalid dtypes
        raise TypeError(
            "cannot add {dtype}-dtype to {cls}".format(
                dtype=other.dtype, cls=type(self).__name__
            )
        )
    elif is_period_dtype(other):
        # if self is a TimedeltaArray and other is a PeriodArray with
        #  a timedelta-like (i.e. Tick) freq, this operation is valid.
        #  Defer to the PeriodArray implementation.
        # In remaining cases, this will end up raising TypeError.
        return NotImplemented
    elif is_extension_array_dtype(other):
        # Categorical op will raise; defer explicitly
        return NotImplemented
    else:  # pragma: no cover
        return NotImplemented

    if is_timedelta64_dtype(result) and isinstance(result, np.ndarray):
        from pandas.core.arrays import TimedeltaArray

        # TODO: infer freq?
        return TimedeltaArray(result)
    return result

def __rsub__(self, other):
    if is_datetime64_dtype(other) and is_timedelta64_dtype(self):
        # ndarray[datetime64] cannot be subtracted from self, so
        # we need to wrap in DatetimeArray/Index and flip the operation
        if not isinstance(other, DatetimeLikeArrayMixin):
            # Avoid down-casting DatetimeIndex
            from pandas.core.arrays import DatetimeArray

            other = DatetimeArray(other)
        return other - self
    elif (
        is_datetime64_any_dtype(self)
        and hasattr(other, "dtype")
        and not is_datetime64_any_dtype(other)
    ):
        # GH#19959 datetime - datetime is well-defined as timedelta,
        # but any other type - datetime is not well-defined.
        raise TypeError(
            "cannot subtract {cls} from {typ}".format(
                cls=type(self).__name__, typ=type(other).__name__
            )
        )
    elif is_period_dtype(self) and is_timedelta64_dtype(other):
        # TODO: Can we simplify/generalize these cases at all?
        raise TypeError(
            "cannot subtract {cls} from {dtype}".format(
                cls=type(self).__name__, dtype=other.dtype
            )
        )
    return -(self - other)

def __sub__(self, other):
    other = lib.item_from_zerodim(other)
    if isinstance(other, (ABCSeries, ABCDataFrame)):
        return NotImplemented

    # scalar others
    elif other is NaT:
        result = self._sub_nat()
    elif isinstance(other, (Tick, timedelta, np.timedelta64)):
        result = self._add_delta(-other)
    elif isinstance(other, DateOffset):
        # specifically _not_ a Tick
        result = self._add_offset(-other)
    elif isinstance(other, (datetime, np.datetime64)):
        result = self._sub_datetimelike_scalar(other)
    elif lib.is_integer(other):
        # This check must come after the check for np.timedelta64
        # as is_integer returns True for these
        if not is_period_dtype(self):
            maybe_integer_op_deprecated(self)
        result = self._time_shift(-other)

    elif isinstance(other, Period):
        result = self._sub_period(other)

    # array-like others
    elif is_timedelta64_dtype(other):
        # TimedeltaIndex, ndarray[timedelta64]
        result = self._add_delta(-other)
    elif is_offsetlike(other):
        # Array/Index of DateOffset objects
        result = self._addsub_offset_array(other, operator.sub)
    elif is_datetime64_dtype(other) or is_datetime64tz_dtype(other):
        # DatetimeIndex, ndarray[datetime64]
        result = self._sub_datetime_arraylike(other)
    elif is_period_dtype(other):
        # PeriodIndex
        result = self._sub_period_array(other)
    elif is_integer_dtype(other):
        if not is_period_dtype(self):
            maybe_integer_op_deprecated(self)
        result = self._addsub_int_array(other, operator.sub)
    elif isinstance(other, ABCIndexClass):
        raise TypeError(
            "cannot subtract {cls} and {typ}".format(
                cls=type(self).__name__, typ=type(other).__name__
            )
        )
    elif is_float_dtype(other):
        # Explicitly catch invalid dtypes
        raise TypeError(
            "cannot subtract {dtype}-dtype from {cls}".format(
                dtype=other.dtype, cls=type(self).__name__
            )
        )
    elif is_extension_array_dtype(other):
        # Categorical op will raise; defer explicitly
        return NotImplemented
    else:  # pragma: no cover
        return NotImplemented

    if is_timedelta64_dtype(result) and isinstance(result, np.ndarray):
        from pandas.core.arrays import TimedeltaArray

        # TODO: infer freq?
        return TimedeltaArray(result)
    return result

def _join_compat(
    self, other, on=None, how="left", lsuffix="", rsuffix="", sort=False
):
    from pandas.core.reshape.merge import merge
    from pandas.core.reshape.concat import concat

    if isinstance(other, Series):
        if other.name is None:
            raise ValueError("Other Series must have a name")
        other = DataFrame({other.name: other})

    if isinstance(other, DataFrame):
        return merge(
            self,
            other,
            left_on=on,
            how=how,
            left_index=on is None,
            right_index=True,
            suffixes=(lsuffix, rsuffix),
            sort=sort,
        )
    else:
        if on is not None:
            raise ValueError(
                "Joining multiple DataFrames only supported for joining on index"
            )

        frames = [self] + list(other)

        can_concat = all(df.index.is_unique for df in frames)

        # join indexes only using concat
        if can_concat:
            if how == "left":
                res = concat(frames, axis=1, join="outer", verify_integrity=True)
                return res.reindex(self.index, copy=False)
            else:
                return concat(frames, axis=1, join=how, verify_integrity=True)

        joined = frames[0]

        for frame in frames[1:]:
            joined = merge(
                joined, frame, how=how, left_index=True, right_index=True
            )

        return joined

def _get_partial_string_timestamp_match_key(self, key, labels):
    """Translate any partial string timestamp matches in key, returning the
    new key (GH 10331)"""
    if isinstance(labels, MultiIndex):
        if isinstance(key, str) and labels.levels[0].is_all_dates:
            # Convert key '2016-01-01' to
            # ('2016-01-01'[, slice(None, None, None)]+)
            key = tuple([key] + [slice(None)] * (len(labels.levels) - 1))

        if isinstance(key, tuple):
            # Convert (..., '2016-01-01', ...) in tuple to
            # (..., slice('2016-01-01', '2016-01-01', None), ...)
            new_key = []
            for i, component in enumerate(key):
                if isinstance(component, str) and labels.levels[i].is_all_dates:
                    new_key.append(slice(component, component, None))
                else:
                    new_key.append(component)
            key = tuple(new_key)

    return key

def convert_to_index_sliceable(obj, key):
    """
    if we are index sliceable, then return my slicer, otherwise return None
    """
    idx = obj.index
    if isinstance(key, slice):
        return idx._convert_slice_indexer(key, kind="getitem")

    elif isinstance(key, str):

        # we are an actual column
        if key in obj._data.items:
            return None

        # We might have a datetimelike string that we can translate to a
        # slice here via partial string indexing
        if idx.is_all_dates:
            try:
                return idx._get_string_slice(key)
            except (KeyError, ValueError, NotImplementedError):
                return None

    return None

def _get_grouper(
    obj,
    key=None,
    axis=0,
    level=None,
    sort=True,
    observed=False,
    mutated=False,
    validate=True,
):
    """
    create and return a BaseGrouper, which is an internal
    mapping of how to create the grouper indexers.
    This may be composed of multiple Grouping objects, indicating
    multiple groupers

    Groupers are ultimately index mappings. They can originate as:
    index mappings, keys to columns, functions, or Groupers

    Groupers enable local references to axis,level,sort, while
    the passed in axis, level, and sort are 'global'.

    This routine tries to figure out what the passing in references
    are and then creates a Grouping for each one, combined into
    a BaseGrouper.

    If observed & we have a categorical grouper, only show the observed
    values

    If validate, then check for key/level overlaps

    """
    group_axis = obj._get_axis(axis)

    # validate that the passed single level is compatible with the passed
    # axis of the object
    if level is not None:
        # TODO: These if-block and else-block are almost same.
        # MultiIndex instance check is removable, but it seems that there are
        # some processes only for non-MultiIndex in else-block,
        # eg. `obj.index.name != level`. We have to consider carefully whether
        # these are applicable for MultiIndex. Even if these are applicable,
        # we need to check if it makes no side effect to subsequent processes
        # on the outside of this condition.
        # (GH 17621)
        if isinstance(group_axis, MultiIndex):
            if is_list_like(level) and len(level) == 1:
                level = level[0]

            if key is None and is_scalar(level):
                # Get the level values from group_axis
                key = group_axis.get_level_values(level)
                level = None

        else:
            # allow level to be a length-one list-like object
            # (e.g., level=[0])
            # GH 13901
            if is_list_like(level):
                nlevels = len(level)
                if nlevels == 1:
                    level = level[0]
                elif nlevels == 0:
                    raise ValueError("No group keys passed!")
                else:
                    raise ValueError("multiple levels only valid with MultiIndex")

            if isinstance(level, str):
                if obj.index.name != level:
                    raise ValueError(
                        "level name {} is not the name of the index".format(level)
                    )
            elif level > 0 or level < -1:
                raise ValueError("level > 0 or level < -1 only valid with MultiIndex")

            # NOTE: `group_axis` and `group_axis.get_level_values(level)`
            # are same in this section.
            level = None
            key = group_axis

    # a passed-in Grouper, directly convert
    if isinstance(key, Grouper):
        binner, grouper, obj = key._get_grouper(obj, validate=False)
        if key.key is None:
            return grouper, [], obj
        else:
            return grouper, {key.key}, obj

    # already have a BaseGrouper, just return it
    elif isinstance(key, BaseGrouper):
        return key, [], obj

    # In the future, a tuple key will always mean an actual key,
    # not an iterable of keys. In the meantime, we attempt to provide
    # a warning. We can assume that the user wanted a list of keys when
    # the key is not in the index. We just have to be careful with
    # unhashable elements of `key`. Any unhashable elements implies that
    # they wanted a list of keys.
    # https://github.com/pandas-dev/pandas/issues/18314
    is_tuple = isinstance(key, tuple)
    all_hashable = is_tuple and is_hashable(key)

    if is_tuple:
        if (
            all_hashable and key not in obj and set(key).issubset(obj)
        ) or not all_hashable:
            # column names ('a', 'b') -> ['a', 'b']
            # arrays like (a, b) -> [a, b]
            msg = (
                "Interpreting tuple 'by' as a list of keys, rather than "
                "a single key. Use 'by=[...]' instead of 'by=(...)'. In "
                "the future, a tuple will always mean a single key."
            )
            warnings.warn(msg, FutureWarning, stacklevel=5)
            key = list(key)

    if not isinstance(key, list):
        keys = [key]
        match_axis_length = False
    else:
        keys = key
        match_axis_length = len(keys) == len(group_axis)

    # what are we after, exactly?
    any_callable = any(callable(g) or isinstance(g, dict) for g in keys)
    any_groupers = any(isinstance(g, Grouper) for g in keys)
    any_arraylike = any(
        isinstance(g, (list, tuple, Series, Index, np.ndarray)) for g in keys
    )

    # is this an index replacement?
    if (
        not any_callable
        and not any_arraylike
        and not any_groupers
        and match_axis_length
        and level is None
    ):
        if isinstance(obj, DataFrame):
            all_in_columns_index = all(
                g in obj.columns or g in obj.index.names for g in keys
            )
        elif isinstance(obj, Series):
            all_in_columns_index = all(g in obj.index.names for g in keys)

        if not all_in_columns_index:
            keys = [com.asarray_tuplesafe(keys)]

    if isinstance(level, (tuple, list)):
        if key is None:
            keys = [None] * len(level)
        levels = level
    else:
        levels = [level] * len(keys)

    groupings = []
    exclusions = []

    # if the actual grouper should be obj[key]
    def is_in_axis(key):
        if not _is_label_like(key):
            try:
                obj._data.items.get_loc(key)
            except Exception:
                return False

        return True

    # if the grouper is obj[name]
    def is_in_obj(gpr):
        try:
            return id(gpr) == id(obj[gpr.name])
        except Exception:
            return False

    for i, (gpr, level) in enumerate(zip(keys, levels)):

        if is_in_obj(gpr):  # df.groupby(df['name'])
            in_axis, name = True, gpr.name
            exclusions.append(name)

        elif is_in_axis(gpr):  # df.groupby('name')
            if gpr in obj:
                if validate:
                    obj._check_label_or_level_ambiguity(gpr)
                in_axis, name, gpr = True, gpr, obj[gpr]
                exclusions.append(name)
            elif obj._is_level_reference(gpr):
                in_axis, name, level, gpr = False, None, gpr, None
            else:
                raise KeyError(gpr)
        elif isinstance(gpr, Grouper) and gpr.key is not None:
            # Add key to exclusions
            exclusions.append(gpr.key)
            in_axis, name = False, None
        else:
            in_axis, name = False, None

        if is_categorical_dtype(gpr) and len(gpr) != obj.shape[axis]:
            raise ValueError(
                (
                    "Length of grouper ({len_gpr}) and axis ({len_axis})"
                    " must be same length".format(
                        len_gpr=len(gpr), len_axis=obj.shape[axis]
                    )
                )
            )

        # create the Grouping
        # allow us to passing the actual Grouping as the gpr
        ping = (
            Grouping(
                group_axis,
                gpr,
                obj=obj,
                name=name,
                level=level,
                sort=sort,
                observed=observed,
                in_axis=in_axis,
            )
            if not isinstance(gpr, Grouping)
            else gpr
        )

        groupings.append(ping)

    if len(groupings) == 0 and len(obj):
        raise ValueError("No group keys passed!")
    elif len(groupings) == 0:
        groupings.append(Grouping(Index([], dtype="int"), np.array([], dtype=np.intp)))

    # create the internals grouper
    grouper = BaseGrouper(group_axis, groupings, sort=sort, mutated=mutated)
    return grouper, exclusions, obj

def _get_addsub_freq(self, other) -> Optional[DateOffset]:
    """
    Find the freq we expect the result of an addition/subtraction operation
    to have.
    """
    if is_period_dtype(self.dtype):
        # Only used for ops that stay PeriodDtype
        return self.freq
    elif self.freq is None:
        return None
    elif lib.is_scalar(other) and isna(other):
        return None

    elif isinstance(other, (Tick, timedelta, np.timedelta64)):
        new_freq = None
        if isinstance(self.freq, Tick):
            new_freq = self.freq
        return new_freq

    elif isinstance(other, DateOffset):
        # otherwise just DatetimeArray
        return None  # TODO: Should we infer if it matches self.freq * n?
    elif isinstance(other, (datetime, np.datetime64)):
        return self.freq

    elif is_timedelta64_dtype(other):
        return None  # TODO: shouldnt we be able to do self.freq + other.freq?
    elif is_object_dtype(other):
        return None  # TODO: is this quite right?  sometimes we unpack singletons
    elif is_datetime64_any_dtype(other):
        return None  # TODO: shouldnt we be able to do self.freq + other.freq?
    else:
        raise NotImplementedError

def _validate_insert_value(self, value):
    if isinstance(value, self._recognized_scalars):
        value = self._scalar_type(value)
    elif is_valid_nat_for_dtype(value, self.dtype):
        # GH#18295
        value = NaT
    elif lib.is_scalar(value) and isna(value):
        raise TypeError(
            f"cannot insert {type(self).__name__} with incompatible label"
        )

    return value

def insert(self, loc, item):
    """
    Make new Index inserting new item at location

    Parameters
    ----------
    loc : int
    item : object
        if not either a Python datetime or a numpy integer-like, returned
        Index dtype will be object rather than datetime.

    Returns
    -------
    new_index : Index
    """
    item = self._data._validate_insert_value(item)

    freq = None
    if isinstance(item, self._data._scalar_type) or item is NaT:
        self._data._check_compatible_with(item, setitem=True)

        # check freq can be preserved on edge cases
        if self.size and self.freq is not None:
            if item is NaT:
                pass
            elif (loc == 0 or loc == -len(self)) and item + self.freq == self[0]:
                freq = self.freq
            elif (loc == len(self)) and item - self.freq == self[-1]:
                freq = self.freq
        elif self.freq is not None:
            # Adding a single item to an empty index may preserve freq
            if self.freq.is_on_offset(item):
                freq = self.freq
        item = item.asm8

    try:
        new_i8s = np.concatenate(
            (self[:loc].asi8, [item.view(np.int64)], self[loc:].asi8)
        )
        arr = type(self._data)._simple_new(new_i8s, dtype=self.dtype, freq=freq)
        return type(self)._simple_new(arr, name=self.name)
    except (AttributeError, TypeError) as err:

        # fall back to object index
        if isinstance(item, str):
            return self.astype(object).insert(loc, item)
        raise TypeError(
            f"cannot insert {type(self).__name__} with incompatible label"
        ) from err

def _getitem_axis(self, key, axis: int):
    key = item_from_zerodim(key)
    if is_iterator(key):
        key = list(key)

    labels = self.obj._get_axis(axis)
    key = labels._get_partial_string_timestamp_match_key(key)

    if isinstance(key, slice):
        self._validate_key(key, axis)
        return self._get_slice_axis(key, axis=axis)
    elif com.is_bool_indexer(key):
        return self._getbool_axis(key, axis=axis)
    elif is_list_like_indexer(key):

        # convert various list-like indexers
        # to a list of keys
        # we will use the *values* of the object
        # and NOT the index if its a PandasObject
        if isinstance(labels, ABCMultiIndex):

            if isinstance(key, (ABCSeries, np.ndarray)) and key.ndim <= 1:
                # Series, or 0,1 ndim ndarray
                # GH 14730
                key = list(key)
            elif isinstance(key, ABCDataFrame):
                # GH 15438
                raise NotImplementedError(
                    "Indexing a MultiIndex with a "
                    "DataFrame key is not "
                    "implemented"
                )
            elif hasattr(key, "ndim") and key.ndim > 1:
                raise NotImplementedError(
                    "Indexing a MultiIndex with a "
                    "multidimensional key is not "
                    "implemented"
                )

            if (
                not isinstance(key, tuple)
                and len(key)
                and not isinstance(key[0], tuple)
            ):
                key = tuple([key])

        # an iterable multi-selection
        if not (isinstance(key, tuple) and isinstance(labels, ABCMultiIndex)):

            if hasattr(key, "ndim") and key.ndim > 1:
                raise ValueError("Cannot index with multidimensional key")

            return self._getitem_iterable(key, axis=axis)

        # nested tuple slicing
        if is_nested_tuple(key, labels):
            locs = labels.get_locs(key)
            indexer = [slice(None)] * self.ndim
            indexer[axis] = locs
            return self.obj.iloc[tuple(indexer)]

    # fall thru to straight lookup
    self._validate_key(key, axis)
    return self._get_label(key, axis=axis)

def is_excluded_dtype(dtype) -> bool:
    """
    These have kind = "O" but aren't string dtypes so need to be explicitly excluded
    """
    is_excluded_checks = (is_period_dtype, is_interval_dtype)
    return any(is_excluded(dtype) for is_excluded in is_excluded_checks)

