def _get_with(self, key):
    # other: fancy integer or otherwise
    if isinstance(key, slice):
        # _convert_slice_indexer to determin if this slice is positional
        #  or label based, and if the latter, convert to positional
        slobj = self.index._convert_slice_indexer(key, kind="getitem")
        return self._slice(slobj)
    elif isinstance(key, ABCDataFrame):
        raise TypeError(
            "Indexing a Series with DataFrame is not "
            "supported, use the appropriate DataFrame column"
        )
    elif isinstance(key, tuple):
        return self._get_values_tuple(key)

    elif not is_list_like(key):
        # e.g. scalars that aren't recognized by lib.is_scalar, GH#32684
        return self.loc[key]

    if not isinstance(key, (list, np.ndarray, ExtensionArray, Series, Index)):
        key = list(key)

    if isinstance(key, Index):
        key_type = key.inferred_type
    else:
        key_type = lib.infer_dtype(key, skipna=False)

    # Note: The key_type == "boolean" case should be caught by the
    #  com.is_bool_indexer check in __getitem__
    if key_type == "integer":
        # We need to decide whether to treat this as a positional indexer
        #  (i.e. self.iloc) or label-based (i.e. self.loc)
        if not self.index._should_fallback_to_positional():
            return self.loc[key]
        else:
            return self.iloc[key]

    if isinstance(key, list):
        # handle the dup indexing case GH#4246
        return self.loc[key]

    return self.reindex(key)

@Substitution(name="rolling")
@Appender(_shared_docs["count"])
def count(self):

    # different impl for freq counting
    if self.is_freq_type:
        window_func = self._get_roll_func("roll_count")
        return self._apply(window_func, center=self.center, name="count")

    return super().count()

def intersection(self, other, sort=False):
    """
    Specialized intersection for DatetimeIndex/TimedeltaIndex.

    May be much faster than Index.intersection

    Parameters
    ----------
    other : Same type as self or array-like
    sort : False or None, default False
        Sort the resulting index if possible.

        .. versionadded:: 0.24.0

        .. versionchanged:: 0.24.1

           Changed the default to ``False`` to match the behaviour
           from before 0.24.0.

        .. versionchanged:: 0.25.0

           The `sort` keyword is added

    Returns
    -------
    y : Index or same type as self
    """
    self._validate_sort_keyword(sort)
    self._assert_can_do_setop(other)

    if self.equals(other):
        return self._get_reconciled_name_object(other)

    if len(self) == 0:
        return self.copy()
    if len(other) == 0:
        return other.copy()

    if not isinstance(other, type(self)):
        result = Index.intersection(self, other, sort=sort)
        if isinstance(result, type(self)):
            if result.freq is None:
                result._set_freq("infer")
        return result

    elif (
        other.freq is None
        or self.freq is None
        or other.freq != self.freq
        or not other.freq.is_anchored()
        or (not self.is_monotonic or not other.is_monotonic)
    ):
        result = Index.intersection(self, other, sort=sort)

        # Invalidate the freq of `result`, which may not be correct at
        # this point, depending on the values.

        result._set_freq(None)
        result = self._shallow_copy(result._data, name=result.name)
        if result.freq is None:
            result._set_freq("infer")
        return result

    # to make our life easier, "sort" the two ranges
    if self[0] <= other[0]:
        left, right = self, other
    else:
        left, right = other, self

    # after sorting, the intersection always starts with the right index
    # and ends with the index of which the last elements is smallest
    end = min(left[-1], right[-1])
    start = right[0]

    if end < start:
        return type(self)(data=[])
    else:
        lslice = slice(*left.slice_locs(start, end))
        left_chunk = left.values[lslice]
        return self._shallow_copy(left_chunk)

def __setitem__(self, key, value):
    if isinstance(key, tuple):
        key = tuple(com.apply_if_callable(x, self.obj) for x in key)
    else:
        # scalar callable may return tuple
        key = com.apply_if_callable(key, self.obj)

    if not isinstance(key, tuple):
        key = _tuplify(self.ndim, key)
    if len(key) != self.ndim:
        raise ValueError("Not enough indexers for scalar access (setting)!")

    key = list(self._convert_key(key, is_setter=True))
    self.obj._set_value(*key, value=value, takeable=self._takeable)

def _try_convert_to_date(self, data):
    """
    Try to parse a ndarray like into a date column.

    Try to coerce object in epoch/iso formats and integer/float in epoch
    formats. Return a boolean if parsing was successful.
    """
    # no conversion on empty
    if not len(data):
        return data, False

    new_data = data
    if new_data.dtype == "object":
        try:
            new_data = data.astype("int64")
        except (TypeError, ValueError, OverflowError):
            pass

    # ignore numbers that are out of range
    if issubclass(new_data.dtype.type, np.number):
        in_range = (
            isna(new_data._values)
            | (new_data > self.min_stamp)
            | (new_data._values == iNaT)
        )
        if not in_range.all():
            return data, False

    date_units = (self.date_unit,) if self.date_unit else self._STAMP_UNITS
    for date_unit in date_units:
        try:
            new_data = to_datetime(new_data, errors="raise", unit=date_unit)
        except (ValueError, OverflowError):
            continue
        return new_data, True
    return data, False

def pre_processor(vals: np.ndarray) -> Tuple[np.ndarray, Optional[Type]]:
    if is_object_dtype(vals):
        raise TypeError(
            "'quantile' cannot be performed against 'object' dtypes!"
        )

    inference = None
    if is_integer_dtype(vals):
        inference = np.int64
    elif is_datetime64_dtype(vals):
        inference = "datetime64[ns]"
        vals = np.asarray(vals).astype(np.float)

    return vals, inference

def __init__(
    self, filepath_or_buffer, index=None, encoding="ISO-8859-1", chunksize=None
):

    self._encoding = encoding
    self._lines_read = 0
    self._index = index
    self._chunksize = chunksize

    if isinstance(filepath_or_buffer, str):
        (
            filepath_or_buffer,
            encoding,
            compression,
            should_close,
        ) = get_filepath_or_buffer(filepath_or_buffer, encoding=encoding)

    if isinstance(filepath_or_buffer, (str, bytes)):
        self.filepath_or_buffer = open(filepath_or_buffer, "rb")
    else:
        # Copy to BytesIO, and ensure no encoding
        contents = filepath_or_buffer.read()
        try:
            contents = contents.encode(self._encoding)
        except UnicodeEncodeError:
            pass
        self.filepath_or_buffer = BytesIO(contents)

    self._read_header()

@cache_readonly
def _engine(self):
    # To avoid a reference cycle, pass a weakref of self to _engine_type.
    period = weakref.ref(self)
    return self._engine_type(period, len(self))

def set(self, locs, values, check=False):
    assert locs.tolist() == [0]
    self.values = values

@Appender(doc)
def f(self, other, axis=default_axis, level=None, fill_value=None):

    if _should_reindex_frame_op(self, other, axis, default_axis, fill_value, level):
        return _frame_arith_method_with_reindex(self, other, op)

    self, other = _align_method_FRAME(self, other, axis, flex=True, level=level)

    if isinstance(other, ABCDataFrame):
        # Another DataFrame
        pass_op = op if should_series_dispatch(self, other, op) else na_op
        pass_op = pass_op if not is_logical else op

        new_data = self._combine_frame(other, pass_op, fill_value)
        return self._construct_result(new_data)

    elif isinstance(other, ABCSeries):
        # For these values of `axis`, we end up dispatching to Series op,
        # so do not want the masked op.
        pass_op = op if axis in [0, "columns", None] else na_op
        pass_op = pass_op if not is_logical else op

        if fill_value is not None:
            raise NotImplementedError(f"fill_value {fill_value} not supported.")

        axis = self._get_axis_number(axis) if axis is not None else 1
        return _combine_series_frame(
            self, other, pass_op, axis=axis, str_rep=str_rep
        )
    else:
        # in this case we always have `np.ndim(other) == 0`
        if fill_value is not None:
            self = self.fillna(fill_value)

        new_data = dispatch_to_series(self, other, op, str_rep)
        return self._construct_result(new_data)

def _should_reindex_frame_op(
    left: "DataFrame", right, axis, default_axis: int, fill_value, level
) -> bool:
    """
    Check if this is an operation between DataFrames that will need to reindex.
    """
    assert isinstance(left, ABCDataFrame)

    if not isinstance(right, ABCDataFrame):
        return False

    if fill_value is None and level is None and axis is default_axis:
        # TODO: any other cases we should handle here?
        cols = left.columns.intersection(right.columns)
        if not (cols.equals(left.columns) and cols.equals(right.columns)):
            return True

    return False

@Appender(_index_shared_docs["get_indexer_non_unique"] % _index_doc_kwargs)
def get_indexer_non_unique(self, target):
    target = ensure_index(target)
    pself, ptarget = self._maybe_promote(target)
    if pself is not self or ptarget is not target:
        return pself.get_indexer_non_unique(ptarget)

    if is_categorical(target):
        tgt_values = np.asarray(target)
    elif self.is_all_dates and target.is_all_dates:  # GH 30399
        tgt_values = target.asi8
    else:
        tgt_values = target._get_engine_target()

    indexer, missing = self._engine.get_indexer_non_unique(tgt_values)
    return ensure_platform_int(indexer), missing

@Appender(_index_shared_docs["get_indexer_non_unique"] % _index_doc_kwargs)
def get_indexer_non_unique(self, target):
    target = ensure_index(target)

    if isinstance(target, PeriodIndex):
        if target.freq != self.freq:
            no_matches = -1 * np.ones(self.shape, dtype=np.intp)
            return no_matches, no_matches

        target = target.asi8

    indexer, missing = self._int64index.get_indexer_non_unique(target)
    return ensure_platform_int(indexer), missing

@unpack_zerodim_and_defer(opname)
def func(self, other):
    if is_list_like(other) and len(other) != len(self):
        # TODO: Could this fail if the categories are listlike objects?
        raise ValueError("Lengths must match.")

    if not self.ordered:
        if opname in ["__lt__", "__gt__", "__le__", "__ge__"]:
            raise TypeError(
                "Unordered Categoricals can only compare equality or not"
            )
    if isinstance(other, Categorical):
        # Two Categoricals can only be be compared if the categories are
        # the same (maybe up to ordering, depending on ordered)

        msg = "Categoricals can only be compared if 'categories' are the same."
        if len(self.categories) != len(other.categories):
            raise TypeError(msg + " Categories are different lengths")
        elif self.ordered and not (self.categories == other.categories).all():
            raise TypeError(msg)
        elif not set(self.categories) == set(other.categories):
            raise TypeError(msg)

        if not (self.ordered == other.ordered):
            raise TypeError(
                "Categoricals can only be compared if 'ordered' is the same"
            )
        if not self.ordered and not self.categories.equals(other.categories):
            # both unordered and different order
            other_codes = _get_codes_for_values(other, self.categories)
        else:
            other_codes = other._codes

        f = getattr(self._codes, opname)
        ret = f(other_codes)
        mask = (self._codes == -1) | (other_codes == -1)
        if mask.any():
            # In other series, the leads to False, so do that here too
            ret[mask] = False
        return ret

    if is_scalar(other):
        if other in self.categories:
            i = self.categories.get_loc(other)
            ret = getattr(self._codes, opname)(i)

            if opname not in {"__eq__", "__ge__", "__gt__"}:
                # check for NaN needed if we are not equal or larger
                mask = self._codes == -1
                ret[mask] = False
            return ret
        else:
            if opname == "__eq__":
                return np.zeros(len(self), dtype=bool)
            elif opname == "__ne__":
                return np.ones(len(self), dtype=bool)
            else:
                raise TypeError(
                    f"Cannot compare a Categorical for op {opname} with a "
                    "scalar, which is not a category."
                )
    else:

        # allow categorical vs object dtype array comparisons for equality
        # these are only positional comparisons
        if opname in ["__eq__", "__ne__"]:
            return getattr(np.array(self), opname)(np.array(other))

        raise TypeError(
            f"Cannot compare a Categorical for op {opname} with "
            f"type {type(other)}.\nIf you want to compare values, "
            "use 'np.asarray(cat) <op> other'."
        )

def _iget_item_cache(self, item):
    """Return the cached item, item represents a positional indexer."""
    ax = self._info_axis
    if ax.is_unique:
        lower = self._get_item_cache(ax[item])
    else:
        lower = self._take_with_is_copy(item, axis=self._info_axis_number)
    return lower

def corr(self, other=None, pairwise=None, **kwargs):
    if other is None:
        other = self._selected_obj
        # only default unset
        pairwise = True if pairwise is None else pairwise
    other = self._shallow_copy(other)
    window = self._get_window(other)

    def _get_corr(a, b):
        a = a.rolling(
            window=window, min_periods=self.min_periods, center=self.center
        )
        b = b.rolling(
            window=window, min_periods=self.min_periods, center=self.center
        )

        return a.cov(b, **kwargs) / (a.std(**kwargs) * b.std(**kwargs))

    return _flex_binary_moment(
        self._selected_obj, other._selected_obj, _get_corr, pairwise=bool(pairwise)
    )

def _get_with(self, key):
    # other: fancy integer or otherwise
    if isinstance(key, slice):
        return self._slice(key)
    elif isinstance(key, ABCDataFrame):
        raise TypeError(
            "Indexing a Series with DataFrame is not "
            "supported, use the appropriate DataFrame column"
        )
    elif isinstance(key, tuple):
        try:
            return self._get_values_tuple(key)
        except ValueError:
            # if we don't have a MultiIndex, we may still be able to handle
            #  a 1-tuple.  see test_1tuple_without_multiindex
            if len(key) == 1:
                key = key[0]
                if isinstance(key, slice):
                    return self._get_values(key)
            raise

    if not isinstance(key, (list, np.ndarray, Series, Index)):
        key = list(key)

    if isinstance(key, Index):
        key_type = key.inferred_type
    else:
        key_type = lib.infer_dtype(key, skipna=False)

    # Note: The key_type == "boolean" case should be caught by the
    #  com.is_bool_indexer check in __getitem__
    if key_type == "integer":
        if self.index.is_integer() or self.index.is_floating():
            return self.loc[key]
        elif isinstance(self.index, IntervalIndex):
            indexer = self.index.get_indexer_for(key)
            return self.iloc[indexer]
        else:
            return self._get_values(key)

    if isinstance(key, (list, tuple)):
        # TODO: de-dup with tuple case handled above?
        # handle the dup indexing case GH#4246
        if len(key) == 1 and isinstance(key[0], slice):
            # [slice(0, 5, None)] will break if you convert to ndarray,
            # e.g. as requested by np.median
            # FIXME: hack
            return self._get_values(key)

        return self.loc[key]

    return self.reindex(key)

def _convert_key(self, key, is_setter: bool = False):
    """
    Require they keys to be the same type as the index. (so we don't
    fallback)
    """
    # allow arbitrary setting
    if is_setter:
        return list(key)

    for ax, i in zip(self.obj.axes, key):
        if ax.is_integer():
            if not is_integer(i):
                raise ValueError(
                    "At based indexing on an integer index "
                    "can only have integer indexers"
                )
        else:
            if is_integer(i) and not (ax.holds_integer() or ax.is_floating()):
                raise ValueError(
                    "At based indexing on an non-integer "
                    "index can only have non-integer "
                    "indexers"
                )
    return key

def __init__(self, src, **kwds):
    self.kwds = kwds
    kwds = kwds.copy()

    ParserBase.__init__(self, kwds)

    encoding = kwds.get("encoding")

    if kwds.get("compression") is None and encoding:
        if isinstance(src, str):
            src = open(src, "rb")
            self.handles.append(src)

        # Handle the file object with universal line mode enabled.
        # We will handle the newline character ourselves later on.
        if isinstance(src, BufferedIOBase):
            src = TextIOWrapper(src, encoding=encoding, newline="")

        kwds["encoding"] = "utf-8"

    # #2442
    kwds["allow_leading_cols"] = self.index_col is not False

    # GH20529, validate usecol arg before TextReader
    self.usecols, self.usecols_dtype = _validate_usecols_arg(kwds["usecols"])
    kwds["usecols"] = self.usecols

    self._reader = parsers.TextReader(src, **kwds)
    self.unnamed_cols = self._reader.unnamed_cols

    passed_names = self.names is None

    if self._reader.header is None:
        self.names = None
    else:
        if len(self._reader.header) > 1:
            # we have a multi index in the columns
            (
                self.names,
                self.index_names,
                self.col_names,
                passed_names,
            ) = self._extract_multi_indexer_columns(
                self._reader.header, self.index_names, self.col_names, passed_names
            )
        else:
            self.names = list(self._reader.header[0])

    if self.names is None:
        if self.prefix:
            self.names = [
                f"{self.prefix}{i}" for i in range(self._reader.table_width)
            ]
        else:
            self.names = list(range(self._reader.table_width))

    # gh-9755
    #
    # need to set orig_names here first
    # so that proper indexing can be done
    # with _set_noconvert_columns
    #
    # once names has been filtered, we will
    # then set orig_names again to names
    self.orig_names = self.names[:]

    if self.usecols:
        usecols = _evaluate_usecols(self.usecols, self.orig_names)

        # GH 14671
        if self.usecols_dtype == "string" and not set(usecols).issubset(
            self.orig_names
        ):
            _validate_usecols_names(usecols, self.orig_names)

        if len(self.names) > len(usecols):
            self.names = [
                n
                for i, n in enumerate(self.names)
                if (i in usecols or n in usecols)
            ]

        if len(self.names) < len(usecols):
            _validate_usecols_names(usecols, self.names)

    self._set_noconvert_columns()

    self.orig_names = self.names

    if not self._has_complex_date_col:
        if self._reader.leading_cols == 0 and _is_index_col(self.index_col):

            self._name_processed = True
            (index_names, self.names, self.index_col) = _clean_index_names(
                self.names, self.index_col, self.unnamed_cols
            )

            if self.index_names is None:
                self.index_names = index_names

        if self._reader.header is None and not passed_names:
            self.index_names = [None] * len(self.index_names)

    self._implicit_index = self._reader.leading_cols > 0

def _convert_key(self, key, is_setter: bool = False):
    """
    Require they keys to be the same type as the index. (so we don't
    fallback)
    """
    # allow arbitrary setting
    if is_setter:
        return list(key)

    for ax, i in zip(self.obj.axes, key):
        if ax.is_integer():
            if not is_integer(i):
                raise ValueError(
                    "At based indexing on an integer index "
                    "can only have integer indexers"
                )
        else:
            if is_integer(i) and not ax.holds_integer():
                raise ValueError(
                    "At based indexing on an non-integer "
                    "index can only have non-integer "
                    "indexers"
                )
    return key

def is_in_obj(gpr) -> bool:
    if not hasattr(gpr, "name"):
        return False
    try:
        return gpr is obj[gpr.name]
    except (KeyError, IndexError):
        return False

def _combine_match_index(self, other, func):
    # at this point we have `self.index.equals(other.index)`

    if ops.should_series_dispatch(self, other, func):
        # operate column-wise; avoid costly object-casting in `.values`
        new_data = ops.dispatch_to_series(self, other, func)
    else:
        # fastpath --> operate directly on values
        with np.errstate(all="ignore"):
            new_data = func(self.values.T, other.values).T
    return new_data

def __new__(
    cls,
    data=None,
    unit=None,
    freq=None,
    closed=None,
    dtype=_TD_DTYPE,
    copy=False,
    name=None,
):
    name = maybe_extract_name(name, data, cls)

    if is_scalar(data):
        raise TypeError(
            f"{cls.__name__}() must be called with a "
            f"collection of some kind, {repr(data)} was passed"
        )

    if unit in {"Y", "y", "M"}:
        raise ValueError(
            "Units 'M' and 'Y' are no longer supported, as they do not "
            "represent unambiguous timedelta values durations."
        )

    if isinstance(data, TimedeltaArray):
        if copy:
            data = data.copy()
        return cls._simple_new(data, name=name, freq=freq)

    if isinstance(data, TimedeltaIndex) and freq is None and name is None:
        if copy:
            return data.copy()
        else:
            return data._shallow_copy()

    # - Cases checked above all return/raise before reaching here - #

    tdarr = TimedeltaArray._from_sequence(
        data, freq=freq, unit=unit, dtype=dtype, copy=copy
    )
    return cls._simple_new(tdarr, name=name)

def get_loc(self, key, method=None, tolerance=None):
    """
    Get integer location for requested label.

    Parameters
    ----------
    key : Period, NaT, str, or datetime
        String or datetime key must be parseable as Period.

    Returns
    -------
    loc : int or ndarray[int64]

    Raises
    ------
    KeyError
        Key is not present in the index.
    TypeError
        If key is listlike or otherwise not hashable.
    """

    if isinstance(key, str):
        try:
            return self._get_string_slice(key)
        except (TypeError, KeyError, ValueError, OverflowError):
            pass

        try:
            asdt, reso = parse_time_string(key, self.freq)
            key = asdt
        except DateParseError:
            # A string with invalid format
            raise KeyError(f"Cannot interpret '{key}' as period")

    elif is_integer(key):
        # Period constructor will cast to string, which we dont want
        raise KeyError(key)

    try:
        key = Period(key, freq=self.freq)
    except ValueError:
        # we cannot construct the Period
        # as we have an invalid type
        if is_list_like(key):
            raise TypeError(f"'{key}' is an invalid key")
        raise KeyError(key)

    ordinal = key.ordinal if key is not NaT else key.value
    try:
        return self._engine.get_loc(ordinal)
    except KeyError:

        try:
            if tolerance is not None:
                tolerance = self._convert_tolerance(tolerance, np.asarray(key))
            return self._int64index.get_loc(ordinal, method, tolerance)

        except KeyError:
            raise KeyError(key)

def _try_convert_data(self, name, data, use_dtypes=True, convert_dates=True):
    """
    Try to parse a ndarray like into a column by inferring dtype.
    """

    # don't try to coerce, unless a force conversion
    if use_dtypes:
        if not self.dtype:
            return data, False
        elif self.dtype is True:
            pass
        else:
            # dtype to force
            dtype = (
                self.dtype.get(name) if isinstance(self.dtype, dict) else self.dtype
            )
            if dtype is not None:
                try:
                    dtype = np.dtype(dtype)
                    return data.astype(dtype), True
                except (TypeError, ValueError):
                    return data, False

    if convert_dates:
        new_data, result = self._try_convert_to_date(data)
        if result:
            return new_data, True

    result = False

    if data.dtype == "object":

        # try float
        try:
            data = data.astype("float64")
            result = True
        except (TypeError, ValueError):
            pass

    if data.dtype.kind == "f":

        if data.dtype != "float64":

            # coerce floats to 64
            try:
                data = data.astype("float64")
                result = True
            except (TypeError, ValueError):
                pass

    # don't coerce 0-len data
    if len(data) and (data.dtype == "float" or data.dtype == "object"):

        # coerce ints if we can
        try:
            new_data = data.astype("int64")
            if (new_data == data).all():
                data = new_data
                result = True
        except (TypeError, ValueError):
            pass

    # coerce ints to 64
    if data.dtype == "int":

        # coerce floats to 64
        try:
            data = data.astype("int64")
            result = True
        except (TypeError, ValueError):
            pass

    return data, result

def _reduce(
    self, op, name, axis=0, skipna=True, numeric_only=None, filter_type=None, **kwds
):
    if axis is None and filter_type == "bool":
        labels = None
        constructor = None
    else:
        # TODO: Make other agg func handle axis=None properly
        axis = self._get_axis_number(axis)
        labels = self._get_agg_axis(axis)
        constructor = self._constructor

    def f(x):
        return op(x, axis=axis, skipna=skipna, **kwds)

    def _get_data(axis_matters):
        if filter_type is None or filter_type == "numeric":
            data = self._get_numeric_data()
        elif filter_type == "bool":
            if axis_matters:
                # GH#25101, GH#24434
                data = self._get_bool_data() if axis == 0 else self
            else:
                data = self._get_bool_data()
        else:  # pragma: no cover
            msg = (
                f"Generating numeric_only data with filter_type {filter_type} "
                "not supported."
            )
            raise NotImplementedError(msg)
        return data

    if numeric_only is not None and axis in [0, 1]:
        df = self
        if numeric_only is True:
            df = _get_data(axis_matters=True)
        if axis == 1:
            df = df.T
            axis = 0

        out_dtype = "bool" if filter_type == "bool" else None

        # After possibly _get_data and transposing, we are now in the
        #  simple case where we can use BlockManager._reduce
        res = df._data.reduce(op, axis=1, skipna=skipna, **kwds)
        assert isinstance(res, dict)
        if len(res):
            assert len(res) == max(list(res.keys())) + 1, res.keys()
        out = df._constructor_sliced(res, index=range(len(res)), dtype=out_dtype)
        out.index = df.columns
        return out

    if numeric_only is None:
        values = self.values
        try:
            result = f(values)

            if filter_type == "bool" and is_object_dtype(values) and axis is None:
                # work around https://github.com/numpy/numpy/issues/10489
                # TODO: combine with hasattr(result, 'dtype') further down
                # hard since we don't have `values` down there.
                result = np.bool_(result)
        except TypeError:
            # e.g. in nanops trying to convert strs to float

            # try by-column first
            if filter_type is None and axis == 0:
                # this can end up with a non-reduction
                # but not always. if the types are mixed
                # with datelike then need to make sure a series

                # we only end up here if we have not specified
                # numeric_only and yet we have tried a
                # column-by-column reduction, where we have mixed type.
                # So let's just do what we can
                from pandas.core.apply import frame_apply

                opa = frame_apply(
                    self, func=f, result_type="expand", ignore_failures=True
                )
                result = opa.get_result()
                if result.ndim == self.ndim:
                    result = result.iloc[0]
                return result

            # TODO: why doesnt axis matter here?
            data = _get_data(axis_matters=False)
            with np.errstate(all="ignore"):
                result = f(data.values)
            labels = data._get_agg_axis(axis)
    else:
        if numeric_only:
            data = _get_data(axis_matters=True)

            values = data.values
            labels = data._get_agg_axis(axis)
        else:
            values = self.values
        result = f(values)

    if hasattr(result, "dtype") and is_object_dtype(result.dtype):
        try:
            if filter_type is None or filter_type == "numeric":
                result = result.astype(np.float64)
            elif filter_type == "bool" and notna(result).all():
                result = result.astype(np.bool_)
        except (ValueError, TypeError):

            # try to coerce to the original dtypes item by item if we can
            if axis == 0:
                result = coerce_to_dtypes(result, self.dtypes)

    if constructor is not None:
        result = Series(result, index=labels)
    return result

def is_in_axis(key) -> bool:
    if not _is_label_like(key):
        items = obj._data.items
        try:
            items.get_loc(key)
        except (KeyError, TypeError):
            # TypeError shows up here if we pass e.g. Int64Index
            return False

    return True

def get_loc_level(self, key, level=0, drop_level: bool = True):
    """
    Get both the location for the requested label(s) and the
    resulting sliced index.

    Parameters
    ----------
    key : label or sequence of labels
    level : int/level name or list thereof, optional
    drop_level : bool, default True
        If ``False``, the resulting index will not drop any level.

    Returns
    -------
    loc : A 2-tuple where the elements are:
          Element 0: int, slice object or boolean array
          Element 1: The resulting sliced multiindex/index. If the key
          contains all levels, this will be ``None``.

    See Also
    --------
    MultiIndex.get_loc  : Get location for a label or a tuple of labels.
    MultiIndex.get_locs : Get location for a label/slice/list/mask or a
                          sequence of such.

    Examples
    --------
    >>> mi = pd.MultiIndex.from_arrays([list('abb'), list('def')],
    ...                                names=['A', 'B'])

    >>> mi.get_loc_level('b')
    (slice(1, 3, None), Index(['e', 'f'], dtype='object', name='B'))

    >>> mi.get_loc_level('e', level='B')
    (array([False,  True, False], dtype=bool),
    Index(['b'], dtype='object', name='A'))

    >>> mi.get_loc_level(['b', 'e'])
    (1, None)
    """

    # different name to distinguish from maybe_droplevels
    def maybe_mi_droplevels(indexer, levels, drop_level: bool):
        if not drop_level:
            return self[indexer]
        # kludgearound
        orig_index = new_index = self[indexer]
        levels = [self._get_level_number(i) for i in levels]
        for i in sorted(levels, reverse=True):
            try:
                new_index = new_index.droplevel(i)
            except ValueError:

                # no dropping here
                return orig_index
        return new_index

    if isinstance(level, (tuple, list)):
        if len(key) != len(level):
            raise AssertionError(
                "Key for location must have same length as number of levels"
            )
        result = None
        for lev, k in zip(level, key):
            loc, new_index = self.get_loc_level(k, level=lev)
            if isinstance(loc, slice):
                mask = np.zeros(len(self), dtype=bool)
                mask[loc] = True
                loc = mask

            result = loc if result is None else result & loc

        return result, maybe_mi_droplevels(result, level, drop_level)

    level = self._get_level_number(level)

    # kludge for #1796
    if isinstance(key, list):
        key = tuple(key)

    if isinstance(key, tuple) and level == 0:

        try:
            if key in self.levels[0]:
                indexer = self._get_level_indexer(key, level=level)
                new_index = maybe_mi_droplevels(indexer, [0], drop_level)
                return indexer, new_index
        except TypeError:
            pass

        if not any(isinstance(k, slice) for k in key):

            # partial selection
            # optionally get indexer to avoid re-calculation
            def partial_selection(key, indexer=None):
                if indexer is None:
                    indexer = self.get_loc(key)
                ilevels = [
                    i for i in range(len(key)) if key[i] != slice(None, None)
                ]
                return indexer, maybe_mi_droplevels(indexer, ilevels, drop_level)

            if len(key) == self.nlevels and self.is_unique:
                # Complete key in unique index -> standard get_loc
                try:
                    return (self._engine.get_loc(key), None)
                except KeyError as e:
                    raise KeyError(key) from e
            else:
                return partial_selection(key)
        else:
            indexer = None
            for i, k in enumerate(key):
                if not isinstance(k, slice):
                    k = self._get_level_indexer(k, level=i)
                    if isinstance(k, slice):
                        # everything
                        if k.start == 0 and k.stop == len(self):
                            k = slice(None, None)
                    else:
                        k_index = k

                if isinstance(k, slice):
                    if k == slice(None, None):
                        continue
                    else:
                        raise TypeError(key)

                if indexer is None:
                    indexer = k_index
                else:  # pragma: no cover
                    indexer &= k_index
            if indexer is None:
                indexer = slice(None, None)
            ilevels = [i for i in range(len(key)) if key[i] != slice(None, None)]
            return indexer, maybe_mi_droplevels(indexer, ilevels, drop_level)
    else:
        indexer = self._get_level_indexer(key, level=level)
        return indexer, maybe_mi_droplevels(indexer, [level], drop_level)

def __invert__(self):
    if not self.size:
        # inv fails with 0 len
        return self

    arr = operator.inv(com.values_from_object(self))
    return self.__array_wrap__(arr)

def _get_empty_dtype_and_na(join_units):
    """
    Return dtype and N/A values to use when concatenating specified units.

    Returned N/A value may be None which means there was no casting involved.

    Returns
    -------
    dtype
    na
    """
    if len(join_units) == 1:
        blk = join_units[0].block
        if blk is None:
            return np.float64, np.nan

    if _is_uniform_reindex(join_units):
        # FIXME: integrate property
        empty_dtype = join_units[0].block.dtype
        upcasted_na = join_units[0].block.fill_value
        return empty_dtype, upcasted_na

    has_none_blocks = False
    dtypes = [None] * len(join_units)
    for i, unit in enumerate(join_units):
        if unit.block is None:
            has_none_blocks = True
        else:
            dtypes[i] = unit.dtype

    upcast_classes = defaultdict(list)
    null_upcast_classes = defaultdict(list)
    for dtype, unit in zip(dtypes, join_units):
        if dtype is None:
            continue

        if is_categorical_dtype(dtype):
            upcast_cls = "category"
        elif is_datetime64tz_dtype(dtype):
            upcast_cls = "datetimetz"
        elif issubclass(dtype.type, np.bool_):
            upcast_cls = "bool"
        elif issubclass(dtype.type, np.object_):
            upcast_cls = "object"
        elif is_datetime64_dtype(dtype):
            upcast_cls = "datetime"
        elif is_timedelta64_dtype(dtype):
            upcast_cls = "timedelta"
        elif is_sparse(dtype):
            upcast_cls = dtype.subtype.name
        elif is_extension_array_dtype(dtype):
            upcast_cls = "object"
        elif is_float_dtype(dtype) or is_numeric_dtype(dtype):
            upcast_cls = dtype.name
        else:
            upcast_cls = "float"

        # Null blocks should not influence upcast class selection, unless there
        # are only null blocks, when same upcasting rules must be applied to
        # null upcast classes.
        if unit.is_na:
            null_upcast_classes[upcast_cls].append(dtype)
        else:
            upcast_classes[upcast_cls].append(dtype)

    if not upcast_classes:
        upcast_classes = null_upcast_classes

    # TODO: de-duplicate with maybe_promote?
    # create the result
    if "object" in upcast_classes:
        return np.dtype(np.object_), np.nan
    elif "bool" in upcast_classes:
        if has_none_blocks:
            return np.dtype(np.object_), np.nan
        else:
            return np.dtype(np.bool_), None
    elif "category" in upcast_classes:
        return np.dtype(np.object_), np.nan
    elif "datetimetz" in upcast_classes:
        # GH-25014. We use NaT instead of iNaT, since this eventually
        # ends up in DatetimeArray.take, which does not allow iNaT.
        dtype = upcast_classes["datetimetz"]
        return dtype[0], tslibs.NaT
    elif "datetime" in upcast_classes:
        return np.dtype("M8[ns]"), tslibs.iNaT
    elif "timedelta" in upcast_classes:
        return np.dtype("m8[ns]"), np.timedelta64("NaT", "ns")
    else:  # pragma
        try:
            g = np.find_common_type(upcast_classes, [])
        except TypeError:
            # At least one is an ExtensionArray
            return np.dtype(np.object_), np.nan
        else:
            if is_float_dtype(g):
                return g, g.type(np.nan)
            elif is_numeric_dtype(g):
                if has_none_blocks:
                    return np.float64, np.nan
                else:
                    return g, None

    msg = "invalid dtype determination in get_concat_dtype"
    raise AssertionError(msg)

def _get_comb_axis(self, i: int) -> Index:
    data_axis = self.objs[0]._get_block_manager_axis(i)
    return get_objs_combined_axis(
        self.objs, axis=data_axis, intersect=self.intersect, sort=self.sort
    )

@Substitution("\ndata : DataFrame")
@Appender(_shared_docs["pivot_table"], indents=1)
def pivot_table(
    data,
    values=None,
    index=None,
    columns=None,
    aggfunc="mean",
    fill_value=None,
    margins=False,
    dropna=True,
    margins_name="All",
    observed=False,
) -> "DataFrame":
    index = _convert_by(index)
    columns = _convert_by(columns)

    if isinstance(aggfunc, list):
        pieces: List[DataFrame] = []
        keys = []
        for func in aggfunc:
            table = pivot_table(
                data,
                values=values,
                index=index,
                columns=columns,
                fill_value=fill_value,
                aggfunc=func,
                margins=margins,
                dropna=dropna,
                margins_name=margins_name,
                observed=observed,
            )
            pieces.append(table)
            keys.append(getattr(func, "__name__", func))

        return concat(pieces, keys=keys, axis=1)

    keys = index + columns

    values_passed = values is not None
    if values_passed:
        if is_list_like(values):
            values_multi = True
            values = list(values)
        else:
            values_multi = False
            values = [values]

        # GH14938 Make sure value labels are in data
        for i in values:
            if i not in data:
                raise KeyError(i)

        to_filter = []
        for x in keys + values:
            if isinstance(x, Grouper):
                x = x.key
            try:
                if x in data:
                    to_filter.append(x)
            except TypeError:
                pass
        if len(to_filter) < len(data.columns):
            data = data[to_filter]

    else:
        values = data.columns
        for key in keys:
            try:
                values = values.drop(key)
            except (TypeError, ValueError, KeyError):
                pass
        values = list(values)

    grouped = data.groupby(keys, observed=observed)
    agged = grouped.agg(aggfunc)
    if dropna and isinstance(agged, ABCDataFrame) and len(agged.columns):
        agged = agged.dropna(how="all")

        # gh-21133
        # we want to down cast if
        # the original values are ints
        # as we grouped with a NaN value
        # and then dropped, coercing to floats
        for v in values:
            if (
                v in data
                and is_integer_dtype(data[v])
                and v in agged
                and not is_integer_dtype(agged[v])
            ):
                agged[v] = maybe_downcast_to_dtype(agged[v], data[v].dtype)

    table = agged
    if table.index.nlevels > 1:
        # Related GH #17123
        # If index_names are integers, determine whether the integers refer
        # to the level position or name.
        index_names = agged.index.names[: len(index)]
        to_unstack = []
        for i in range(len(index), len(keys)):
            name = agged.index.names[i]
            if name is None or name in index_names:
                to_unstack.append(i)
            else:
                to_unstack.append(name)
        table = agged.unstack(to_unstack)

    if not dropna:
        if table.index.nlevels > 1:
            m = MultiIndex.from_arrays(
                cartesian_product(table.index.levels), names=table.index.names
            )
            table = table.reindex(m, axis=0)

        if table.columns.nlevels > 1:
            m = MultiIndex.from_arrays(
                cartesian_product(table.columns.levels), names=table.columns.names
            )
            table = table.reindex(m, axis=1)

    if isinstance(table, ABCDataFrame):
        table = table.sort_index(axis=1)

    if fill_value is not None:
        table = table._ensure_type(table.fillna(fill_value, downcast="infer"))

    if margins:
        if dropna:
            data = data[data.notna().all(axis=1)]
        table = _add_margins(
            table,
            data,
            values,
            rows=index,
            cols=columns,
            aggfunc=aggfunc,
            observed=dropna,
            margins_name=margins_name,
            fill_value=fill_value,
        )

    # discard the top level
    if (
        values_passed
        and not values_multi
        and not table.empty
        and (table.columns.nlevels > 1)
    ):
        table = table[values[0]]

    if len(index) == 0 and len(columns) > 0:
        table = table.T

    # GH 15193 Make sure empty columns are removed if dropna=True
    if isinstance(table, ABCDataFrame) and dropna:
        table = table.dropna(how="all", axis=1)

    return table

@Substitution(klass="TimedeltaIndex")
@Appender(_shared_docs["searchsorted"])
def searchsorted(self, value, side="left", sorter=None):
    if isinstance(value, (np.ndarray, Index)):
        value = np.array(value, dtype=_TD_DTYPE, copy=False)
    else:
        value = Timedelta(value).asm8.view(_TD_DTYPE)

    return self.values.searchsorted(value, side=side, sorter=sorter)

def _get_string_slice(self, key):
    if not self.is_monotonic:
        raise ValueError("Partial indexing only valid for ordered time series")

    key, parsed, reso = parse_time_string(key, self.freq)
    grp = resolution.Resolution.get_freq_group(reso)
    freqn = resolution.get_freq_group(self.freq)
    if reso in ["day", "hour", "minute", "second"] and not grp < freqn:
        raise KeyError(key)

    t1, t2 = self._parsed_string_to_bounds(reso, parsed)
    return slice(
        self.searchsorted(t1.ordinal, side="left"),
        self.searchsorted(t2.ordinal, side="right"),
    )

@Substitution(klass="PeriodIndex")
@Appender(_shared_docs["searchsorted"])
def searchsorted(self, value, side="left", sorter=None):
    if isinstance(value, Period):
        if value.freq != self.freq:
            raise raise_on_incompatible(self, value)
        value = value.ordinal
    elif isinstance(value, str):
        try:
            value = Period(value, freq=self.freq).ordinal
        except DateParseError:
            raise KeyError(f"Cannot interpret '{value}' as period")

    return self._ndarray_values.searchsorted(value, side=side, sorter=sorter)

def _round(self, freq, mode, ambiguous, nonexistent):
    # round the local times
    values = _ensure_datetimelike_to_i8(self)
    result = round_nsint64(values, mode, freq)
    result = self._maybe_mask_results(result, fill_value=NaT)

    dtype = self.dtype
    if is_datetime64tz_dtype(self):
        dtype = None
    return self._ensure_localized(
        self._simple_new(result, dtype=dtype), ambiguous, nonexistent
    )

@Appender(_index_shared_docs["where"] % _index_doc_kwargs)
def where(self, cond, other=None):
    other = _ensure_datetimelike_to_i8(other, to_utc=True)
    values = _ensure_datetimelike_to_i8(self, to_utc=True)
    result = np.where(cond, values, other).astype("i8")

    result = self._ensure_localized(result, from_utc=True)
    return self._shallow_copy(result)

@Appender(_index_shared_docs["repeat"] % _index_doc_kwargs)
def repeat(self, repeats, axis=None):
    nv.validate_repeat(tuple(), dict(axis=axis))
    freq = self.freq if is_period_dtype(self) else None
    return self._shallow_copy(self.asi8.repeat(repeats), freq=freq)

@Appender(_index_shared_docs["take"] % _index_doc_kwargs)
def take(self, indices, axis=0, allow_fill=True, fill_value=None, **kwargs):
    nv.validate_take(tuple(), kwargs)
    indices = ensure_int64(indices)

    maybe_slice = lib.maybe_indices_to_slice(indices, len(self))
    if isinstance(maybe_slice, slice):
        return self[maybe_slice]

    taken = ExtensionIndex.take(
        self, indices, axis, allow_fill, fill_value, **kwargs
    )

    # keep freq in PeriodArray/Index, reset otherwise
    freq = self.freq if is_period_dtype(self) else None
    assert taken.freq == freq, (taken.freq, freq, taken)
    return self._shallow_copy(taken, freq=freq)

@unpack_zerodim_and_defer(opname)
def wrapper(self, other):
    ordinal_op = getattr(self.asi8, opname)

    if isinstance(other, str):
        try:
            other = self._scalar_from_string(other)
        except ValueError:
            # string that can't be parsed as Period
            return invalid_comparison(self, other, op)
    elif isinstance(other, int):
        # TODO: sure we want to allow this?  we dont for DTA/TDA
        #  2 tests rely on this
        other = Period(other, freq=self.freq)
        result = ordinal_op(other.ordinal)

    if isinstance(other, self._recognized_scalars) or other is NaT:
        other = self._scalar_type(other)
        self._check_compatible_with(other)

        other_i8 = self._unbox_scalar(other)

        result = op(self.view("i8"), other_i8)
        if isna(other):
            result.fill(nat_result)

    elif not is_list_like(other):
        return invalid_comparison(self, other, op)

    elif len(other) != len(self):
        raise ValueError("Lengths must match")

    else:
        if isinstance(other, list):
            # TODO: could use pd.Index to do inference?
            other = np.array(other)

        if not isinstance(other, (np.ndarray, cls)):
            return invalid_comparison(self, other, op)

        if is_object_dtype(other):
            with np.errstate(all="ignore"):
                result = ops.comp_method_OBJECT_ARRAY(
                    op, self.astype(object), other
                )
            o_mask = isna(other)

        elif not cls._is_recognized_dtype(other.dtype):
            # e.g. is_timedelta64_dtype(other)
            return invalid_comparison(self, other, op)

        else:
            assert isinstance(other, cls), type(other)

            self._check_compatible_with(other)

            result = op(self.view("i8"), other.view("i8"))
            o_mask = other._isnan

        if o_mask.any():
            result[o_mask] = nat_result

    if self._hasnans:
        result[self._isnan] = nat_result

    return result

@apply_wraps
def apply(self, other):
    if isinstance(other, datetime):
        # used for detecting edge condition
        nanosecond = getattr(other, "nanosecond", 0)
        # reset timezone and nanosecond
        # other may be a Timestamp, thus not use replace
        other = datetime(
            other.year,
            other.month,
            other.day,
            other.hour,
            other.minute,
            other.second,
            other.microsecond,
        )
        n = self.n

        # adjust other to reduce number of cases to handle
        if n >= 0:
            if other.time() in self.end or not self._is_on_offset(other):
                other = self._next_opening_time(other)
        else:
            if other.time() in self.start:
                # adjustment to move to previous business day
                other = other - timedelta(seconds=1)
            if not self._is_on_offset(other):
                other = self._next_opening_time(other)
                other = self._get_closing_time(other)

        # get total business hours by sec in one business day
        businesshours = sum(
            self._get_business_hours_by_sec(st, en)
            for st, en in zip(self.start, self.end)
        )

        bd, r = divmod(abs(n * 60), businesshours // 60)
        if n < 0:
            bd, r = -bd, -r

        # adjust by business days first
        if bd != 0:
            skip_bd = BusinessDay(n=bd)
            # midnight business hour may not on BusinessDay
            if not self.next_bday.is_on_offset(other):
                prev_open = self._prev_opening_time(other)
                remain = other - prev_open
                other = prev_open + skip_bd + remain
            else:
                other = other + skip_bd

        # remaining business hours to adjust
        bhour_remain = timedelta(minutes=r)

        if n >= 0:
            while bhour_remain != timedelta(0):
                # business hour left in this business time interval
                bhour = (
                    self._get_closing_time(self._prev_opening_time(other)) - other
                )
                if bhour_remain < bhour:
                    # finish adjusting if possible
                    other += bhour_remain
                    bhour_remain = timedelta(0)
                else:
                    # go to next business time interval
                    bhour_remain -= bhour
                    other = self._next_opening_time(other + bhour)
        else:
            while bhour_remain != timedelta(0):
                # business hour left in this business time interval
                bhour = self._next_opening_time(other) - other
                if (
                    bhour_remain > bhour
                    or bhour_remain == bhour
                    and nanosecond != 0
                ):
                    # finish adjusting if possible
                    other += bhour_remain
                    bhour_remain = timedelta(0)
                else:
                    # go to next business time interval
                    bhour_remain -= bhour
                    other = self._get_closing_time(
                        self._next_opening_time(
                            other + bhour - timedelta(seconds=1)
                        )
                    )

        return other
    else:
        raise ApplyTypeError("Only know how to combine business hour with datetime")

def _fast_union(self, other):
    if len(other) == 0:
        return self.view(type(self))

    if len(self) == 0:
        return other.view(type(self))

    # to make our life easier, "sort" the two ranges
    if self[0] <= other[0]:
        left, right = self, other
    else:
        left, right = other, self

    left_end = left[-1]
    right_end = right[-1]

    # concatenate
    if left_end < right_end:
        loc = right.searchsorted(left_end, side="right")
        right_chunk = right.values[loc:]
        dates = concat_compat((left.values, right_chunk))
        return self._shallow_copy(dates)
    else:
        return left

def _union(self, other: "TimedeltaIndex", sort):
    if len(other) == 0 or self.equals(other) or len(self) == 0:
        return super()._union(other, sort=sort)

    # We are called by `union`, which is responsible for this validation
    assert isinstance(other, TimedeltaIndex)

    this, other = self, other

    if this._can_fast_union(other):
        return this._fast_union(other)
    else:
        result = Index._union(this, other, sort=sort)
        if isinstance(result, TimedeltaIndex):
            if result.freq is None:
                result._set_freq("infer")
        return result

def __new__(
    cls, data=None, dtype=None, copy=False, name=None, tupleize_cols=True, **kwargs,
) -> "Index":

    from .range import RangeIndex
    from pandas import PeriodIndex, DatetimeIndex, TimedeltaIndex
    from .numeric import Float64Index, Int64Index, UInt64Index
    from .interval import IntervalIndex
    from .category import CategoricalIndex

    name = maybe_extract_name(name, data, cls)

    if isinstance(data, ABCPandasArray):
        # ensure users don't accidentally put a PandasArray in an index.
        data = data.to_numpy()

    # range
    if isinstance(data, RangeIndex):
        return RangeIndex(start=data, copy=copy, dtype=dtype, name=name)
    elif isinstance(data, range):
        return RangeIndex.from_range(data, dtype=dtype, name=name)

    # categorical
    elif is_categorical_dtype(data) or is_categorical_dtype(dtype):
        return CategoricalIndex(data, dtype=dtype, copy=copy, name=name, **kwargs)

    # interval
    elif (
        is_interval_dtype(data) or is_interval_dtype(dtype)
    ) and not is_object_dtype(dtype):
        closed = kwargs.get("closed", None)
        return IntervalIndex(data, dtype=dtype, name=name, copy=copy, closed=closed)

    elif (
        is_datetime64_any_dtype(data)
        or is_datetime64_any_dtype(dtype)
        or "tz" in kwargs
    ):
        if is_dtype_equal(_o_dtype, dtype):
            # GH#23524 passing `dtype=object` to DatetimeIndex is invalid,
            #  will raise in the where `data` is already tz-aware.  So
            #  we leave it out of this step and cast to object-dtype after
            #  the DatetimeIndex construction.
            # Note we can pass copy=False because the .astype below
            #  will always make a copy
            return DatetimeIndex(data, copy=False, name=name, **kwargs).astype(
                object
            )
        else:
            return DatetimeIndex(data, copy=copy, name=name, dtype=dtype, **kwargs)

    elif is_timedelta64_dtype(data) or is_timedelta64_dtype(dtype):
        if is_dtype_equal(_o_dtype, dtype):
            # Note we can pass copy=False because the .astype below
            #  will always make a copy
            return TimedeltaIndex(data, copy=False, name=name, **kwargs).astype(
                object
            )
        else:
            return TimedeltaIndex(data, copy=copy, name=name, dtype=dtype, **kwargs)

    elif is_period_dtype(data) and not is_object_dtype(dtype):
        return PeriodIndex(data, copy=copy, name=name, **kwargs)

    # extension dtype
    elif is_extension_array_dtype(data) or is_extension_array_dtype(dtype):
        if not (dtype is None or is_object_dtype(dtype)):
            # coerce to the provided dtype
            ea_cls = dtype.construct_array_type()
            data = ea_cls._from_sequence(data, dtype=dtype, copy=False)
        else:
            data = np.asarray(data, dtype=object)

        # coerce to the object dtype
        data = data.astype(object)
        return Index(data, dtype=object, copy=copy, name=name, **kwargs)

    # index-like
    elif isinstance(data, (np.ndarray, Index, ABCSeries)):
        if dtype is not None:
            # we need to avoid having numpy coerce
            # things that look like ints/floats to ints unless
            # they are actually ints, e.g. '0' and 0.0
            # should not be coerced
            # GH 11836
            data = _maybe_cast_with_dtype(data, dtype, copy)
            dtype = data.dtype  # TODO: maybe not for object?

        # maybe coerce to a sub-class
        if is_signed_integer_dtype(data.dtype):
            return Int64Index(data, copy=copy, dtype=dtype, name=name)
        elif is_unsigned_integer_dtype(data.dtype):
            return UInt64Index(data, copy=copy, dtype=dtype, name=name)
        elif is_float_dtype(data.dtype):
            return Float64Index(data, copy=copy, dtype=dtype, name=name)
        elif issubclass(data.dtype.type, np.bool) or is_bool_dtype(data):
            subarr = data.astype("object")
        else:
            subarr = com.asarray_tuplesafe(data, dtype=object)

        # asarray_tuplesafe does not always copy underlying data,
        # so need to make sure that this happens
        if copy:
            subarr = subarr.copy()

        if dtype is None:
            new_data, new_dtype = _maybe_cast_data_without_dtype(subarr)
            if new_dtype is not None:
                return cls(
                    new_data, dtype=new_dtype, copy=False, name=name, **kwargs
                )

        if kwargs:
            raise TypeError(f"Unexpected keyword arguments {repr(set(kwargs))}")
        return cls._simple_new(subarr, name, **kwargs)

    elif hasattr(data, "__array__"):
        return Index(np.asarray(data), dtype=dtype, copy=copy, name=name, **kwargs)
    elif data is None or is_scalar(data):
        raise cls._scalar_data_error(data)
    else:
        if tupleize_cols and is_list_like(data):
            # GH21470: convert iterable to list before determining if empty
            if is_iterator(data):
                data = list(data)

            if data and all(isinstance(e, tuple) for e in data):
                # we must be all tuples, otherwise don't construct
                # 10697
                from .multi import MultiIndex

                return MultiIndex.from_tuples(
                    data, names=name or kwargs.get("names")
                )
        # other iterable of some kind
        subarr = com.asarray_tuplesafe(data, dtype=object)
        return Index(subarr, dtype=dtype, copy=copy, name=name, **kwargs)

def _convert_listlike_datetimes(
    arg,
    format,
    name=None,
    tz=None,
    unit=None,
    errors=None,
    infer_datetime_format=None,
    dayfirst=None,
    yearfirst=None,
    exact=None,
):
    """
    Helper function for to_datetime. Performs the conversions of 1D listlike
    of dates

    Parameters
    ----------
    arg : list, tuple, ndarray, Series, Index
        date to be parced
    name : object
        None or string for the Index name
    tz : object
        None or 'utc'
    unit : string
        None or string of the frequency of the passed data
    errors : string
        error handing behaviors from to_datetime, 'raise', 'coerce', 'ignore'
    infer_datetime_format : boolean
        inferring format behavior from to_datetime
    dayfirst : boolean
        dayfirst parsing behavior from to_datetime
    yearfirst : boolean
        yearfirst parsing behavior from to_datetime
    exact : boolean
        exact format matching behavior from to_datetime

    Returns
    -------
    Index-like of parsed dates
    """
    from pandas import DatetimeIndex
    from pandas.core.arrays import DatetimeArray
    from pandas.core.arrays.datetimes import (
        maybe_convert_dtype,
        objects_to_datetime64ns,
    )

    if isinstance(arg, (list, tuple)):
        arg = np.array(arg, dtype="O")

    # these are shortcutable
    if is_datetime64tz_dtype(arg):
        if not isinstance(arg, (DatetimeArray, DatetimeIndex)):
            return DatetimeIndex(arg, tz=tz, name=name)
        if tz == "utc":
            arg = arg.tz_convert(None).tz_localize(tz)
        return arg

    elif is_datetime64_ns_dtype(arg):
        if not isinstance(arg, (DatetimeArray, DatetimeIndex)):
            try:
                return DatetimeIndex(arg, tz=tz, name=name)
            except ValueError:
                pass
        elif tz:
            # DatetimeArray, DatetimeIndex
            return arg.tz_localize(tz)

        return arg

    elif unit is not None:
        if format is not None:
            raise ValueError("cannot specify both format and unit")
        arg = getattr(arg, "values", arg)
        result, tz_parsed = tslib.array_with_unit_to_datetime(arg, unit, errors=errors)
        if errors == "ignore":
            from pandas import Index

            result = Index(result, name=name)
        else:
            result = DatetimeIndex(result, name=name)
        # GH 23758: We may still need to localize the result with tz
        # GH 25546: Apply tz_parsed first (from arg), then tz (from caller)
        # result will be naive but in UTC
        try:
            result = result.tz_localize("UTC").tz_convert(tz_parsed)
        except AttributeError:
            # Regular Index from 'ignore' path
            return result
        if tz is not None:
            if result.tz is None:
                result = result.tz_localize(tz)
            else:
                result = result.tz_convert(tz)
        return result
    elif getattr(arg, "ndim", 1) > 1:
        raise TypeError(
            "arg must be a string, datetime, list, tuple, 1-d array, or Series"
        )

    # warn if passing timedelta64, raise for PeriodDtype
    # NB: this must come after unit transformation
    orig_arg = arg
    arg, _ = maybe_convert_dtype(arg, copy=False)

    arg = ensure_object(arg)
    require_iso8601 = False

    if infer_datetime_format and format is None:
        format = _guess_datetime_format_for_array(arg, dayfirst=dayfirst)

    if format is not None:
        # There is a special fast-path for iso8601 formatted
        # datetime strings, so in those cases don't use the inferred
        # format because this path makes process slower in this
        # special case
        format_is_iso8601 = _format_is_iso(format)
        if format_is_iso8601:
            require_iso8601 = not infer_datetime_format
            format = None

    tz_parsed = None
    result = None

    if format is not None:
        try:
            # shortcut formatting here
            if format == "%Y%m%d":
                try:
                    # pass orig_arg as float-dtype may have been converted to
                    # datetime64[ns]
                    orig_arg = ensure_object(orig_arg)
                    result = _attempt_YYYYMMDD(orig_arg, errors=errors)
                except (ValueError, TypeError, tslibs.OutOfBoundsDatetime):
                    raise ValueError("cannot convert the input to '%Y%m%d' date format")

            # fallback
            if result is None:
                try:
                    result, timezones = array_strptime(
                        arg, format, exact=exact, errors=errors
                    )
                    if "%Z" in format or "%z" in format:
                        return _return_parsed_timezone_results(
                            result, timezones, tz, name
                        )
                except tslibs.OutOfBoundsDatetime:
                    if errors == "raise":
                        raise
                    elif errors == "coerce":
                        result = np.empty(arg.shape, dtype="M8[ns]")
                        iresult = result.view("i8")
                        iresult.fill(tslibs.iNaT)
                    else:
                        result = arg
                except ValueError:
                    # if format was inferred, try falling back
                    # to array_to_datetime - terminate here
                    # for specified formats
                    if not infer_datetime_format:
                        if errors == "raise":
                            raise
                        elif errors == "coerce":
                            result = np.empty(arg.shape, dtype="M8[ns]")
                            iresult = result.view("i8")
                            iresult.fill(tslibs.iNaT)
                        else:
                            result = arg
        except ValueError as e:
            # Fallback to try to convert datetime objects if timezone-aware
            #  datetime objects are found without passing `utc=True`
            try:
                values, tz = conversion.datetime_to_datetime64(arg)
                return DatetimeIndex._simple_new(values, name=name, tz=tz)
            except (ValueError, TypeError):
                raise e

    if result is None:
        assert format is None or infer_datetime_format
        utc = tz == "utc"
        result, tz_parsed = objects_to_datetime64ns(
            arg,
            dayfirst=dayfirst,
            yearfirst=yearfirst,
            utc=utc,
            errors=errors,
            require_iso8601=require_iso8601,
            allow_object=True,
        )

    if tz_parsed is not None:
        # We can take a shortcut since the datetime64 numpy array
        # is in UTC
        return DatetimeIndex._simple_new(result, name=name, tz=tz_parsed)

    utc = tz == "utc"
    return _box_as_indexlike(result, utc=utc, name=name)

def __contains__(self, key) -> bool:
    """
    Returns True if `key` is in this Categorical.
    """
    # if key is a NaN, check if any NaN is in self.
    if is_scalar(key) and isna(key):
        return self.isna().any()

    return contains(self, key, container=self._codes)

@doc(Index.__contains__)
def __contains__(self, key: Any) -> bool:
    # if key is a NaN, check if any NaN is in self.
    if is_scalar(key) and isna(key):
        return self.hasnans

    hash(key)
    return contains(self, key, container=self._engine)

def is_gzipped(response):
    """Return True if the response is gzipped, or False otherwise"""
    ctype = response.headers.get('Content-Type', b'')
    return ctype in (b'application/x-gzip', b'application/gzip')

def _unquotepath(path):
    for reserved in ('2f', '2F', '3f', '3F'):
        path = path.replace('%' + reserved, '%25' + reserved.upper())
    return unquote(path)

def parse_url(url, encoding=None):
    """Return urlparsed url from the given argument (which could be an already
    parsed url)
    """
    if isinstance(url, ParseResult):
        return url
    return urlparse(to_native_str(url, encoding))

def from_content_disposition(self, content_disposition):
    try:
        filename = to_native_str(content_disposition).split(';')[1].split('=')[1]
        filename = filename.strip('"\'')
        return self.from_filename(filename)
    except IndexError:
        return Response

def get_host_regex(self, spider):
    """Override this method to implement a different offsite policy"""
    allowed_domains = getattr(spider, 'allowed_domains', None)
    if not allowed_domains:
        return re.compile('')  # allow all by default
    url_pattern = re.compile("^https?://.*$")
    for domain in allowed_domains:
        if url_pattern.match(domain):
            message = ("allowed_domains accepts only domains, not URLs. "
                       "Ignoring URL entry %s in allowed_domains." % domain)
            warnings.warn(message, URLWarning)
    domains = [re.escape(d) for d in allowed_domains if d is not None]
    regex = r'^(.*\.)?(%s)$' % '|'.join(domains)
    return re.compile(regex)

def _parse_sitemap(self, response):
    if response.url.endswith('/robots.txt'):
        for url in sitemap_urls_from_robots(response.body):
            yield Request(url, callback=self._parse_sitemap)
    else:
        body = self._get_sitemap_body(response)
        if body is None:
            logger.warning("Ignoring invalid sitemap: %(response)s",
                           {'response': response}, extra={'spider': self})
            return

        s = Sitemap(body)
        if s.type == 'sitemapindex':
            for loc in iterloc(s, self.sitemap_alternate_links):
                if any(x.search(loc) for x in self._follow):
                    yield Request(loc, callback=self._parse_sitemap)
        elif s.type == 'urlset':
            for loc in iterloc(s):
                for r, c in self._cbs:
                    if r.search(loc):
                        yield Request(loc, callback=c)
                        break

def _export_xml_field(self, name, serialized_value):
    self.xg.startElement(name, {})
    if hasattr(serialized_value, 'items'):
        for subname, value in serialized_value.items():
            self._export_xml_field(subname, value)
    elif is_listlike(serialized_value):
        for value in serialized_value:
            self._export_xml_field('value', value)
    else:
        self._xg_characters(serialized_value)
    self.xg.endElement(name)

def _get_proxy(self, url, orig_type):
    proxy_type, user, password, hostport = _parse_proxy(url)
    proxy_url = urlunparse((proxy_type or orig_type, hostport, '', '', '', ''))

    if user:
        user_pass = '%s:%s' % (unquote(user), unquote(password))
        creds = base64.b64encode(user_pass).strip()
    else:
        creds = None

    return creds, proxy_url

def _set_proxy(self, request, scheme):
    creds, proxy = self.proxies[scheme]
    request.meta['proxy'] = proxy
    if creds:
        request.headers['Proxy-Authorization'] = 'Basic ' + creds

def _get_form(response, formname, formid, formnumber, formxpath):
    """Find the form element """
    text = response.body_as_unicode()
    root = create_root_node(text, lxml.html.HTMLParser, base_url=response.url)
    forms = root.xpath('//form')
    if not forms:
        raise ValueError("No <form> element found in %s" % response)

    if formname is not None:
        f = root.xpath('//form[@name="%s"]' % formname)
        if f:
            return f[0]

    if formid is not None:
        f = root.xpath('//form[@id="%s"]' % formid)
        if f:
            return f[0]

    # Get form element from xpath, if not found, go up
    if formxpath is not None:
        nodes = root.xpath(formxpath)
        if nodes:
            el = nodes[0]
            while True:
                if el.tag == 'form':
                    return el
                el = el.getparent()
                if el is None:
                    break
        raise ValueError('No <form> element found with %s' % formxpath)

    # If we get here, it means that either formname was None
    # or invalid
    if formnumber is not None:
        try:
            form = forms[formnumber]
        except IndexError:
            raise IndexError("Form number %d not found in %s" %
                             (formnumber, response))
        else:
            return form

def _get_form_url(form, url):
    if url is None:
        return form.action or form.base_url
    return urljoin(form.base_url, url)

def process_response(self, request, response, spider):
    if (request.meta.get('dont_redirect', False) or
           response.status in getattr(spider, 'handle_httpstatus_list', [])):
        return response

    if request.method == 'HEAD':
        if response.status in [301, 302, 303, 307] and 'Location' in response.headers:
            redirected_url = urljoin(request.url, response.headers['location'])
            redirected = request.replace(url=redirected_url)
            return self._redirect(redirected, request, spider, response.status)
        else:
            return response

    if response.status in [302, 303] and 'Location' in response.headers:
        redirected_url = urljoin(request.url, response.headers['location'])
        redirected = self._redirect_request_using_get(request, redirected_url)
        return self._redirect(redirected, request, spider, response.status)

    if response.status in [301, 307] and 'Location' in response.headers:
        redirected_url = urljoin(request.url, response.headers['location'])
        redirected = request.replace(url=redirected_url)
        return self._redirect(redirected, request, spider, response.status)

    return response

def __setitem__(self, key, value):
    while len(self) >= self.limit:
        self.popitem(last=False)
    super(LocalCache, self).__setitem__(key, value)

def _iter_command_classes(module_name):
    # TODO: add `name` attribute to commands and and merge this function with
    # scrapy.utils.spider.iter_spider_classes
    for module in walk_modules(module_name):
        for obj in vars(module).itervalues():
            if inspect.isclass(obj) and \
               issubclass(obj, ScrapyCommand) and \
               obj.__module__ == module.__name__:
                yield obj

def header_items(self):
    return [
        (to_native_str(k), [to_native_str(x) for x in v])
        for k, v in self.request.headers.items()
    ]

def _itemproc_finished(self, output, item, response, spider):
    """ItemProcessor finished for the given ``item`` and returned ``output``
    """
    self.slot.itemproc_size -= 1
    if isinstance(output, Failure):
        ex = output.value
        if isinstance(ex, DropItem):
            logkws = self.logformatter.dropped(item, ex, response, spider)
            logger.log(*logformatter_adapter(logkws), extra={'spider': spider})
            return self.signals.send_catch_log_deferred(
                signal=signals.item_dropped, item=item, response=response,
                spider=spider, exception=output.value)
        else:
            logger.error('Error processing %(item)s', {'item': item},
                         extra={'spider': spider, 'failure': output})
    else:
        logkws = self.logformatter.scraped(output, response, spider)
        logger.log(*logformatter_adapter(logkws), extra={'spider': spider})
        return self.signals.send_catch_log_deferred(
            signal=signals.item_scraped, item=output, response=response,
            spider=spider)

def handle_spider_error(self, _failure, request, response, spider):
    exc = _failure.value
    if isinstance(exc, CloseSpider):
        self.crawler.engine.close_spider(spider, exc.reason or 'cancelled')
        return
    referer = request.headers.get('Referer')
    logger.error(
        "Spider error processing %(request)s (referer: %(referer)s)",
        {'request': request, 'referer': referer},
        extra={'spider': spider, 'failure': _failure}
    )
    self.signals.send_catch_log(
        signal=signals.spider_error,
        failure=_failure, response=response,
        spider=spider
    )
    self.crawler.stats.inc_value(
        "spider_exceptions/%s" % _failure.value.__class__.__name__,
        spider=spider
    )

def _logerror(self, failure, request, spider):
    if failure.type is not IgnoreRequest:
        logger.error("Error downloading %(request)s: %(f_exception)s",
                     {'request': request, 'f_exception': failure.value},
                     extra={'spider': spider, 'failure': failure})

def item_completed(self, results, item, info):
    """Called per item when all media requests has been processed"""
    if self.LOG_FAILED_RESULTS:
        for ok, value in results:
            if not ok:
                logger.error(
                    '%(class)s found errors processing %(item)s',
                    {'class': self.__class__.__name__, 'item': item},
                    extra={'spider': info.spider, 'failure': value}
                )
    return item

def logerror(failure, recv):
    if dont_log is None or not isinstance(failure.value, dont_log):
        logger.error("Error caught on signal handler: %(receiver)s",
                     {'receiver': recv},
                     extra={'spider': spider, 'failure': failure})
    return failure

def __new__(mcs, class_name, bases, attrs):
    new_bases = tuple(base._class for base in bases if hasattr(base, '_class'))
    _class = super(ItemMeta, mcs).__new__(mcs, 'x_' + class_name, new_bases, attrs)

    fields = {}
    new_attrs = {}
    for n in dir(_class):
        v = getattr(_class, n)
        if isinstance(v, Field):
            fields[n] = v
        elif n in attrs:
            new_attrs[n] = attrs[n]

    new_attrs['fields'] = fields
    new_attrs['_class'] = _class
    return super(ItemMeta, mcs).__new__(mcs, class_name, bases, new_attrs)

def _get_spider_loader(settings):
    """ Get SpiderLoader instance from settings """
    if settings.get('SPIDER_MANAGER_CLASS'):
        warnings.warn(
            'SPIDER_MANAGER_CLASS option is deprecated. '
            'Please use SPIDER_LOADER_CLASS.',
            category=ScrapyDeprecationWarning, stacklevel=2
        )
    cls_path = settings.get('SPIDER_LOADER_CLASS',
                            settings.get('SPIDER_MANAGER_CLASS'))
    loader_cls = load_object(cls_path)
    verifyClass(ISpiderLoader, loader_cls)
    return loader_cls.from_settings(settings.frozencopy())

def create_instance(objcls, settings, crawler, *args, **kwargs):
    """Construct a class instance using its ``from_crawler`` or
    ``from_settings`` constructors, if available.

    At least one of ``settings`` and ``crawler`` needs to be different from
    ``None``. If ``settings `` is ``None``, ``crawler.settings`` will be used.
    If ``crawler`` is ``None``, only the ``from_settings`` constructor will be
    tried.

    ``*args`` and ``**kwargs`` are forwarded to the constructors.

    Raises ``ValueError`` if both ``settings`` and ``crawler`` are ``None``.
    """
    if settings is None:
        if crawler is None:
            raise ValueError("Specify at least one of settings and crawler.")
        settings = crawler.settings
    if crawler and hasattr(objcls, 'from_crawler'):
        return objcls.from_crawler(crawler, *args, **kwargs)
    elif hasattr(objcls, 'from_settings'):
        return objcls.from_settings(settings, *args, **kwargs)
    else:
        return objcls(*args, **kwargs)

def _set_url(self, url):
    if not isinstance(url, six.string_types):
        raise TypeError('Request url must be str or unicode, got %s:' % type(url).__name__)

    s = safe_url_string(url, self.encoding)
    self._url = escape_ajax(s)

    if ':' not in self._url:
        raise ValueError('Missing scheme in request url: %s' % self._url)

def _get_clickable(clickdata, form):
    """
    Returns the clickable element specified in clickdata,
    if the latter is given. If not, it returns the first
    clickable element found
    """
    clickables = [
        el for el in form.xpath(
            'descendant::*[(self::input or self::button)'
            ' and re:test(@type, "^submit$", "i")]'
            '|descendant::button[not(@type)]',
            namespaces={"re": "http://exslt.org/regular-expressions"})
        ]
    if not clickables:
        return

    # If we don't have clickdata, we just use the first clickable element
    if clickdata is None:
        el = clickables[0]
        return (el.get('name'), el.get('value') or '')

    # If clickdata is given, we compare it to the clickable elements to find a
    # match. We first look to see if the number is specified in clickdata,
    # because that uniquely identifies the element
    nr = clickdata.get('nr', None)
    if nr is not None:
        try:
            el = list(form.inputs)[nr]
        except IndexError:
            pass
        else:
            return (el.get('name'), el.get('value') or '')

    # We didn't find it, so now we build an XPath expression out of the other
    # arguments, because they can be used as such
    xpath = u'.//*' + \
            u''.join(u'[@%s="%s"]' % c for c in six.iteritems(clickdata))
    el = form.xpath(xpath)
    if len(el) == 1:
        return (el[0].get('name'), el[0].get('value') or '')
    elif len(el) > 1:
        raise ValueError("Multiple elements found (%r) matching the criteria "
                         "in clickdata: %r" % (el, clickdata))
    else:
        raise ValueError('No clickable element matching clickdata: %r' % (clickdata,))

def start_requests(self):
    if self.make_requests_from_url is not Spider.make_requests_from_url:
        warnings.warn(
            "Spider.make_requests_from_url method is deprecated; "
            "it won't be called in future Scrapy releases. "
            "Please override start_requests method instead."
        )
        for url in self.start_urls:
            yield self.make_requests_from_url(url)
    else:
        for url in self.start_urls:
            yield Request(url, dont_filter=True)

def process_response(self, request, response, spider):
    if (request.meta.get('dont_redirect', False) or
            response.status in getattr(spider, 'handle_httpstatus_list', []) or
            response.status in request.meta.get('handle_httpstatus_list', []) or
            request.meta.get('handle_httpstatus_all', False)):
        return response

    allowed_status = (301, 302, 303, 307, 308)
    if 'Location' not in response.headers or response.status not in allowed_status:
        return response

    location = safe_url_string(response.headers['location'])

    redirected_url = urljoin(request.url, location)

    if response.status in (301, 307, 308) or request.method == 'HEAD':
        redirected = request.replace(url=redirected_url)
        return self._redirect(redirected, request, spider, response.status)

    redirected = self._redirect_request_using_get(request, redirected_url)
    return self._redirect(redirected, request, spider, response.status)

def _serialize_value(self, value):
    if isinstance(value, BaseItem):
        return self.export_item(value)
    if isinstance(value, dict):
        return dict(self._serialize_dict(value))
    if is_listlike(value):
        return [self._serialize_value(v) for v in value]
    if self.binary:
        return to_bytes(value, encoding=self.encoding)
    else:
        return to_unicode(value, encoding=self.encoding)

def _get_form_url(form, url):
    if url is None:
        return urljoin(form.base_url, form.action)
    return urljoin(form.base_url, url)

