@utils.mutating
def delete(self, req, image_id):
    self._enforce(req, 'delete_image')
    image = self._get_image(req.context, image_id)

    if image['protected']:
        msg = _("Unable to delete as image %(image_id)s is protected"
                % locals())
        raise webob.exc.HTTPForbidden(explanation=msg)

    status = 'deleted'
    if image['location']:
        if CONF.delayed_delete:
            status = 'pending_delete'
            self.store_api.schedule_delayed_delete_from_backend(
                            image['location'], id)
        else:
            self.store_api.safe_delete_from_backend(image['location'],
                                                    req.context, id)

    try:
        self.db_api.image_update(req.context, image_id, {'status': status})
        self.db_api.image_destroy(req.context, image_id)
    except (exception.NotFound, exception.Forbidden):
        msg = ("Failed to find image %(image_id)s to delete" % locals())
        LOG.info(msg)
        raise webob.exc.HTTPNotFound()
    else:
        self.notifier.info('image.delete', image)

def delete(self, location, connection=None):
    location = location.store_location
    if not connection:
        connection = self.get_connection(location)

    try:
        # We request the manifest for the object. If one exists,
        # that means the object was uploaded in chunks/segments,
        # and we need to delete all the chunks as well as the
        # manifest.
        manifest = None
        try:
            headers = connection.head_object(
                    location.container, location.obj)
            manifest = headers.get('x-object-manifest')
        except swiftclient.ClientException, e:
            if e.http_status != httplib.NOT_FOUND:
                raise
        if manifest:
            # Delete all the chunks before the object manifest itself
            obj_container, obj_prefix = manifest.split('/', 1)
            segments = connection.get_container(
                    obj_container, prefix=obj_prefix)[1]
            for segment in segments:
                # TODO(jaypipes): This would be an easy area to parallelize
                # since we're simply sending off parallelizable requests
                # to Swift to delete stuff. It's not like we're going to
                # be hogging up network or file I/O here...
                connection.delete_object(
                        obj_container, segment['name'])

        else:
            connection.delete_object(location.container, location.obj)

    except swiftclient.ClientException, e:
        if e.http_status == httplib.NOT_FOUND:
            uri = location.get_uri()
            raise exception.NotFound(_("Swift could not find image at "
                                       "uri %(uri)s") % locals())
        else:
            raise

