def parse_Compare(self):
    left = Expr.parse_value_expr(self.expr.left, self.context)
    right = Expr.parse_value_expr(self.expr.right, self.context)

    if right.value is None:
        return

    if isinstance(self.expr.op, (vy_ast.In, vy_ast.NotIn)):
        if isinstance(right.typ, ArrayLike):
            return self.build_in_comparator()
        return  # pragma: notest

    if isinstance(self.expr.op, vy_ast.Gt):
        op = "sgt"
    elif isinstance(self.expr.op, vy_ast.GtE):
        op = "sge"
    elif isinstance(self.expr.op, vy_ast.LtE):
        op = "sle"
    elif isinstance(self.expr.op, vy_ast.Lt):
        op = "slt"
    elif isinstance(self.expr.op, vy_ast.Eq):
        op = "eq"
    elif isinstance(self.expr.op, vy_ast.NotEq):
        op = "ne"
    else:
        return  # pragma: notest

    # Compare (limited to 32) byte arrays.
    if isinstance(left.typ, ByteArrayLike) and isinstance(right.typ, ByteArrayLike):
        left = Expr(self.expr.left, self.context).ir_node
        right = Expr(self.expr.right, self.context).ir_node

        length_mismatch = left.typ.maxlen != right.typ.maxlen
        left_over_32 = left.typ.maxlen > 32
        right_over_32 = right.typ.maxlen > 32

        if length_mismatch or left_over_32 or right_over_32:
            left_keccak = keccak256_helper(self.expr, left, self.context)
            right_keccak = keccak256_helper(self.expr, right, self.context)

            if op == "eq" or op == "ne":
                return IRnode.from_list([op, left_keccak, right_keccak], typ="bool")

            else:
                return

        else:

            def load_bytearray(side):
                return LOAD(bytes_data_ptr(side))

            return IRnode.from_list(
                # CMC 2022-03-24 TODO investigate this.
                [op, load_bytearray(left), load_bytearray(right)],
                typ="bool",
            )

    # Compare other types.
    elif is_numeric_type(left.typ) and is_numeric_type(right.typ):
        if left.typ.typ == right.typ.typ == "uint256":
            # this works because we only have one unsigned integer type
            # in the future if others are added, this logic must be expanded
            op = self._signed_to_unsigned_comparision_op(op)

    elif isinstance(left.typ, BaseType) and isinstance(right.typ, BaseType):
        if op not in ("eq", "ne"):
            return
    else:
        # kludge to block behavior in #2638
        # TODO actually implement equality for complex types
        raise TypeMismatch(
            f"operation not yet supported for {left.typ}, {right.typ}, see issue #2638",
            self.expr.op,
        )

    return IRnode.from_list([op, left, right], typ="bool")

def keccak256_helper(expr, ir_arg, context):
    sub = ir_arg  # TODO get rid of useless variable
    _check_byteslike(sub.typ, expr)

    # Can hash literals
    # TODO this is dead code.
    if isinstance(sub, bytes):
        return IRnode.from_list(bytes_to_int(keccak256(sub)), typ=BaseType("bytes32"))

    # Can hash bytes32 objects
    if is_base_type(sub.typ, "bytes32"):
        return IRnode.from_list(
            [
                "seq",
                ["mstore", MemoryPositions.FREE_VAR_SPACE, sub],
                ["sha3", MemoryPositions.FREE_VAR_SPACE, 32],
            ],
            typ=BaseType("bytes32"),
            add_gas_estimate=_gas_bound(1),
        )

    sub = ensure_in_memory(sub, context)

    return IRnode.from_list(
        [
            "with",
            "_buf",
            sub,
            ["sha3", ["add", "_buf", 32], ["mload", "_buf"]],
        ],
        typ=BaseType("bytes32"),
        annotation="keccak256",
        add_gas_estimate=_gas_bound(ceil(sub.typ.maxlen / 32)),
    )

def headerReceived(self, line):
    """
    Do pre-processing (for content-length) and store this header away.
    Enforce the per-request header limit.

    @type line: C{bytes}
    @param line: A line from the header section of a request, excluding the
        line delimiter.

    @return: A flag indicating whether the header was valid.
    @rtype: L{bool}
    """
    try:
        header, data = line.split(b":", 1)
    except ValueError:
        self._respondToBadRequestAndDisconnect()
        return False

    if not header or header[-1:].isspace():
        self._respondToBadRequestAndDisconnect()
        return False

    header = header.lower()
    data = data.strip()

    if not self._maybeChooseTransferDecoder(header, data):
        return False

    reqHeaders = self.requests[-1].requestHeaders
    values = reqHeaders.getRawHeaders(header)
    if values is not None:
        values.append(data)
    else:
        reqHeaders.setRawHeaders(header, [data])

    self._receivedHeaderCount += 1
    if self._receivedHeaderCount > self.maxHeaders:
        self._respondToBadRequestAndDisconnect()
        return False

    return True

def _dataReceived_CHUNK_LENGTH(self) -> bool:
    """
    Read the chunk size line, ignoring any extensions.

    @returns: C{True} once the line has been read and removed from
        C{self._buffer}.  C{False} when more data is required.

    @raises _MalformedChunkedDataError: when the chunk size cannot be
        decoded or the length of the line exceeds L{maxChunkSizeLineLength}.
    """
    eolIndex = self._buffer.find(b"\r\n", self._start)

    if eolIndex >= maxChunkSizeLineLength or (
        eolIndex == -1 and len(self._buffer) > maxChunkSizeLineLength
    ):
        raise _MalformedChunkedDataError(
            "Chunk size line exceeds maximum of {} bytes.".format(
                maxChunkSizeLineLength
            )
        )

    if eolIndex == -1:
        # Restart the search upon receipt of more data at the start of the
        # new data, minus one in case the last character of the buffer is
        # CR.
        self._start = len(self._buffer) - 1
        return False

    endOfLengthIndex = self._buffer.find(b";", 0, eolIndex)
    if endOfLengthIndex == -1:
        endOfLengthIndex = eolIndex
    try:
        length = int(self._buffer[0:endOfLengthIndex], 16)
    except ValueError:
        raise _MalformedChunkedDataError("Chunk-size must be an integer.")

    if length < 0:
        raise _MalformedChunkedDataError("Chunk-size must not be negative.")
    elif length == 0:
        self.state = "TRAILER"
    else:
        self.state = "BODY"

    self.length = length
    del self._buffer[0 : eolIndex + 2]
    self._start = 0
    return True

def fromChunk(data):
    """
    Convert chunk to string.

    @type data: C{bytes}

    @return: tuple of (result, remaining) - both C{bytes}.

    @raise ValueError: If the given data is not a correctly formatted chunked
        byte string.
    """
    prefix, rest = data.split(b"\r\n", 1)
    length = int(prefix, 16)
    if length < 0:
        raise ValueError("Chunk length must be >= 0, not %d" % (length,))
    if rest[length : length + 2] != b"\r\n":
        raise ValueError("chunk must end with CRLF")
    return rest[:length], rest[length + 2 :]

def _get_element_ptr_array(parent, key, array_bounds_check):

    assert isinstance(parent.typ, ArrayLike)

    if not is_integer_type(key.typ):
        raise TypeCheckFailure(f"{key.typ} used as array index")

    subtype = parent.typ.subtype

    if parent.value == "~empty":
        if array_bounds_check:
            # this case was previously missing a bounds check. codegen
            # is a bit complicated when bounds check is required, so
            # block it. there is no reason to index into a literal empty
            # array anyways!
            raise TypeCheckFailure("indexing into zero array not allowed")
        return IRnode.from_list("~empty", subtype)

    if parent.value == "multi":
        assert isinstance(key.value, int)
        return parent.args[key.value]

    ix = unwrap_location(key)

    if array_bounds_check:
        # clamplt works, even for signed ints. since two's-complement
        # is used, if the index is negative, (unsigned) LT will interpret
        # it as a very large number, larger than any practical value for
        # an array index, and the clamp will throw an error.
        clamp_op = "uclamplt"
        is_darray = isinstance(parent.typ, DArrayType)
        bound = get_dyn_array_count(parent) if is_darray else parent.typ.count
        # NOTE: there are optimization rules for this when ix or bound is literal
        ix = IRnode.from_list([clamp_op, ix, bound], typ=ix.typ)

    if parent.encoding in (Encoding.ABI, Encoding.JSON_ABI):
        if parent.location == STORAGE:
            raise CompilerPanic("storage variables should not be abi encoded")  # pragma: notest

        member_abi_t = subtype.abi_type

        ofst = _mul(ix, member_abi_t.embedded_static_size())

        return _getelemptr_abi_helper(parent, subtype, ofst)

    if parent.location.word_addressable:
        element_size = subtype.storage_size_in_words
    elif parent.location.byte_addressable:
        element_size = subtype.memory_bytes_required
    else:
        raise CompilerPanic("unreachable")  # pragma: notest

    ofst = _mul(ix, element_size)

    if has_length_word(parent.typ):
        data_ptr = add_ofst(parent, parent.location.word_scale * DYNAMIC_ARRAY_OVERHEAD)
    else:
        data_ptr = parent

    return IRnode.from_list(add_ofst(data_ptr, ofst), typ=subtype, location=parent.location)

def _get_element_ptr_tuplelike(parent, key):
    typ = parent.typ
    assert isinstance(typ, TupleLike)

    if isinstance(typ, StructType):
        assert isinstance(key, str)
        subtype = typ.members[key]
        attrs = list(typ.tuple_keys())
        index = attrs.index(key)
        annotation = key
    else:
        assert isinstance(key, int)
        subtype = typ.members[key]
        attrs = list(range(len(typ.members)))
        index = key
        annotation = None

    # generated by empty() + make_setter
    if parent.value == "~empty":
        return IRnode.from_list("~empty", typ=subtype)

    if parent.value == "multi":
        assert parent.encoding != Encoding.ABI, "no abi-encoded literals"
        return parent.args[index]

    ofst = 0  # offset from parent start

    if parent.encoding in (Encoding.ABI, Encoding.JSON_ABI):
        if parent.location == STORAGE:
            raise CompilerPanic("storage variables should not be abi encoded")  # pragma: notest

        member_t = typ.members[attrs[index]]

        for i in range(index):
            member_abi_t = typ.members[attrs[i]].abi_type
            ofst += member_abi_t.embedded_static_size()

        return _getelemptr_abi_helper(parent, member_t, ofst)

    if parent.location.word_addressable:
        for i in range(index):
            ofst += typ.members[attrs[i]].storage_size_in_words
    elif parent.location.byte_addressable:
        for i in range(index):
            ofst += typ.members[attrs[i]].memory_bytes_required
    else:
        raise CompilerPanic(f"bad location {parent.location}")  # pragma: notest

    return IRnode.from_list(
        add_ofst(parent, ofst),
        typ=subtype,
        location=parent.location,
        encoding=parent.encoding,
        annotation=annotation,
    )

def needs_clamp(t, encoding):
    if encoding not in (Encoding.ABI, Encoding.JSON_ABI):
        return False
    if isinstance(t, (ByteArrayLike, DArrayType)):
        if encoding == Encoding.JSON_ABI:
            # don't have bytestring size bound from json, don't clamp
            return False
        return True
    if isinstance(t, BaseType) and t.typ not in ("int256", "uint256", "bytes32"):
        return True
    if isinstance(t, SArrayType):
        return needs_clamp(t.subtype, encoding)
    if isinstance(t, TupleLike):
        return any(needs_clamp(m, encoding) for m in t.tuple_members())
    return False

def new_type_to_old_type(typ: new.BasePrimitive) -> old.NodeType:
    if isinstance(typ, new.BoolDefinition):
        return old.BaseType("bool")
    if isinstance(typ, new.AddressDefinition):
        return old.BaseType("address")
    if isinstance(typ, new.InterfaceDefinition):
        return old.InterfaceType(typ._id)
    if isinstance(typ, new.BytesMDefinition):
        m = typ._length  # type: ignore
        return old.BaseType(f"bytes{m}")
    if isinstance(typ, new.BytesArrayDefinition):
        return old.ByteArrayType(typ.length)
    if isinstance(typ, new.StringDefinition):
        return old.StringType(typ.length)
    if isinstance(typ, new.DecimalDefinition):
        return old.BaseType("decimal")
    if isinstance(typ, new.SignedIntegerAbstractType):
        bits = typ._bits  # type: ignore
        return old.BaseType("int" + str(bits))
    if isinstance(typ, new.UnsignedIntegerAbstractType):
        bits = typ._bits  # type: ignore
        return old.BaseType("uint" + str(bits))
    if isinstance(typ, new.ArrayDefinition):
        return old.SArrayType(new_type_to_old_type(typ.value_type), typ.length)
    if isinstance(typ, new.DynamicArrayDefinition):
        return old.DArrayType(new_type_to_old_type(typ.value_type), typ.length)
    if isinstance(typ, new.TupleDefinition):
        return old.TupleType(typ.value_type)
    if isinstance(typ, new.StructDefinition):
        return old.StructType(
            {n: new_type_to_old_type(t) for (n, t) in typ.members.items()}, typ._id
        )
    raise InvalidType(f"unknown type {typ}")

def _flush_exception(self, flush):
    if flush:
        try:
            return (flush(), False)
        except OSError:
            if self.adj.log_socket_errors:
                self.logger.exception("Socket error")
            self.will_close = True

            return (False, True)
        except Exception:  # pragma: nocover
            self.logger.exception("Unexpected exception when flushing")
            self.will_close = True

            return (False, True)

def _flush_some(self):
    # Send as much data as possible to our client

    sent = 0
    dobreak = False

    while True:
        outbuf = self.outbufs[0]
        # use outbuf.__len__ rather than len(outbuf) FBO of not getting
        # OverflowError on 32-bit Python
        outbuflen = outbuf.__len__()

        while outbuflen > 0:
            chunk = outbuf.get(self.sendbuf_len)
            num_sent = self.send(chunk)

            if num_sent:
                outbuf.skip(num_sent, True)
                outbuflen -= num_sent
                sent += num_sent
                self.total_outbufs_len -= num_sent
            else:
                # failed to write anything, break out entirely
                dobreak = True

                break
        else:
            # self.outbufs[-1] must always be a writable outbuf

            if len(self.outbufs) > 1:
                toclose = self.outbufs.pop(0)
                try:
                    toclose.close()
                except Exception:
                    self.logger.exception("Unexpected error when closing an outbuf")
            else:
                # caught up, done flushing for now
                dobreak = True

        if dobreak:
            break

    if sent:
        self.last_activity = time.time()

        return True

    return False

def _flush_some_if_lockable(self):
    # Since our task may be appending to the outbuf, we try to acquire
    # the lock, but we don't block if we can't.

    if self.outbuf_lock.acquire(False):
        try:
            self._flush_some()

            if self.total_outbufs_len < self.adj.outbuf_high_watermark:
                self.outbuf_lock.notify()
        finally:
            self.outbuf_lock.release()

def send(self, data):
    try:
        result = self.socket.send(data)
        return result
    except OSError as why:
        if why.args[0] == EWOULDBLOCK:
            return 0
        elif why.args[0] in _DISCONNECTED:
            self.handle_close()
            return 0
        else:
            raise

def get_ipcache_entry(self, client):
    """Build a cache of dns results."""
    if client in self.ipcache:
        if self.ipcache[client]:
            return self.ipcache[client]
        else:
            raise socket.gaierror
    else:
        # need to add entry
        try:
            ipaddr = socket.gethostbyname(client)
            self.ipcache[client] = (ipaddr, client)
            return (ipaddr, client)
        except socket.gaierror:
            cmd = "getent hosts %s" % client
            ipaddr = Popen(cmd, shell=True, \
                           stdout=PIPE).stdout.read().strip().split()
            if ipaddr:
                self.ipcache[client] = (ipaddr, client)
                return (ipaddr, client)
            self.ipcache[client] = False
            self.logger.error("Failed to find IP address for %s" % client)
            raise socket.gaierror

