def remove(self, name):
    if os.path.exists(os.path.join(self._path, name)):
        os.remove(os.path.join(self._path, name))

@property
def text(self):
    components = (
        ical.Timezone, ical.Event, ical.Todo, ical.Journal, ical.Card)
    items = set()
    try:
        filenames = os.listdir(self._path)
    except (OSError, IOError) as e:
        log.LOGGER.info('Error while reading collection %r: %r'
                        % (self._path, e))
        return ""

    for filename in filenames:
        path = os.path.join(self._path, filename)
        try:
            with filesystem.open(path) as fd:
                items.update(self._parse(fd.read(), components))
        except (OSError, IOError) as e:
            log.LOGGER.warning('Error while reading item %r: %r'
                               % (path, e))

    return ical.serialize(
        self.tag, self.headers, sorted(items, key=lambda x: x.name))

def stream_exists_backend(request, user_profile, stream_id, autosubscribe):
    # type: (HttpRequest, UserProfile, int, bool) -> HttpResponse
    try:
        stream = get_and_validate_stream_by_id(stream_id, user_profile.realm)
    except JsonableError:
        stream = None
    result = {"exists": bool(stream)}
    if stream is not None:
        recipient = get_recipient(Recipient.STREAM, stream.id)
        if autosubscribe:
            bulk_add_subscriptions([stream], [user_profile])
        result["subscribed"] = is_active_subscriber(
            user_profile=user_profile,
            recipient=recipient)

        return json_success(result) # results are ignored for HEAD requests
    return json_response(data=result, status=404)

