@has_request_variables
def update_user_backend(
    request: HttpRequest,
    user_profile: UserProfile,
    user_id: int,
    full_name: Optional[str] = REQ(default=None),
    role: Optional[int] = REQ(
        default=None,
        json_validator=check_int_in(
            UserProfile.ROLE_TYPES,
        ),
    ),
    profile_data: Optional[List[Dict[str, Optional[Union[int, ProfileDataElementValue]]]]] = REQ(
        default=None,
        json_validator=check_profile_data,
    ),
) -> HttpResponse:
    target = access_user_by_id(
        user_profile, user_id, allow_deactivated=True, allow_bots=True, for_admin=True
    )

    if role is not None and target.role != role:
        # Require that the current user has permissions to
        # grant/remove the role in question.  access_user_by_id has
        # already verified we're an administrator; here we enforce
        # that only owners can toggle the is_realm_owner flag.
        #
        # Logic replicated in patch_bot_backend.
        if UserProfile.ROLE_REALM_OWNER in [role, target.role] and not user_profile.is_realm_owner:
            raise OrganizationOwnerRequired()

        if target.role == UserProfile.ROLE_REALM_OWNER and check_last_owner(target):
            raise JsonableError(
                _("The owner permission cannot be removed from the only organization owner.")
            )
        do_change_user_role(target, role, acting_user=user_profile)

    if full_name is not None and target.full_name != full_name and full_name.strip() != "":
        # We don't respect `name_changes_disabled` here because the request
        # is on behalf of the administrator.
        check_change_full_name(target, full_name, user_profile)

    if profile_data is not None:
        clean_profile_data: List[ProfileDataElementUpdateDict] = []
        for entry in profile_data:
            assert isinstance(entry["id"], int)
            assert not isinstance(entry["value"], int)
            if entry["value"] is None or not entry["value"]:
                field_id = entry["id"]
                check_remove_custom_profile_field_value(target, field_id)
            else:
                clean_profile_data.append(
                    {
                        "id": entry["id"],
                        "value": entry["value"],
                    }
                )
        validate_user_custom_profile_data(target.realm.id, clean_profile_data)
        do_update_user_custom_profile_data_if_changed(target, clean_profile_data)

    return json_success(request)

def serve_file_unauthed_from_token(
    request: HttpRequest, token: str, filename: str
) -> HttpResponseBase:
    path_id = get_file_path_id_from_token(token)
    if path_id is None:
        raise JsonableError(_("Invalid token"))
    if path_id.split("/")[-1] != filename:
        raise JsonableError(_("Invalid filename"))

    mimetype, encoding = guess_type(path_id)
    download = mimetype not in INLINE_MIME_TYPES

    if settings.LOCAL_UPLOADS_DIR is not None:
        return serve_local(request, path_id, download=download)
    else:
        return serve_s3(request, path_id, download=download)

def serve_file(
    request: HttpRequest,
    maybe_user_profile: Union[UserProfile, AnonymousUser],
    realm_id_str: str,
    filename: str,
    url_only: bool = False,
    download: bool = False,
) -> HttpResponseBase:
    path_id = f"{realm_id_str}/{filename}"
    realm = get_valid_realm_from_request(request)
    is_authorized = validate_attachment_request(maybe_user_profile, path_id, realm)

    if is_authorized is None:
        return HttpResponseNotFound(_("<p>File not found.</p>"))
    if not is_authorized:
        return HttpResponseForbidden(_("<p>You are not authorized to view this file.</p>"))
    if url_only:
        url = generate_unauthed_file_access_url(path_id)
        return json_success(request, data=dict(url=url))

    mimetype, encoding = guess_type(path_id)
    download = download or mimetype not in INLINE_MIME_TYPES

    if settings.LOCAL_UPLOADS_DIR is not None:
        return serve_local(request, path_id, download=download)
    else:
        return serve_s3(request, path_id, download=download)

def handle_delete_user(self, req):
    """Handles the DELETE v2/<account>/<user> call for deleting a user from an
    account.

    Can only be called by an account .admin.

    :param req: The swob.Request to process.
    :returns: swob.Response, 2xx on success.
    """
    # Validate path info
    account = req.path_info_pop()
    user = req.path_info_pop()
    if req.path_info or not account or account[0] == '.' or not user or \
            user[0] == '.':
        return HTTPBadRequest(request=req)

    # if user to be deleted is reseller_admin, then requesting
    # user must be the super_admin
    is_reseller_admin = self.is_user_reseller_admin(req, account, user)
    if not is_reseller_admin and not req.credentials_valid:
        # if user to be deleted can't be found, return 404
        return HTTPNotFound(request=req)
    elif is_reseller_admin and not self.is_super_admin(req):
        return HTTPForbidden(request=req)

    if not self.is_account_admin(req, account):
        return self.denied_response(req)

    # Delete the user's existing token, if any.
    path = quote('/v1/%s/%s/%s' % (self.auth_account, account, user))
    resp = self.make_pre_authed_request(
        req.environ, 'HEAD', path).get_response(self.app)
    if resp.status_int == 404:
        return HTTPNotFound(request=req)
    elif resp.status_int // 100 != 2:
        raise Exception('Could not obtain user details: %s %s' %
                        (path, resp.status))
    candidate_token = resp.headers.get('x-object-meta-auth-token')
    if candidate_token:
        path = quote('/v1/%s/.token_%s/%s' %
            (self.auth_account, candidate_token[-1], candidate_token))
        resp = self.make_pre_authed_request(
            req.environ, 'DELETE', path).get_response(self.app)
        if resp.status_int // 100 != 2 and resp.status_int != 404:
            raise Exception('Could not delete possibly existing token: '
                            '%s %s' % (path, resp.status))
    # Delete the user entry itself.
    path = quote('/v1/%s/%s/%s' % (self.auth_account, account, user))
    resp = self.make_pre_authed_request(
        req.environ, 'DELETE', path).get_response(self.app)
    if resp.status_int // 100 != 2 and resp.status_int != 404:
        raise Exception('Could not delete the user object: %s %s' %
                        (path, resp.status))
    return HTTPNoContent(request=req)

