def post(self, request, *args, **kwargs):
    serializer = self.serializer_class(data=request.data, context={'request': request})
    serializer.is_valid(raise_exception=True)
    user = serializer.validated_data['user']
    if user is None:
        return FormattedResponse(status=HTTP_401_UNAUTHORIZED, d={'reason': 'login_failed'}, m='login_failed')

    if not user.has_2fa():
        return FormattedResponse(status=HTTP_401_UNAUTHORIZED, d={'reason': '2fa_not_enabled'}, m='2fa_not_enabled')

    token = serializer.data['tfa']

    if len(token) == 6:
        if user.totp_device is not None and user.totp_device.validate_token(token):
            return self.issue_token(user)
    elif len(token) == 8:
        for code in user.backup_codes:
            if token == code.code:
                code.delete()
                return self.issue_token(user)

    return self.issue_token(user)

@api_view(['GET', 'POST'])
@permission_classes([IsAuthenticated])
def project_configure(request, project_name):
    """
    get configuration
    :param request: request object
    :param project_name: project name
    :return: json
    """
    # get configuration
    if request.method == 'GET':
        project = Project.objects.get(name=project_name)
        project = model_to_dict(project)
        project['configuration'] = json.loads(project['configuration']) if project['configuration'] else None
        return JsonResponse(project)

    # update configuration
    elif request.method == 'POST':
        project = Project.objects.filter(name=project_name)
        data = json.loads(request.body)
        configuration = json.dumps(data.get('configuration'), ensure_ascii=False)
        project.update(**{'configuration': configuration})

        # for safe protection
        project_name = re.sub('[\!\@\#\$\;\&\*\~\"\'\{\}\]\[\-\+\%\^]+', '', project_name)
        # execute generate cmd
        cmd = ' '.join(['gerapy', 'generate', project_name])
        p = Popen(cmd, shell=True, stdin=PIPE, stdout=PIPE, stderr=PIPE)
        stdout, stderr = bytes2str(p.stdout.read()), bytes2str(p.stderr.read())

        if not stderr:
            return JsonResponse({'status': '1'})
        else:
            return JsonResponse({'status': '0', 'message': stderr})

async def handle_404(request, response):
    if 'json' not in response.headers['Content-Type']:
        if request.path.endswith('/'):
            return web.HTTPFound(request.path.rstrip('/'))
        return web.json_response({
            "status": 404,
            "message": "Page '{}' not found".format(request.path)
        }, status=404)
    return response

def handle(self, command, kwargs=None):
    """
    Dispatch and handle processing of the given command.

    :param command: Name of command to run.
    :type command: unicode
    :param kwargs: Arguments to pass to the command handler. If empty, `request.POST` is used.
    :type kwargs: dict
    :return: response.
    :rtype: HttpResponse
    """

    kwargs = kwargs or dict(six.iteritems(self.request.POST))
    try:
        handler = self.get_command_handler(command)
        if not handler or not callable(handler):
            raise Problem(_("Error! Invalid command `%s`.") % command)
        kwargs.pop("csrfmiddlewaretoken", None)  # The CSRF token should never be passed as a kwarg
        kwargs.pop("command", None)  # Nor the command
        kwargs.update(request=self.request, basket=self.basket)
        kwargs = self.preprocess_kwargs(command, kwargs)

        response = handler(**kwargs) or {}

    except (Problem, ValidationError) as exc:
        if not self.ajax:
            raise
        msg = exc.message if hasattr(exc, "message") else exc
        response = {
            "error": force_text(msg, errors="ignore"),
            "code": force_text(getattr(exc, "code", None) or "", errors="ignore"),
        }

    response = self.postprocess_response(command, kwargs, response)

    if self.ajax:
        return JsonResponse(response)

    return_url = response.get("return") or kwargs.get("return")
    if return_url and return_url.startswith("/"):
        return HttpResponseRedirect(return_url)
    return redirect("shuup:basket")

def get_current_phase(self, requested_phase_identifier):
    found = False
    for phase in self.phases:
        if phase.is_valid():
            phase.process()
        if found or not requested_phase_identifier or requested_phase_identifier == phase.identifier:
            found = True  # We're at or past the requested phase
            if not phase.should_skip():
                return phase
        if not phase.should_skip() and not phase.is_valid():  # A past phase is not valid, that's the current one
            return phase
    raise Http404("Error! Phase with identifier `%s` not found." % requested_phase_identifier)  # pragma: no cover

def extract_messages(obj_list):
    """
    Extract "messages" from a list of exceptions or other objects.

    For ValidationErrors, `messages` are flattened into the output.
    For Exceptions, `args[0]` is added into the output.
    For other objects, `force_text` is called.

    :param obj_list: List of exceptions etc.
    :type obj_list: Iterable[object]
    :rtype: Iterable[str]
    """
    for obj in obj_list:
        if isinstance(obj, ValidationError):
            for msg in obj.messages:
                yield force_text(msg)
            continue
        if isinstance(obj, Exception):
            if len(obj.args):
                yield force_text(obj.args[0])
                continue
        yield force_text(obj)

def post(self, request, *args, **kwargs):  # doccov: ignore
    command = request.POST.get("command")
    if command:
        dispatcher = getattr(self, "dispatch_%s" % command, None)
        if not callable(dispatcher):
            raise Problem(_("Unknown command: `%s`.") % command)
        dispatch_kwargs = dict(request.POST.items())
        rv = dispatcher(**dispatch_kwargs)
        if rv:
            return rv
        self.request.method = "GET"  # At this point, we won't want to cause form validation
        self.build_form()  # and it's not a bad idea to rebuild the form
        return super(EditorView, self).get(request, *args, **kwargs)

    if request.POST.get("save") and self.form and self.form.is_valid():
        self.form.save()
        self.save_layout()

        # after we save the new layout configs, make sure to reload the saved data in forms
        # so the returned get() response contains updated data
        self.build_form()

        if request.POST.get("publish") == "1":
            return self.dispatch_publish()

    return self.get(request, *args, **kwargs)

def _load_yamlconfig(self, configfile):
    yamlconfig = None
    try:
        if self._recent_pyyaml():
            # https://github.com/yaml/pyyaml/wiki/PyYAML-yaml.load(input)-Deprecation
            # only for 5.1+
            yamlconfig = yaml.load(open(configfile), Loader=yaml.FullLoader)
        else:
            yamlconfig = yaml.load(open(configfile))
    except yaml.YAMLError as exc:
        logger.error("Error in configuration file {0}:".format(configfile))
        if hasattr(exc, 'problem_mark'):
            mark = exc.problem_mark
            raise PystemonConfigException("error position: (%s:%s)" % (mark.line + 1, mark.column + 1))
    for includes in yamlconfig.get("includes", []):
        try:
            logger.debug("loading include '{0}'".format(includes))
            yamlconfig.update(yaml.load(open(includes)))
        except Exception as e:
            raise PystemonConfigException("failed to load '{0}': {1}".format(includes, e))
    return yamlconfig

def redirect_output(outfmt, errfmt, o_out=None, o_err=None):

    if is_true(os.environ.get("_CLOUD_INIT_SAVE_STDOUT")):
        LOG.debug("Not redirecting output due to _CLOUD_INIT_SAVE_STDOUT")
        return

    if not o_out:
        o_out = sys.stdout
    if not o_err:
        o_err = sys.stderr

    if outfmt:
        LOG.debug("Redirecting %s to %s", o_out, outfmt)
        (mode, arg) = outfmt.split(" ", 1)
        if mode == ">" or mode == ">>":
            owith = "ab"
            if mode == ">":
                owith = "wb"
            new_fp = open(arg, owith)
        elif mode == "|":
            proc = subprocess.Popen(arg, shell=True, stdin=subprocess.PIPE)
            new_fp = proc.stdin
        else:
            raise TypeError("Invalid type for output format: %s" % outfmt)

        if o_out:
            os.dup2(new_fp.fileno(), o_out.fileno())

        if errfmt == outfmt:
            LOG.debug("Redirecting %s to %s", o_err, outfmt)
            os.dup2(new_fp.fileno(), o_err.fileno())
            return

    if errfmt:
        LOG.debug("Redirecting %s to %s", o_err, errfmt)
        (mode, arg) = errfmt.split(" ", 1)
        if mode == ">" or mode == ">>":
            owith = "ab"
            if mode == ">":
                owith = "wb"
            new_fp = open(arg, owith)
        elif mode == "|":
            proc = subprocess.Popen(arg, shell=True, stdin=subprocess.PIPE)
            new_fp = proc.stdin
        else:
            raise TypeError("Invalid type for error format: %s" % errfmt)

        if o_err:
            os.dup2(new_fp.fileno(), o_err.fileno())

def validate_cloudconfig_schema(
    config: dict,
    schema: dict = None,
    strict: bool = False,
    strict_metaschema: bool = False,
):
    """Validate provided config meets the schema definition.

    @param config: Dict of cloud configuration settings validated against
        schema. Ignored if strict_metaschema=True
    @param schema: jsonschema dict describing the supported schema definition
       for the cloud config module (config.cc_*). If None, validate against
       global schema.
    @param strict: Boolean, when True raise SchemaValidationErrors instead of
       logging warnings.
    @param strict_metaschema: Boolean, when True validates schema using strict
       metaschema definition at runtime (currently unused)

    @raises: SchemaValidationError when provided config does not validate
        against the provided schema.
    @raises: RuntimeError when provided config sourced from YAML is not a dict.
    """
    if schema is None:
        schema = get_schema()
    try:
        (cloudinitValidator, FormatChecker) = get_jsonschema_validator()
        if strict_metaschema:
            validate_cloudconfig_metaschema(
                cloudinitValidator, schema, throw=False
            )
    except ImportError:
        LOG.debug("Ignoring schema validation. jsonschema is not present")
        return

    validator = cloudinitValidator(schema, format_checker=FormatChecker())
    errors: Tuple[Tuple[str, str], ...] = ()
    for error in sorted(validator.iter_errors(config), key=lambda e: e.path):
        path = ".".join([str(p) for p in error.path])
        errors += ((path, error.message),)
    if errors:
        if strict:
            raise SchemaValidationError(errors)
        else:
            messages = ["{0}: {1}".format(k, msg) for k, msg in errors]
            LOG.warning(
                "Invalid cloud-config provided:\n%s", "\n".join(messages)
            )

def process_instance_metadata(metadata, key_path="", sensitive_keys=()):
    """Process all instance metadata cleaning it up for persisting as json.

    Strip ci-b64 prefix and catalog any 'base64_encoded_keys' as a list

    @return Dict copy of processed metadata.
    """
    md_copy = copy.deepcopy(metadata)
    base64_encoded_keys = []
    sens_keys = []
    for key, val in metadata.items():
        if key_path:
            sub_key_path = key_path + "/" + key
        else:
            sub_key_path = key
        if key in sensitive_keys or sub_key_path in sensitive_keys:
            sens_keys.append(sub_key_path)
        if isinstance(val, str) and val.startswith("ci-b64:"):
            base64_encoded_keys.append(sub_key_path)
            md_copy[key] = val.replace("ci-b64:", "")
        if isinstance(val, dict):
            return_val = process_instance_metadata(
                val, sub_key_path, sensitive_keys
            )
            base64_encoded_keys.extend(return_val.pop("base64_encoded_keys"))
            sens_keys.extend(return_val.pop("sensitive_keys"))
            md_copy[key] = return_val
    md_copy["base64_encoded_keys"] = sorted(base64_encoded_keys)
    md_copy["sensitive_keys"] = sorted(sens_keys)
    return md_copy

def _initialize_filesystem(self):
    util.ensure_dirs(self._initial_subdirs())
    log_file = util.get_cfg_option_str(self.cfg, "def_log_file")
    if log_file:
        util.ensure_file(log_file, mode=0o640, preserve_mode=True)
        perms = self.cfg.get("syslog_fix_perms")
        if not perms:
            perms = {}
        if not isinstance(perms, list):
            perms = [perms]

        error = None
        for perm in perms:
            u, g = util.extract_usergroup(perm)
            try:
                util.chownbyname(log_file, u, g)
                return
            except OSError as e:
                error = e

        LOG.warning(
            "Failed changing perms on '%s'. tried: %s. %s",
            log_file,
            ",".join(perms),
            error,
        )

@staff_member_required
def switch_user(request, object_id):

    # current/session user
    current_user = request.user
    session_user = request.session.get("original_user", {"id": current_user.id, "username": current_user.get_username()})

    # check redirect
    redirect_url = request.GET.get("redirect", None)
    if redirect_url is None or not redirect_url.startswith("/"):
        raise Http404()

    # check original_user
    try:
        original_user = User.objects.get(pk=session_user["id"], is_staff=True)
        if not SWITCH_USER_ORIGINAL(original_user):
            messages.add_message(request, messages.ERROR, _("Permission denied."))
            return redirect(request.GET.get("redirect"))
    except ObjectDoesNotExist:
        msg = _('%(name)s object with primary key %(key)r does not exist.') % {'name': "User", 'key': escape(session_user["id"])}
        messages.add_message(request, messages.ERROR, msg)
        return redirect(request.GET.get("redirect"))

    # check new user
    try:
        target_user = User.objects.get(pk=object_id, is_staff=True)
        if target_user != original_user and not SWITCH_USER_TARGET(original_user, target_user):
            messages.add_message(request, messages.ERROR, _("Permission denied."))
            return redirect(request.GET.get("redirect"))
    except ObjectDoesNotExist:
        msg = _('%(name)s object with primary key %(key)r does not exist.') % {'name': "User", 'key': escape(object_id)}
        messages.add_message(request, messages.ERROR, msg)
        return redirect(request.GET.get("redirect"))

    # find backend
    if not hasattr(target_user, 'backend'):
        for backend in settings.AUTHENTICATION_BACKENDS:
            if target_user == load_backend(backend).get_user(target_user.pk):
                target_user.backend = backend
                break

    # target user login, set original as session
    if hasattr(target_user, 'backend'):
        login(request, target_user)
        if original_user.id != target_user.id:
            request.session["original_user"] = {"id": original_user.id, "username": original_user.get_username()}

    return redirect(request.GET.get("redirect"))

@catch_mlflow_exception
def create_user():
    content_type = request.headers.get("Content-Type")
    if content_type == "application/x-www-form-urlencoded":
        username = request.form["username"]
        password = request.form["password"]

        if store.has_user(username):
            flash(f"Username has already been taken: {username}")
            return alert(href=SIGNUP)

        store.create_user(username, password)
        flash(f"Successfully signed up user: {username}")
        return alert(href=HOME)
    elif content_type == "application/json":
        username = _get_request_param("username")
        password = _get_request_param("password")

        user = store.create_user(username, password)
        return make_response({"user": user.to_json()})
    else:
        return make_response(f"Invalid content type: '{content_type}'", 400)

