@classmethod
def mutate(cls, root, info: ResolveInfo, **data):
    disallow_replica_in_context(info.context)
    setup_context_user(info.context)

    if not cls.check_permissions(info.context, data=data):
        raise PermissionDenied(permissions=cls._meta.permissions)
    manager = get_plugin_manager_promise(info.context).get()
    result = manager.perform_mutation(
        mutation_cls=cls, root=root, info=info, data=data
    )
    if result is not None:
        return result

    try:
        response = cls.perform_mutation(root, info, **data)
        if response.errors is None:
            response.errors = []
        return response
    except ValidationError as e:
        return cls.handle_errors(e)

@classmethod
def get_refresh_token(
    cls, info: ResolveInfo, refresh_token: Optional[str] = None
) -> Optional[str]:
    request = info.context
    refresh_token = refresh_token or request.COOKIES.get(
        JWT_REFRESH_TOKEN_COOKIE_NAME, None
    )
    return refresh_token

@classmethod
def clean_refresh_token(cls, refresh_token):
    if not refresh_token:
        raise ValidationError(
            {
                "refresh_token": ValidationError(
                    "Missing refreshToken",
                    code=AccountErrorCode.JWT_MISSING_TOKEN.value,
                )
            }
        )
    payload = cls.get_refresh_token_payload(refresh_token)
    if payload["type"] != JWT_REFRESH_TYPE:
        raise ValidationError(
            {
                "refresh_token": ValidationError(
                    "Incorrect refreshToken",
                    code=AccountErrorCode.JWT_INVALID_TOKEN.value,
                )
            }
        )
    return payload

@staticmethod
def get_files_from_storage(paths):
    """Return S3 file where the name does not include the path."""
    for path in paths:
        path = pathlib.PurePosixPath(path)
        try:
            location = storage.aws_location
        except AttributeError:
            location = storage.location
        try:
            f = storage.open(str(path.relative_to(location)))
            f.name = path.name
            yield f
        except (OSError, ValueError):
            logger.exception("File not found: %s", path)

def __call__(self, request):
    file_fields = request.POST.getlist("s3file")
    for field_name in file_fields:
        paths = request.POST.getlist(field_name)
        request.FILES.setlist(field_name, list(self.get_files_from_storage(paths)))

    if local_dev and request.path == "/__s3_mock__/":
        return views.S3MockView.as_view()(request)

    return self.get_response(request)

