def check_and_call_git_repository_function(request, pk, func):
    """Helper for checking Git permissions and worker availability, then calling provided function if all is well
    Args:
        request (HttpRequest): request object.
        pk (UUID): GitRepository pk value.
        func (function): Enqueue git repo function.
    Returns:
        (Union[HttpResponseForbidden,redirect]): HttpResponseForbidden if user does not have permission to run the job,
            otherwise redirect to the job result page.
    """
    if not request.user.has_perm("extras.change_gitrepository"):
        return HttpResponseForbidden()

    # Allow execution only if a worker process is running.
    if not get_worker_count():
        messages.error(request, "Unable to run job: Celery worker process not running.")
        return redirect(request.get_full_path(), permanent=False)
    else:
        repository = get_object_or_404(GitRepository, pk=pk)
        job_result = func(repository, request.user)

    return redirect(job_result.get_absolute_url())

def render(
    self, tokens: Sequence[Token], options: OptionsDict, env: MutableMapping
) -> str:
    """Takes token stream and generates HTML.

    :param tokens: list on block tokens to render
    :param options: params of parser instance
    :param env: additional data from parsed input

    """
    result = ""

    for i, token in enumerate(tokens):
        if token.type == "inline":
            assert token.children is not None
            result += self.renderInline(token.children, options, env)
        elif token.type in self.rules:
            result += self.rules[token.type](tokens, i, options, env)
        else:
            result += self.renderToken(tokens, i, options, env)

    return result

def replace(state: StateCore) -> None:
    if not state.md.options.typographer:
        return

    for token in state.tokens:
        if token.type != "inline":
            continue
        assert token.children is not None

        if SCOPED_ABBR_RE.search(token.content):
            replace_scoped(token.children)

        if RARE_RE.search(token.content):
            replace_rare(token.children)

def smartquotes(state: StateCore) -> None:
    if not state.md.options.typographer:
        return

    for token in state.tokens:
        if token.type != "inline" or not QUOTE_RE.search(token.content):
            continue
        assert token.children is not None
        process_inlines(token.children, state)

def connect(self) -> dict:
    """
    Set up the connection required by the handler.
    Returns:
        HandlerStatusResponse
    """

    headers = {
        'Content-Type': 'application/json',
    }

    data = '{' + f'"userName": "{self.connection_data["username"]}","password": "{self.connection_data["password"]}"' + '}'

    response = requests.post(self.base_url + '/apiv2/login', headers=headers, data=data, verify=False)

    return {
        'Authorization': '_dremio' + response.json()['token'],
        'Content-Type': 'application/json',
    }

def on_headers_finished(self) -> None:
    message = (MultiPartMessage.HEADERS_FINISHED, b"")
    self.messages.append(message)

def __init__(
    self, headers: Headers, stream: typing.AsyncGenerator[bytes, None]
) -> None:
    assert (
        multipart is not None
    ), "The `python-multipart` library must be installed to use form parsing."
    self.headers = headers
    self.stream = stream
    self.messages: typing.List[typing.Tuple[MultiPartMessage, bytes]] = []

async def _get_form(self) -> FormData:
    if self._form is None:
        assert (
            parse_options_header is not None
        ), "The `python-multipart` library must be installed to use form parsing."
        content_type_header = self.headers.get("Content-Type")
        content_type: bytes
        content_type, _ = parse_options_header(content_type_header)
        if content_type == b"multipart/form-data":
            try:
                multipart_parser = MultiPartParser(self.headers, self.stream())
                self._form = await multipart_parser.parse()
            except MultiPartException as exc:
                if "app" in self.scope:
                    raise HTTPException(status_code=400, detail=exc.message)
                raise exc
        elif content_type == b"application/x-www-form-urlencoded":
            form_parser = FormParser(self.headers, self.stream())
            self._form = await form_parser.parse()
        else:
            self._form = FormData()
    return self._form

def _real_extract(self, url):
    if url.startswith('//'):
        return self.url_result(self.http_scheme() + url)

    parsed_url = urllib.parse.urlparse(url)
    if not parsed_url.scheme:
        default_search = self.get_param('default_search')
        if default_search is None:
            default_search = 'fixup_error'

        if default_search in ('auto', 'auto_warning', 'fixup_error'):
            if re.match(r'^[^\s/]+\.[^\s/]+/', url):
                self.report_warning('The url doesn\'t specify the protocol, trying with http')
                return self.url_result('http://' + url)
            elif default_search != 'fixup_error':
                if default_search == 'auto_warning':
                    if re.match(r'^(?:url|URL)$', url):
                        raise ExtractorError(
                            'Invalid URL:  %r . Call yt-dlp like this:  yt-dlp -v "https://www.youtube.com/watch?v=BaW_jenozKc"  ' % url,
                            expected=True)
                    else:
                        self.report_warning(
                            'Falling back to youtube search for  %s . Set --default-search "auto" to suppress this warning.' % url)
                return self.url_result('ytsearch:' + url)

        if default_search in ('error', 'fixup_error'):
            raise ExtractorError(
                '%r is not a valid URL. '
                'Set --default-search "ytsearch" (or run  yt-dlp "ytsearch:%s" ) to search YouTube'
                % (url, url), expected=True)
        else:
            if ':' not in default_search:
                default_search += ':'
            return self.url_result(default_search + url)

    original_url = url
    url, smuggled_data = unsmuggle_url(url, {})
    force_videoid = None
    is_intentional = smuggled_data.get('to_generic')
    if 'force_videoid' in smuggled_data:
        force_videoid = smuggled_data['force_videoid']
        video_id = force_videoid
    else:
        video_id = self._generic_id(url)

    # Some webservers may serve compressed content of rather big size (e.g. gzipped flac)
    # making it impossible to download only chunk of the file (yet we need only 512kB to
    # test whether it's HTML or not). According to yt-dlp default Accept-Encoding
    # that will always result in downloading the whole file that is not desirable.
    # Therefore for extraction pass we have to override Accept-Encoding to any in order
    # to accept raw bytes and being able to download only a chunk.
    # It may probably better to solve this by checking Content-Type for application/octet-stream
    # after a HEAD request, but not sure if we can rely on this.
    full_response = self._request_webpage(url, video_id, headers={
        'Accept-Encoding': 'identity',
        **smuggled_data.get('http_headers', {})
    })
    new_url = full_response.url
    url = urllib.parse.urlparse(url)._replace(scheme=urllib.parse.urlparse(new_url).scheme).geturl()
    if new_url != extract_basic_auth(url)[0]:
        self.report_following_redirect(new_url)
        if force_videoid:
            new_url = smuggle_url(new_url, {'force_videoid': force_videoid})
        return self.url_result(new_url)

    info_dict = {
        'id': video_id,
        'title': self._generic_title(url),
        'timestamp': unified_timestamp(full_response.headers.get('Last-Modified'))
    }

    # Check for direct link to a video
    content_type = full_response.headers.get('Content-Type', '').lower()
    m = re.match(r'^(?P<type>audio|video|application(?=/(?:ogg$|(?:vnd\.apple\.|x-)?mpegurl)))/(?P<format_id>[^;\s]+)', content_type)
    if m:
        self.report_detected('direct video link')
        headers = smuggled_data.get('http_headers', {})
        format_id = str(m.group('format_id'))
        ext = determine_ext(url, default_ext=None) or urlhandle_detect_ext(full_response)
        subtitles = {}
        if format_id.endswith('mpegurl') or ext == 'm3u8':
            formats, subtitles = self._extract_m3u8_formats_and_subtitles(url, video_id, 'mp4', headers=headers)
        elif format_id.endswith('mpd') or format_id.endswith('dash+xml') or ext == 'mpd':
            formats, subtitles = self._extract_mpd_formats_and_subtitles(url, video_id, headers=headers)
        elif format_id == 'f4m' or ext == 'f4m':
            formats = self._extract_f4m_formats(url, video_id, headers=headers)
        else:
            formats = [{
                'format_id': format_id,
                'url': url,
                'ext': ext,
                'vcodec': 'none' if m.group('type') == 'audio' else None
            }]
            info_dict['direct'] = True
        info_dict.update({
            'formats': formats,
            'subtitles': subtitles,
            'http_headers': headers or None,
        })
        self._extra_manifest_info(info_dict, url)
        return info_dict

    if not self.get_param('test', False) and not is_intentional:
        force = self.get_param('force_generic_extractor', False)
        self.report_warning('%s generic information extractor' % ('Forcing' if force else 'Falling back on'))

    first_bytes = full_response.read(512)

    # Is it an M3U playlist?
    if first_bytes.startswith(b'#EXTM3U'):
        self.report_detected('M3U playlist')
        info_dict['formats'], info_dict['subtitles'] = self._extract_m3u8_formats_and_subtitles(url, video_id, 'mp4')
        self._extra_manifest_info(info_dict, url)
        return info_dict

    # Maybe it's a direct link to a video?
    # Be careful not to download the whole thing!
    if not is_html(first_bytes):
        self.report_warning(
            'URL could be a direct video link, returning it as such.')
        info_dict.update({
            'direct': True,
            'url': url,
        })
        return info_dict

    webpage = self._webpage_read_content(
        full_response, url, video_id, prefix=first_bytes)

    if '<title>DPG Media Privacy Gate</title>' in webpage:
        webpage = self._download_webpage(url, video_id)

    self.report_extraction(video_id)

    # Is it an RSS feed, a SMIL file, an XSPF playlist or a MPD manifest?
    try:
        try:
            doc = compat_etree_fromstring(webpage)
        except xml.etree.ElementTree.ParseError:
            doc = compat_etree_fromstring(webpage.encode('utf-8'))
        if doc.tag == 'rss':
            self.report_detected('RSS feed')
            return self._extract_rss(url, video_id, doc)
        elif doc.tag == 'SmoothStreamingMedia':
            info_dict['formats'], info_dict['subtitles'] = self._parse_ism_formats_and_subtitles(doc, url)
            self.report_detected('ISM manifest')
            return info_dict
        elif re.match(r'^(?:{[^}]+})?smil$', doc.tag):
            smil = self._parse_smil(doc, url, video_id)
            self.report_detected('SMIL file')
            return smil
        elif doc.tag == '{http://xspf.org/ns/0/}playlist':
            self.report_detected('XSPF playlist')
            return self.playlist_result(
                self._parse_xspf(
                    doc, video_id, xspf_url=url,
                    xspf_base_url=full_response.url),
                video_id)
        elif re.match(r'(?i)^(?:{[^}]+})?MPD$', doc.tag):
            info_dict['formats'], info_dict['subtitles'] = self._parse_mpd_formats_and_subtitles(
                doc,
                mpd_base_url=full_response.url.rpartition('/')[0],
                mpd_url=url)
            self._extra_manifest_info(info_dict, url)
            self.report_detected('DASH manifest')
            return info_dict
        elif re.match(r'^{http://ns\.adobe\.com/f4m/[12]\.0}manifest$', doc.tag):
            info_dict['formats'] = self._parse_f4m_formats(doc, url, video_id)
            self.report_detected('F4M manifest')
            return info_dict
    except xml.etree.ElementTree.ParseError:
        pass

    info_dict.update({
        # it's tempting to parse this further, but you would
        # have to take into account all the variations like
        #   Video Title - Site Name
        #   Site Name | Video Title
        #   Video Title - Tagline | Site Name
        # and so on and so forth; it's just not practical
        'title': self._generic_title('', webpage, default='video'),
        'description': self._og_search_description(webpage, default=None),
        'thumbnail': self._og_search_thumbnail(webpage, default=None),
        'age_limit': self._rta_search(webpage),
    })

    self._downloader.write_debug('Looking for embeds')
    embeds = list(self._extract_embeds(original_url, webpage, urlh=full_response, info_dict=info_dict))
    if len(embeds) == 1:
        return merge_dicts(embeds[0], info_dict)
    elif embeds:
        return self.playlist_result(embeds, **info_dict)
    raise UnsupportedError(url)

def prepare_outtmpl(self, outtmpl, info_dict, sanitize=False):
    """ Make the outtmpl and info_dict suitable for substitution: ydl.escape_outtmpl(outtmpl) % info_dict
    @param sanitize    Whether to sanitize the output as a filename.
                       For backward compatibility, a function can also be passed
    """

    info_dict.setdefault('epoch', int(time.time()))  # keep epoch consistent once set

    info_dict = self._copy_infodict(info_dict)
    info_dict['duration_string'] = (  # %(duration>%H-%M-%S)s is wrong if duration > 24hrs
        formatSeconds(info_dict['duration'], '-' if sanitize else ':')
        if info_dict.get('duration', None) is not None
        else None)
    info_dict['autonumber'] = int(self.params.get('autonumber_start', 1) - 1 + self._num_downloads)
    info_dict['video_autonumber'] = self._num_videos
    if info_dict.get('resolution') is None:
        info_dict['resolution'] = self.format_resolution(info_dict, default=None)

    # For fields playlist_index, playlist_autonumber and autonumber convert all occurrences
    # of %(field)s to %(field)0Nd for backward compatibility
    field_size_compat_map = {
        'playlist_index': number_of_digits(info_dict.get('__last_playlist_index') or 0),
        'playlist_autonumber': number_of_digits(info_dict.get('n_entries') or 0),
        'autonumber': self.params.get('autonumber_size') or 5,
    }

    TMPL_DICT = {}
    EXTERNAL_FORMAT_RE = re.compile(STR_FORMAT_RE_TMPL.format('[^)]*', f'[{STR_FORMAT_TYPES}ljhqBUDS]'))
    MATH_FUNCTIONS = {
        '+': float.__add__,
        '-': float.__sub__,
        '*': float.__mul__,
    }
    # Field is of the form key1.key2...
    # where keys (except first) can be string, int, slice or "{field, ...}"
    FIELD_INNER_RE = r'(?:\w+|%(num)s|%(num)s?(?::%(num)s?){1,2})' % {'num': r'(?:-?\d+)'}
    FIELD_RE = r'\w*(?:\.(?:%(inner)s|{%(field)s(?:,%(field)s)*}))*' % {
        'inner': FIELD_INNER_RE,
        'field': rf'\w*(?:\.{FIELD_INNER_RE})*'
    }
    MATH_FIELD_RE = rf'(?:{FIELD_RE}|-?{NUMBER_RE})'
    MATH_OPERATORS_RE = r'(?:%s)' % '|'.join(map(re.escape, MATH_FUNCTIONS.keys()))
    INTERNAL_FORMAT_RE = re.compile(rf'''(?xs)
        (?P<negate>-)?
        (?P<fields>{FIELD_RE})
        (?P<maths>(?:{MATH_OPERATORS_RE}{MATH_FIELD_RE})*)
        (?:>(?P<strf_format>.+?))?
        (?P<remaining>
            (?P<alternate>(?<!\\),[^|&)]+)?
            (?:&(?P<replacement>.*?))?
            (?:\|(?P<default>.*?))?
        )$''')

    def _from_user_input(field):
        if field == ':':
            return ...
        elif ':' in field:
            return slice(*map(int_or_none, field.split(':')))
        elif int_or_none(field) is not None:
            return int(field)
        return field

    def _traverse_infodict(fields):
        fields = [f for x in re.split(r'\.({.+?})\.?', fields)
                  for f in ([x] if x.startswith('{') else x.split('.'))]
        for i in (0, -1):
            if fields and not fields[i]:
                fields.pop(i)

        for i, f in enumerate(fields):
            if not f.startswith('{'):
                fields[i] = _from_user_input(f)
                continue
            assert f.endswith('}'), f'No closing brace for {f} in {fields}'
            fields[i] = {k: list(map(_from_user_input, k.split('.'))) for k in f[1:-1].split(',')}

        return traverse_obj(info_dict, fields, traverse_string=True)

    def get_value(mdict):
        # Object traversal
        value = _traverse_infodict(mdict['fields'])
        # Negative
        if mdict['negate']:
            value = float_or_none(value)
            if value is not None:
                value *= -1
        # Do maths
        offset_key = mdict['maths']
        if offset_key:
            value = float_or_none(value)
            operator = None
            while offset_key:
                item = re.match(
                    MATH_FIELD_RE if operator else MATH_OPERATORS_RE,
                    offset_key).group(0)
                offset_key = offset_key[len(item):]
                if operator is None:
                    operator = MATH_FUNCTIONS[item]
                    continue
                item, multiplier = (item[1:], -1) if item[0] == '-' else (item, 1)
                offset = float_or_none(item)
                if offset is None:
                    offset = float_or_none(_traverse_infodict(item))
                try:
                    value = operator(value, multiplier * offset)
                except (TypeError, ZeroDivisionError):
                    return None
                operator = None
        # Datetime formatting
        if mdict['strf_format']:
            value = strftime_or_none(value, mdict['strf_format'].replace('\\,', ','))

        # XXX: Workaround for https://github.com/yt-dlp/yt-dlp/issues/4485
        if sanitize and value == '':
            value = None
        return value

    na = self.params.get('outtmpl_na_placeholder', 'NA')

    def filename_sanitizer(key, value, restricted=self.params.get('restrictfilenames')):
        return sanitize_filename(str(value), restricted=restricted, is_id=(
            bool(re.search(r'(^|[_.])id(\.|$)', key))
            if 'filename-sanitization' in self.params['compat_opts']
            else NO_DEFAULT))

    sanitizer = sanitize if callable(sanitize) else filename_sanitizer
    sanitize = bool(sanitize)

    def _dumpjson_default(obj):
        if isinstance(obj, (set, LazyList)):
            return list(obj)
        return repr(obj)

    class _ReplacementFormatter(string.Formatter):
        def get_field(self, field_name, args, kwargs):
            if field_name.isdigit():
                return args[0], -1
            raise ValueError('Unsupported field')

    replacement_formatter = _ReplacementFormatter()

    def create_key(outer_mobj):
        if not outer_mobj.group('has_key'):
            return outer_mobj.group(0)
        key = outer_mobj.group('key')
        mobj = re.match(INTERNAL_FORMAT_RE, key)
        value, replacement, default, last_field = None, None, na, ''
        while mobj:
            mobj = mobj.groupdict()
            default = mobj['default'] if mobj['default'] is not None else default
            value = get_value(mobj)
            last_field, replacement = mobj['fields'], mobj['replacement']
            if value is None and mobj['alternate']:
                mobj = re.match(INTERNAL_FORMAT_RE, mobj['remaining'][1:])
            else:
                break

        if None not in (value, replacement):
            try:
                value = replacement_formatter.format(replacement, value)
            except ValueError:
                value, default = None, na

        fmt = outer_mobj.group('format')
        if fmt == 's' and last_field in field_size_compat_map.keys() and isinstance(value, int):
            fmt = f'0{field_size_compat_map[last_field]:d}d'

        flags = outer_mobj.group('conversion') or ''
        str_fmt = f'{fmt[:-1]}s'
        if value is None:
            value, fmt = default, 's'
        elif fmt[-1] == 'l':  # list
            delim = '\n' if '#' in flags else ', '
            value, fmt = delim.join(map(str, variadic(value, allowed_types=(str, bytes)))), str_fmt
        elif fmt[-1] == 'j':  # json
            value, fmt = json.dumps(
                value, default=_dumpjson_default,
                indent=4 if '#' in flags else None, ensure_ascii='+' not in flags), str_fmt
        elif fmt[-1] == 'h':  # html
            value, fmt = escapeHTML(str(value)), str_fmt
        elif fmt[-1] == 'q':  # quoted
            value = map(str, variadic(value) if '#' in flags else [value])
            value, fmt = ' '.join(map(compat_shlex_quote, value)), str_fmt
        elif fmt[-1] == 'B':  # bytes
            value = f'%{str_fmt}'.encode() % str(value).encode()
            value, fmt = value.decode('utf-8', 'ignore'), 's'
        elif fmt[-1] == 'U':  # unicode normalized
            value, fmt = unicodedata.normalize(
                # "+" = compatibility equivalence, "#" = NFD
                'NF%s%s' % ('K' if '+' in flags else '', 'D' if '#' in flags else 'C'),
                value), str_fmt
        elif fmt[-1] == 'D':  # decimal suffix
            num_fmt, fmt = fmt[:-1].replace('#', ''), 's'
            value = format_decimal_suffix(value, f'%{num_fmt}f%s' if num_fmt else '%d%s',
                                          factor=1024 if '#' in flags else 1000)
        elif fmt[-1] == 'S':  # filename sanitization
            value, fmt = filename_sanitizer(last_field, value, restricted='#' in flags), str_fmt
        elif fmt[-1] == 'c':
            if value:
                value = str(value)[0]
            else:
                fmt = str_fmt
        elif fmt[-1] not in 'rsa':  # numeric
            value = float_or_none(value)
            if value is None:
                value, fmt = default, 's'

        if sanitize:
            # If value is an object, sanitize might convert it to a string
            # So we convert it to repr first
            if fmt[-1] == 'r':
                value, fmt = repr(value), str_fmt
            elif fmt[-1] == 'a':
                value, fmt = ascii(value), str_fmt
            if fmt[-1] in 'csra':
                value = sanitizer(last_field, value)

        key = '%s\0%s' % (key.replace('%', '%\0'), outer_mobj.group('format'))
        TMPL_DICT[key] = value
        return '{prefix}%({key}){fmt}'.format(key=key, fmt=fmt, prefix=outer_mobj.group('prefix'))

    return EXTERNAL_FORMAT_RE.sub(create_key, outtmpl), TMPL_DICT

def shell_quote(args):
    quoted_args = []
    encoding = get_filesystem_encoding()
    for a in args:
        if isinstance(a, bytes):
            # We may get a filename encoded with 'encodeFilename'
            a = a.decode(encoding)
        quoted_args.append(compat_shlex_quote(a))
    return ' '.join(quoted_args)

def __post_init_code(self, raw_code: str, request: HttpRequest):
    if not raw_code:
        LOGGER.warning("Missing authorization code")
        raise TokenError("invalid_grant")

    allowed_redirect_urls = self.provider.redirect_uris.split()
    # At this point, no provider should have a blank redirect_uri, in case they do
    # this will check an empty array and raise an error
    try:
        if not any(fullmatch(x, self.redirect_uri) for x in allowed_redirect_urls):
            LOGGER.warning(
                "Invalid redirect uri (regex comparison)",
                redirect_uri=self.redirect_uri,
                expected=allowed_redirect_urls,
            )
            Event.new(
                EventAction.CONFIGURATION_ERROR,
                message="Invalid redirect URI used by provider",
                provider=self.provider,
                redirect_uri=self.redirect_uri,
                expected=allowed_redirect_urls,
            ).from_http(request)
            raise TokenError("invalid_client")
    except RegexError as exc:
        LOGGER.info("Failed to parse regular expression, checking directly", exc=exc)
        if not any(x == self.redirect_uri for x in allowed_redirect_urls):
            LOGGER.warning(
                "Invalid redirect uri (strict comparison)",
                redirect_uri=self.redirect_uri,
                expected=allowed_redirect_urls,
            )
            Event.new(
                EventAction.CONFIGURATION_ERROR,
                message="Invalid redirect_uri configured",
                provider=self.provider,
            ).from_http(request)
            raise TokenError("invalid_client")

    self.authorization_code = AuthorizationCode.objects.filter(code=raw_code).first()
    if not self.authorization_code:
        LOGGER.warning("Code does not exist", code=raw_code)
        raise TokenError("invalid_grant")

    if self.authorization_code.is_expired:
        LOGGER.warning(
            "Code is expired",
            token=raw_code,
        )
        raise TokenError("invalid_grant")

    if self.authorization_code.provider != self.provider or self.authorization_code.is_expired:
        LOGGER.warning("Invalid code: invalid client or code has expired")
        raise TokenError("invalid_grant")

    # Validate PKCE parameters.
    if self.code_verifier:
        if self.authorization_code.code_challenge_method == PKCE_METHOD_S256:
            new_code_challenge = (
                urlsafe_b64encode(sha256(self.code_verifier.encode("ascii")).digest())
                .decode("utf-8")
                .replace("=", "")
            )
        else:
            new_code_challenge = self.code_verifier

        if new_code_challenge != self.authorization_code.code_challenge:
            LOGGER.warning("Code challenge not matching")
            raise TokenError("invalid_grant")

def download_file(self, file_id, project: Project):
    rate_limited = ratelimits.is_limited(
        project=project,
        key=f"rl:ArtifactLookupEndpoint:download:{file_id}:{project.id}",
        limit=10,
    )
    if rate_limited:
        logger.info(
            "notification.rate_limited",
            extra={"project_id": project.id, "file_id": file_id},
        )
        return HttpResponse({"Too many download requests"}, status=429)

    file = File.objects.filter(id=file_id).first()

    if file is None:
        raise Http404

    try:
        fp = file.getfile()
        response = StreamingHttpResponse(
            iter(lambda: fp.read(4096), b""), content_type="application/octet-stream"
        )
        response["Content-Length"] = file.size
        response["Content-Disposition"] = f'attachment; filename="{file.name}"'
        return response
    except OSError:
        raise Http404

def download(self, debug_file_id, project):
    rate_limited = ratelimits.is_limited(
        project=project,
        key=f"rl:DSymFilesEndpoint:download:{debug_file_id}:{project.id}",
        limit=10,
    )
    if rate_limited:
        logger.info(
            "notification.rate_limited",
            extra={"project_id": project.id, "project_debug_file_id": debug_file_id},
        )
        return HttpResponse({"Too many download requests"}, status=403)

    debug_file = ProjectDebugFile.objects.filter(id=debug_file_id).first()

    if debug_file is None:
        raise Http404

    try:
        fp = debug_file.file.getfile()
        response = StreamingHttpResponse(
            iter(lambda: fp.read(4096), b""), content_type="application/octet-stream"
        )
        response["Content-Length"] = debug_file.file.size
        response["Content-Disposition"] = 'attachment; filename="{}{}"'.format(
            posixpath.basename(debug_file.debug_id),
            debug_file.file_extension,
        )
        return response
    except OSError:
        raise Http404

@functools.wraps(func)
def allow_cors_options_wrapper(self, request: Request, *args, **kwargs):
    if request.method == "OPTIONS":
        response = HttpResponse(status=200)
        response["Access-Control-Max-Age"] = "3600"  # don't ask for options again for 1 hour
    else:
        response = func(self, request, *args, **kwargs)

    allow = ", ".join(self._allowed_methods())
    response["Allow"] = allow
    response["Access-Control-Allow-Methods"] = allow
    response["Access-Control-Allow-Headers"] = (
        "X-Sentry-Auth, X-Requested-With, Origin, Accept, "
        "Content-Type, Authentication, Authorization, Content-Encoding, "
        "sentry-trace, baggage, X-CSRFToken"
    )
    response["Access-Control-Expose-Headers"] = "X-Sentry-Error, Retry-After"

    if request.META.get("HTTP_ORIGIN") == "null":
        origin = "null"  # if ORIGIN header is explicitly specified as 'null' leave it alone
    else:
        origin = origin_from_request(request)

    if origin is None or origin == "null":
        response["Access-Control-Allow-Origin"] = "*"
    else:
        response["Access-Control-Allow-Origin"] = origin

    # If the requesting origin is a subdomain of
    # the application's base-hostname we should allow cookies
    # to be sent.
    basehost = options.get("system.base-hostname")
    if basehost and origin:
        if origin.endswith(basehost):
            response["Access-Control-Allow-Credentials"] = "true"

    return response

@classmethod
def is_csrf_token_valid(cls, user_id: Optional[str], token: str) -> bool:
    """Validates a given CSRF token.

    Args:
        user_id: str|None. The user_id to validate the CSRF token against.
        token: str. The CSRF token to validate.

    Returns:
        bool. Whether the given CSRF token is valid.
    """
    try:
        parts = token.split('/')
        if len(parts) != 2:
            return False

        issued_on = int(parts[0])
        age = cls._get_current_time() - issued_on
        if age > cls._CSRF_TOKEN_AGE_SECS:
            return False

        authentic_token = cls._create_token(user_id, issued_on)
        if authentic_token == token:
            return True

        return False
    except Exception:
        return False

def get_result_from_sqldb(
    db: SQLDatabase, cmd: str
) -> Union[str, List[Dict[str, Any]], Dict[str, Any]]:
    result = db._execute(cmd, fetch="all")  # type: ignore
    if isinstance(result, list):
        return [{k: _try_eval(v) for k, v in dict(d._asdict()).items()} for d in result]
    else:
        return {
            k: _try_eval(v) for k, v in dict(result._asdict()).items()  # type: ignore
        }

def parse(self, text: str) -> Dict[str, List[Any]]:
    # Try to find XML string within triple backticks
    match = re.search(r"```(xml)?(.*)```", text, re.DOTALL)
    if match is not None:
        # If match found, use the content within the backticks
        text = match.group(2)
    encoding_match = self.encoding_matcher.search(text)
    if encoding_match:
        text = encoding_match.group(2)

    text = text.strip()
    try:
        root = ET.fromstring(text)
        return self._root_to_dict(root)

    except ET.ParseError as e:
        msg = f"Failed to parse XML format from completion {text}. Got: {e}"
        raise OutputParserException(msg, llm_output=text) from e

