def get_knowledge_base_name(self, kb_ids):
    kb_ids_str = ','.join("'{}'".format(str(x)) for x in kb_ids)
    query = "SELECT user_id, kb_id, kb_name FROM KnowledgeBase WHERE kb_id IN ({}) AND deleted = 0".format(kb_ids_str)
    return self.execute_query_(query, (), fetch=True)

def applyAttributes(mjml_element):
    if len(mjml_element) == 0:
        return {}
    def parse(_mjml, parentMjClass='', *, template_dir):
        tagName = _mjml.name
        is_comment = not isinstance(tagName, str)
        if is_comment:
            # XML comment: <cyfunction Comment at 0x…>
            # (this needs to be extended when "keepComments" should be implemented)
            return None
        attributes = _mjml.attrs
        children = [child for child in _mjml]
        classes = ignore_empty(attributes.get('mj-class', '').split(' '))

        # upstream parses text contents (+ comments) in mjml-parser-xml/index.js
        content = _mjml.decode_contents(formatter=None)

        attributesClasses = {}
        for css_class in classes:
            mjClassValues = globalDatas.classes.get(css_class)
            if mjClassValues:
                attributesClasses.update(mjClassValues)

        parent_mj_classes = ignore_empty(parentMjClass.split(' '))
        def default_attr_classes(value):
            return globalDatas.classesDefault.get(value, {}).get(tagName, {})
        defaultAttributesForClasses = merge_dicts(*map(default_attr_classes, parent_mj_classes))
        nextParentMjClass = attributes.get('mj-class', parentMjClass)

        _attrs_omit = omit(attributes, 'mj-class')
        _returned_attributes = merge_dicts(
            globalDatas.defaultAttributes.get(tagName, {}),
            attributesClasses,
            defaultAttributesForClasses,
            _attrs_omit,
        )

        if tagName == 'mj-include':
            mj_include_subtree = handle_include(attributes['path'],
                                                parse_mjml=parse,
                                                template_dir=template_dir)
            return mj_include_subtree
        result = {
            'tagName': tagName,
            'content': content,
            'attributes': _returned_attributes,
            'globalAttributes': globalDatas.defaultAttributes.get('mj-all', {}).copy(),
            'children': [], # will be set afterwards
        }
        _parse_mjml = lambda mjml: parse(mjml, nextParentMjClass, template_dir=template_dir)
        for child_result in _map_to_tuple(children, _parse_mjml, filter_none=True):
            if isinstance(child_result, (tuple, list)):
                result['children'].extend(child_result)
            else:
                result['children'].append(child_result)
        return result

    return parse(mjml_element, template_dir=template_dir)

def render_jinja2(template, context, trim=False, lstrip=False):
    """
    Render the template using Jinja2.
    """
    import traceback

    from django.conf import settings
    from jinja2 import Environment, TemplateSyntaxError

    environment = Environment(
        loader=PeeringManagerLoader(), trim_blocks=trim, lstrip_blocks=lstrip
    )
    environment.add_extension(IncludeTemplateExtension)
    for extension in settings.JINJA2_TEMPLATE_EXTENSIONS:
        environment.add_extension(extension)

    # Add custom filters to our environment
    environment.filters.update(FILTER_DICT)

    # Try rendering the template, return a message about syntax issues if there
    # are any
    try:
        jinja2_template = environment.from_string(template)
        return jinja2_template.render(**context)
    except TemplateSyntaxError as e:
        return f"Syntax error in template at line {e.lineno}: {e.message}"
    except Exception:
        return traceback.format_exc()

@classmethod
def get_social_auth(cls, provider, uid):
    try:
        return cls.objects.select_related("user").get(provider=provider, uid=uid)
    except cls.DoesNotExist:
        return None

@blueprint.route("/static/nbextensions/<dir>/<filename>")
def nbext(dir, filename):
    if not allowed():
        abort(401)
    for directory in server.nbextensions_directories:
        file = directory / dir / filename
        if file.exists():
            return send_from_directory(directory / dir, filename)
    return flask.Response("not found", status=404)

def secret_add(
    self,
    content: Dict[str, str],
    *,
    label: Optional[str] = None,
    description: Optional[str] = None,
    expire: Optional[datetime.datetime] = None,
    rotate: Optional[SecretRotate] = None,
    owner: Optional[str] = None,
) -> str:
    args: List[str] = []
    if label is not None:
        args.extend(['--label', label])
    if description is not None:
        args.extend(['--description', description])
    if expire is not None:
        args.extend(['--expire', expire.isoformat()])
    if rotate is not None:
        args += ['--rotate', rotate.value]
    if owner is not None:
        args += ['--owner', owner]
    # The content has already been validated with Secret._validate_content
    for k, v in content.items():
        args.append(f'{k}={v}')
    result = self._run('secret-add', *args, return_output=True)
    secret_id = typing.cast(str, result)
    return secret_id.strip()

def secret_set(
    self,
    id: str,
    *,
    content: Optional[Dict[str, str]] = None,
    label: Optional[str] = None,
    description: Optional[str] = None,
    expire: Optional[datetime.datetime] = None,
    rotate: Optional[SecretRotate] = None,
):
    args = [id]
    if label is not None:
        args.extend(['--label', label])
    if description is not None:
        args.extend(['--description', description])
    if expire is not None:
        args.extend(['--expire', expire.isoformat()])
    if rotate is not None:
        args += ['--rotate', rotate.value]
    if content is not None:
        # The content has already been validated with Secret._validate_content
        for k, v in content.items():
            args.append(f'{k}={v}')
    self._run_for_secret('secret-set', *args)
